UPDATE writing_characters SET comp_details_json = '[{"w": "夕", "h": "TỊCH", "d": "buổi chiều; buổi tối; lúc mặt trời lặn \nVD: 夕映 (ánh chiều tà), 夕陽 (ánh hoàng hôn), 旦夕 (sớm tối)"}, {"w": "卜", "h": "BẶC", "d": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "外夕", "source": "外"}, {"target": "外夕タ", "source": "外夕"}, {"target": "外卜", "source": "外"}], "nodes": [{"id": "外夕", "word": "夕", "hanViet": "TỊCH", "detail": "buổi chiều; buổi tối; lúc mặt trời lặn \nVD: 夕映 (ánh chiều tà), 夕陽 (ánh hoàng hôn), 旦夕 (sớm tối)"}, {"id": "外夕タ", "word": "タ", "hanViet": "TỊCH", "detail": "Bộ Tịch hoặc nét Katakana Ta"}, {"id": "外卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}]}'::jsonb WHERE character = '外' AND char_type = 'KANJI';
