UPDATE writing_characters SET comp_details_json = '[{"w": "幺", "h": "YÊU", "d": "Nhỏ.##Tục gọi số một là yêu, vì số một là số đầu (nhỏ); đánh tổ tôm, tài bàn, chắn, v.v. gọi nhất là yêu là vì đó.##Dị dạng của chữ [么].##Giản thể của chữ [么]."}, {"w": "彳", "h": "XÍCH", "d": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}, {"w": "夂", "h": "TRI", "d": "Theo sau mà đến. Ngày xưa dùng như chữ chung [終]. $ Chữ này [夂] viết không có nét ló ra phía trên góc bên trái, khác với chữ tuy [夊] có nét ló ra phía trên góc bên trái."}]'::jsonb, comp_graph_json = '{"links": [{"target": "後幺", "source": "後"}, {"target": "後幺糸", "source": "後幺"}, {"target": "後彳", "source": "後"}, {"target": "後夂", "source": "後"}], "nodes": [{"id": "後幺", "word": "幺", "hanViet": "YÊU", "detail": "Nhỏ.##Tục gọi số một là yêu, vì số một là số đầu (nhỏ); đánh tổ tôm, tài bàn, chắn, v.v. gọi nhất là yêu là vì đó.##Dị dạng của chữ [么].##Giản thể của chữ [么]."}, {"id": "後幺糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"id": "後彳", "word": "彳", "hanViet": "XÍCH", "detail": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}, {"id": "後夂", "word": "夂", "hanViet": "TRI, TRUY", "detail": "Theo sau mà đến. Ngày xưa dùng như chữ chung [終]. $ Chữ này [夂] viết không có nét ló ra phía trên góc bên trái, khác với chữ tuy [夊] có nét ló ra phía trên góc bên trái."}]}'::jsonb WHERE character = '後' AND char_type = 'KANJI';
