UPDATE writing_characters SET comp_details_json = '[{"w": "王", "h": "VƯƠNG", "d": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"w": "丶", "h": "CHỦ", "d": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}]'::jsonb, comp_graph_json = '{"links": [{"target": "主王", "source": "主"}, {"target": "主王一", "source": "主王"}, {"target": "主王土", "source": "主王"}, {"target": "主丶", "source": "主"}], "nodes": [{"id": "主王", "word": "王", "hanViet": "VƯƠNG, VƯỢNG", "detail": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"id": "主王一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "主王土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "主丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}]}'::jsonb WHERE character = '主' AND char_type = 'KANJI';
