UPDATE writing_characters SET comp_details_json = '[{"w": "艹", "h": "THẢO", "d": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"w": "化", "h": "HÓA", "d": "1. biến hóa; thay đổi; trở thành vật khác\nVD: 化身 (hóa thân), 変化 (biến hóa), 老化 (lão hóa)\n2. trời đất tự nhiên sinh ra vạn vật\nVD: 化育 (tạo hóa), 化工 (sinh dưỡng)\n3. các chất khác nhau kết hợp tạo thành chất mới\nVD: 化合 (phản ứng hóa học)\n4. dạy dỗ dẫn dắt; gây ảnh hưởng\nVD: 感化 (cảm hóa), 教化 (giáo hóa), 陶化 (uốn nắn)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "花艹", "source": "花"}, {"target": "花化", "source": "花"}, {"target": "花化亻", "source": "花化"}, {"target": "花化匕", "source": "花化"}], "nodes": [{"id": "花艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "花化", "word": "化", "hanViet": "HÓA", "detail": "1. biến hóa; thay đổi; trở thành vật khác\nVD: 化身 (hóa thân), 変化 (biến hóa), 老化 (lão hóa)\n2. trời đất tự nhiên sinh ra vạn vật\nVD: 化育 (tạo hóa), 化工 (sinh dưỡng)\n3. các chất khác nhau kết hợp tạo thành chất mới\nVD: 化合 (phản ứng hóa học)\n4. dạy dỗ dẫn dắt; gây ảnh hưởng\nVD: 感化 (cảm hóa), 教化 (giáo hóa), 陶化 (uốn nắn)"}, {"id": "花化亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "花化匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]}'::jsonb WHERE character = '花' AND char_type = 'KANJI';
