UPDATE writing_characters SET comp_details_json = '[{"w": "𠆢", "h": "", "d": ""}, {"w": "云", "h": "VÂN", "d": "Rằng. Như ngữ vân [語云] nhời quê nói rằng.##Vân vân v.v. nhời kể các sự còn dài, chỉ kể một hai cái làm mẫu. Như làng tôi có dệt vải, vóc, nhiễu, v.v.##Nhung nhúc. Như vạn vật vân vân [萬物云云] muôn vật nhung nhúc.##Giản thể của chữ [雲]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "会𠆢", "source": "会"}, {"target": "会云", "source": "会"}, {"target": "会云二", "source": "会云"}, {"target": "会云厶", "source": "会云"}], "nodes": [{"id": "会𠆢", "word": "𠆢", "hanViet": "", "detail": ""}, {"id": "会云", "word": "云", "hanViet": "VÂN", "detail": "Rằng. Như ngữ vân [語云] nhời quê nói rằng.##Vân vân v.v. nhời kể các sự còn dài, chỉ kể một hai cái làm mẫu. Như làng tôi có dệt vải, vóc, nhiễu, v.v.##Nhung nhúc. Như vạn vật vân vân [萬物云云] muôn vật nhung nhúc.##Giản thể của chữ [雲]."}, {"id": "会云二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "会云厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}]}'::jsonb WHERE character = '会' AND char_type = 'KANJI';
