UPDATE writing_characters SET comp_details_json = '[{"w": "乍", "h": "SẠ", "d": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "作乍", "source": "作"}, {"target": "作乍𠂉", "source": "作乍"}, {"target": "作乍二", "source": "作乍"}, {"target": "作乍丨", "source": "作乍"}, {"target": "作亻", "source": "作"}], "nodes": [{"id": "作乍", "word": "乍", "hanViet": "SẠ", "detail": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"id": "作乍𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "作乍二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "作乍丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "作亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}]}'::jsonb WHERE character = '作' AND char_type = 'KANJI';
