UPDATE writing_characters SET comp_details_json = '[{"w": "也", "h": "DÃ", "d": "Vậy, nhời nói hết câu. Như nghĩa giả nghi dã [義者宜也] nghĩa, ấy là sự nên thế thì làm vậy.##Có chỗ dùng làm lời mở đầu. Như dã tri hương tín nhật ưng sơ [也知鄉信日應疎] vậy biết tin làng ngày phải thưa."}, {"w": "土", "h": "THỔ", "d": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "地也", "source": "地"}, {"target": "地土", "source": "地"}], "nodes": [{"id": "地也", "word": "也", "hanViet": "DÃ", "detail": "Vậy, nhời nói hết câu. Như nghĩa giả nghi dã [義者宜也] nghĩa, ấy là sự nên thế thì làm vậy.##Có chỗ dùng làm lời mở đầu. Như dã tri hương tín nhật ưng sơ [也知鄉信日應疎] vậy biết tin làng ngày phải thưa."}, {"id": "地土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}]}'::jsonb WHERE character = '地' AND char_type = 'KANJI';
