UPDATE writing_characters SET comp_details_json = '[{"w": "歹", "h": "NGẠT", "d": "Xương tàn.##Tục đọc là chữ đãi. Tồi, xấu."}, {"w": "匕", "h": "CHỦY", "d": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]'::jsonb, comp_graph_json = '{"links": [{"target": "死歹", "source": "死"}, {"target": "死歹夕", "source": "死歹"}, {"target": "死歹夕タ", "source": "死歹夕"}, {"target": "死歹一", "source": "死歹"}, {"target": "死匕", "source": "死"}], "nodes": [{"id": "死歹", "word": "歹", "hanViet": "NGẠT, ĐÃI", "detail": "Xương tàn.##Tục đọc là chữ đãi. Tồi, xấu."}, {"id": "死歹夕", "word": "夕", "hanViet": "TỊCH", "detail": "buổi chiều; buổi tối; lúc mặt trời lặn \nVD: 夕映 (ánh chiều tà), 夕陽 (ánh hoàng hôn), 旦夕 (sớm tối)"}, {"id": "死歹夕タ", "word": "タ", "hanViet": "TỊCH", "detail": "Bộ Tịch hoặc nét Katakana Ta"}, {"id": "死歹一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "死匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]}'::jsonb WHERE character = '死' AND char_type = 'KANJI';
