UPDATE writing_characters SET comp_details_json = '[{"w": "占", "h": "CHIÊM", "d": "1. bói toán; xem bói\nVD: 占星 (bói sao), 占卜 (bói toán)\n2. chiếm giữ; chiếm lĩnh\nVD: 占領 (chiếm đóng), 占有 (sở hữu)"}, {"w": "广", "h": "NGHIỄM", "d": "Mái nhà. Cũng đọc là yểm.##Giản thể của chữ [廣]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "店占", "source": "店"}, {"target": "店占口", "source": "店占"}, {"target": "店占卜", "source": "店占"}, {"target": "店广", "source": "店"}], "nodes": [{"id": "店占", "word": "占", "hanViet": "CHIÊM, CHIẾM", "detail": "1. bói toán; xem bói\nVD: 占星 (bói sao), 占卜 (bói toán)\n2. chiếm giữ; chiếm lĩnh\nVD: 占領 (chiếm đóng), 占有 (sở hữu)"}, {"id": "店占口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "店占卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "店广", "word": "广", "hanViet": "NGHIỄM, YỂM, QUẢNG, QUÁNG", "detail": "Mái nhà. Cũng đọc là yểm.##Giản thể của chữ [廣]."}]}'::jsonb WHERE character = '店' AND char_type = 'KANJI';
