UPDATE writing_characters SET comp_details_json = '[{"w": "尸", "h": "THI", "d": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"w": "至", "h": "CHÍ", "d": "1. hết mức; cực kỳ\nVD: 至言 (lời nói chí lý), 至急 (khẩn cấp)\n2. đến; tới; đạt đến\nVD: 乃至 (cho đến), 必至 (tất yếu)\n3. ngày chí (ngày mặt trời đạt đến điểm cực)\nVD: 夏至 (hạ chí), 冬至 (đông chí)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "屋尸", "source": "屋"}, {"target": "屋至", "source": "屋"}, {"target": "屋至一", "source": "屋至"}, {"target": "屋至厶", "source": "屋至"}, {"target": "屋至土", "source": "屋至"}], "nodes": [{"id": "屋尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "屋至", "word": "至", "hanViet": "CHÍ", "detail": "1. hết mức; cực kỳ\nVD: 至言 (lời nói chí lý), 至急 (khẩn cấp)\n2. đến; tới; đạt đến\nVD: 乃至 (cho đến), 必至 (tất yếu)\n3. ngày chí (ngày mặt trời đạt đến điểm cực)\nVD: 夏至 (hạ chí), 冬至 (đông chí)"}, {"id": "屋至一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "屋至厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "屋至土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}]}'::jsonb WHERE character = '屋' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "广", "h": "NGHIỄM", "d": "Mái nhà. Cũng đọc là yểm.##Giản thể của chữ [廣]."}, {"w": "廿", "h": "NHẬP", "d": "Hai mươi. Như nhập bát tinh tú [廿八星宿] hai mươi tám sao, tức \"Nhị thập bát tú\" [二十八宿]. $ Ta quen đọc là chữ chấp."}, {"w": "又", "h": "HỰU", "d": "lại; hơn nữa; lại một lần nữa"}]'::jsonb, comp_graph_json = '{"links": [{"target": "度广", "source": "度"}, {"target": "度廿", "source": "度"}, {"target": "度廿十", "source": "度廿"}, {"target": "度廿十一", "source": "度廿十"}, {"target": "度廿十丨", "source": "度廿十"}, {"target": "度又", "source": "度"}], "nodes": [{"id": "度广", "word": "广", "hanViet": "NGHIỄM, YỂM, QUẢNG, QUÁNG", "detail": "Mái nhà. Cũng đọc là yểm.##Giản thể của chữ [廣]."}, {"id": "度廿", "word": "廿", "hanViet": "NHẬP, CHẤP", "detail": "Hai mươi. Như nhập bát tinh tú [廿八星宿] hai mươi tám sao, tức \"Nhị thập bát tú\" [二十八宿]. $ Ta quen đọc là chữ chấp."}, {"id": "度廿十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "度廿十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "度廿十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "度又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}]}'::jsonb WHERE character = '度' AND char_type = 'KANJI';
