UPDATE writing_characters SET comp_details_json = '[{"w": "云", "h": "VÂN", "d": "Rằng. Như ngữ vân [語云] nhời quê nói rằng.##Vân vân v.v. nhời kể các sự còn dài, chỉ kể một hai cái làm mẫu. Như làng tôi có dệt vải, vóc, nhiễu, v.v.##Nhung nhúc. Như vạn vật vân vân [萬物云云] muôn vật nhung nhúc.##Giản thể của chữ [雲]."}, {"w": "車", "h": "XA", "d": "1. bánh xe\nVD: 滑車 (ròng rọc), 風車 (cối xay gió)\n2. phương tiện di chuyển bằng bánh xe\nVD: 車馬 (xe ngựa), 電車 (tàu điện)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "転云", "source": "転"}, {"target": "転云二", "source": "転云"}, {"target": "転云厶", "source": "転云"}, {"target": "転車", "source": "転"}], "nodes": [{"id": "転云", "word": "云", "hanViet": "VÂN", "detail": "Rằng. Như ngữ vân [語云] nhời quê nói rằng.##Vân vân v.v. nhời kể các sự còn dài, chỉ kể một hai cái làm mẫu. Như làng tôi có dệt vải, vóc, nhiễu, v.v.##Nhung nhúc. Như vạn vật vân vân [萬物云云] muôn vật nhung nhúc.##Giản thể của chữ [雲]."}, {"id": "転云二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "転云厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "転車", "word": "車", "hanViet": "XA", "detail": "1. bánh xe\nVD: 滑車 (ròng rọc), 風車 (cối xay gió)\n2. phương tiện di chuyển bằng bánh xe\nVD: 車馬 (xe ngựa), 電車 (tàu điện)"}]}'::jsonb WHERE character = '転' AND char_type = 'KANJI';
