UPDATE writing_characters SET comp_details_json = '[{"w": "央", "h": "ƯƠNG", "d": "1. chính giữa; trung tâm\nVD: 震央 (trung tâm của động đất), 中央 (trung ương)\n2. cạn kiệt; dừng; kết thúc\nVD: 未央 (chưa kết thúc)"}, {"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "映央", "source": "映"}, {"target": "映日", "source": "映"}], "nodes": [{"id": "映央", "word": "央", "hanViet": "ƯƠNG", "detail": "1. chính giữa; trung tâm\nVD: 震央 (trung tâm của động đất), 中央 (trung ương)\n2. cạn kiệt; dừng; kết thúc\nVD: 未央 (chưa kết thúc)"}, {"id": "映日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]}'::jsonb WHERE character = '映' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "厶", "h": "KHƯ", "d": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"w": "禾", "h": "HÒA", "d": "Lúa, lúa chưa cắt rơm rạ đi gọi là hòa."}]'::jsonb, comp_graph_json = '{"links": [{"target": "私厶", "source": "私"}, {"target": "私禾", "source": "私"}], "nodes": [{"id": "私厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "私禾", "word": "禾", "hanViet": "HÒA", "detail": "Lúa, lúa chưa cắt rơm rạ đi gọi là hòa."}]}'::jsonb WHERE character = '私' AND char_type = 'KANJI';
