UPDATE writing_characters SET comp_details_json = '[{"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"w": "也", "h": "DÃ", "d": "Vậy, nhời nói hết câu. Như nghĩa giả nghi dã [義者宜也] nghĩa, ấy là sự nên thế thì làm vậy.##Có chỗ dùng làm lời mở đầu. Như dã tri hương tín nhật ưng sơ [也知鄉信日應疎] vậy biết tin làng ngày phải thưa."}]'::jsonb, comp_graph_json = '{"links": [{"target": "他亻", "source": "他"}, {"target": "他也", "source": "他"}], "nodes": [{"id": "他亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "他也", "word": "也", "hanViet": "DÃ", "detail": "Vậy, nhời nói hết câu. Như nghĩa giả nghi dã [義者宜也] nghĩa, ấy là sự nên thế thì làm vậy.##Có chỗ dùng làm lời mở đầu. Như dã tri hương tín nhật ưng sơ [也知鄉信日應疎] vậy biết tin làng ngày phải thưa."}]}'::jsonb WHERE character = '他' AND char_type = 'KANJI';
