UPDATE writing_characters SET comp_details_json = '[{"w": "六", "h": "LỤC", "d": "số sáu\nVD: 六書 (lục thư - sáu phép phân loại chữ Hán), 六法 (lục pháp - sáu bộ luật cơ bản trong hệ thống pháp luật Nhật)"}, {"w": "父", "h": "PHỤ", "d": "1. cha \nVD: 父君 (phụ thân), 父兄 (phụ huynh)\n2. người đàn ông cao tuổi\nVD: 父老 (bô lão), 漁父 (ông lão đánh cá)\n3. người đàn ông lớn tuổi trong họ hàng\nVD: 伯父 (bác), 叔父 (chú)\n4. kính ngữ dành cho nam giới \nVD: 尼父 (tôn xưng dành cho vị tăng ni)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "交六", "source": "交"}, {"target": "交父", "source": "交"}, {"target": "交父ハ", "source": "交父"}, {"target": "交父乂", "source": "交父"}], "nodes": [{"id": "交六", "word": "六", "hanViet": "LỤC", "detail": "số sáu\nVD: 六書 (lục thư - sáu phép phân loại chữ Hán), 六法 (lục pháp - sáu bộ luật cơ bản trong hệ thống pháp luật Nhật)"}, {"id": "交父", "word": "父", "hanViet": "PHỤ, PHỦ", "detail": "1. cha \nVD: 父君 (phụ thân), 父兄 (phụ huynh)\n2. người đàn ông cao tuổi\nVD: 父老 (bô lão), 漁父 (ông lão đánh cá)\n3. người đàn ông lớn tuổi trong họ hàng\nVD: 伯父 (bác), 叔父 (chú)\n4. kính ngữ dành cho nam giới \nVD: 尼父 (tôn xưng dành cho vị tăng ni)"}, {"id": "交父ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "交父乂", "word": "乂", "hanViet": "NGHỆ", "detail": "Trị, cai trị được dân yên gọi là nghệ.##Tài giỏi. Như tuấn nghệ tại quan [俊乂在官] người hiền tài làm quan."}]}'::jsonb WHERE character = '交' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "小", "h": "TIỂU", "d": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"w": "兀", "h": "NGỘT", "d": "Cao mà bằng đầu. Bây giờ quen gọi là cao chót. Như đột ngột [突兀] chót vót.##Ngây ngất. Như hằng ngột ngột dĩ cùng niên [恆兀兀以窮年] thường lo đau đáu suốt năm.##Lại là lời trợ ngữ, trong các bài từ nhà Nguyên họ hay dùng.##Ngột giả [兀者] kẻ bị chặt gẫy một chân."}]'::jsonb, comp_graph_json = '{"links": [{"target": "光小", "source": "光"}, {"target": "光兀", "source": "光"}, {"target": "光兀一", "source": "光兀"}, {"target": "光兀儿", "source": "光兀"}], "nodes": [{"id": "光小", "word": "小", "hanViet": "TIỂU", "detail": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"id": "光兀", "word": "兀", "hanViet": "NGỘT", "detail": "Cao mà bằng đầu. Bây giờ quen gọi là cao chót. Như đột ngột [突兀] chót vót.##Ngây ngất. Như hằng ngột ngột dĩ cùng niên [恆兀兀以窮年] thường lo đau đáu suốt năm.##Lại là lời trợ ngữ, trong các bài từ nhà Nguyên họ hay dùng.##Ngột giả [兀者] kẻ bị chặt gẫy một chân."}, {"id": "光兀一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "光兀儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}]}'::jsonb WHERE character = '光' AND char_type = 'KANJI';
