UPDATE writing_characters SET comp_details_json = '[{"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"w": "匕", "h": "CHỦY", "d": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]'::jsonb, comp_graph_json = '{"links": [{"target": "化亻", "source": "化"}, {"target": "化匕", "source": "化"}], "nodes": [{"id": "化亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "化匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]}'::jsonb WHERE character = '化' AND char_type = 'KANJI';
