UPDATE writing_characters SET comp_details_json = '[{"w": "戈", "h": "QUA", "d": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"w": "勹", "h": "BAO", "d": "Bọc."}]'::jsonb, comp_graph_json = '{"links": [{"target": "成戈", "source": "成"}, {"target": "成勹", "source": "成"}], "nodes": [{"id": "成戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "成勹", "word": "勹", "hanViet": "BAO", "detail": "Bọc."}]}'::jsonb WHERE character = '成' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "耂", "h": "", "d": ""}, {"w": "匕", "h": "CHỦY", "d": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]'::jsonb, comp_graph_json = '{"links": [{"target": "老耂", "source": "老"}, {"target": "老匕", "source": "老"}], "nodes": [{"id": "老耂", "word": "耂", "hanViet": "", "detail": ""}, {"id": "老匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]}'::jsonb WHERE character = '老' AND char_type = 'KANJI';
