UPDATE writing_characters SET comp_details_json = '[{"w": "𠫓", "h": "ĐỘT", "d": ""}, {"w": "月", "h": "NGUYỆT", "d": "1. thứ Hai\n2. mặt trăng \nVD: 月光 (ánh trăng), 満月 (trăng tròn)\n3. tháng\nVD: 歳月 (thời gian dài), 年月 (năm tháng) "}]'::jsonb, comp_graph_json = '{"links": [{"target": "育𠫓", "source": "育"}, {"target": "育𠫓厶", "source": "育𠫓"}, {"target": "育𠫓亠", "source": "育𠫓"}, {"target": "育月", "source": "育"}], "nodes": [{"id": "育𠫓", "word": "𠫓", "hanViet": "", "detail": ""}, {"id": "育𠫓厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "育𠫓亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "育月", "word": "月", "hanViet": "NGUYỆT", "detail": "1. thứ Hai\n2. mặt trăng \nVD: 月光 (ánh trăng), 満月 (trăng tròn)\n3. tháng\nVD: 歳月 (thời gian dài), 年月 (năm tháng) "}]}'::jsonb WHERE character = '育' AND char_type = 'KANJI';
