UPDATE writing_characters SET comp_details_json = '[{"w": "単", "h": "ĐƠN", "d": "1. không phức tạp; không lẫn tạp chất\nVD: 単調 (đơn điệu), 簡単 (đơn giản)\n2. một; một mình \nVD: 単独 (đơn độc), 単身 (đơn thân)\n3. áo một lớp; loại áo Kimono không có lớp lót\nVD: 単衣 (Kimono một lớp)\n4. đơn vị làm tiêu chuẩn\nVD: 単位 (đơn vị), 単元 (đơn vị bài học)"}, {"w": "戈", "h": "QUA", "d": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}]'::jsonb, comp_graph_json = '{"links": [{"target": "戦単", "source": "戦"}, {"target": "戦単十", "source": "戦単"}, {"target": "戦単十一", "source": "戦単十"}, {"target": "戦単十丨", "source": "戦単十"}, {"target": "戦単⺍", "source": "戦単"}, {"target": "戦単田", "source": "戦単"}, {"target": "戦戈", "source": "戦"}], "nodes": [{"id": "戦単", "word": "単", "hanViet": "ĐƠN", "detail": "1. không phức tạp; không lẫn tạp chất\nVD: 単調 (đơn điệu), 簡単 (đơn giản)\n2. một; một mình \nVD: 単独 (đơn độc), 単身 (đơn thân)\n3. áo một lớp; loại áo Kimono không có lớp lót\nVD: 単衣 (Kimono một lớp)\n4. đơn vị làm tiêu chuẩn\nVD: 単位 (đơn vị), 単元 (đơn vị bài học)"}, {"id": "戦単十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "戦単十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "戦単十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "戦単⺍", "word": "⺍", "hanViet": "", "detail": ""}, {"id": "戦単田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "戦戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}]}'::jsonb WHERE character = '戦' AND char_type = 'KANJI';
