UPDATE writing_characters SET comp_details_json = '[{"w": "其", "h": "KÌ", "d": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"w": "月", "h": "NGUYỆT", "d": "1. thứ Hai\n2. mặt trăng \nVD: 月光 (ánh trăng), 満月 (trăng tròn)\n3. tháng\nVD: 歳月 (thời gian dài), 年月 (năm tháng) "}]'::jsonb, comp_graph_json = '{"links": [{"target": "期其", "source": "期"}, {"target": "期月", "source": "期"}], "nodes": [{"id": "期其", "word": "其", "hanViet": "KÌ, KÍ, KI", "detail": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"id": "期月", "word": "月", "hanViet": "NGUYỆT", "detail": "1. thứ Hai\n2. mặt trăng \nVD: 月光 (ánh trăng), 満月 (trăng tròn)\n3. tháng\nVD: 歳月 (thời gian dài), 年月 (năm tháng) "}]}'::jsonb WHERE character = '期' AND char_type = 'KANJI';
