UPDATE writing_characters SET comp_details_json = '[{"w": "咸", "h": "HÀM", "d": "Khắp cả.##Đều, hết thẩy.##Một âm là giảm, cùng nghĩa với chữ giảm [減].##Giản thể của chữ [鹹]."}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "感咸", "source": "感"}, {"target": "感咸戊", "source": "感咸"}, {"target": "感咸戊戈", "source": "感咸戊"}, {"target": "感咸一", "source": "感咸"}, {"target": "感咸口", "source": "感咸"}, {"target": "感心", "source": "感"}], "nodes": [{"id": "感咸", "word": "咸", "hanViet": "HÀM, GIẢM", "detail": "Khắp cả.##Đều, hết thẩy.##Một âm là giảm, cùng nghĩa với chữ giảm [減].##Giản thể của chữ [鹹]."}, {"id": "感咸戊", "word": "戊", "hanViet": "MẬU", "detail": "Can Mậu [戊], can thứ năm trong mười can."}, {"id": "感咸戊戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "感咸一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "感咸口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủn