UPDATE writing_characters SET comp_details_json = '[{"w": "灬", "h": "HỎA", "d": "Một hình thức của bộ hỏa [火]."}, {"w": "埶", "h": "NGHỆ", "d": "Vốn là chữ nghệ [藝]. Cũng mượn làm chữ thế [勢]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "熱灬", "source": "熱"}, {"target": "熱埶", "source": "熱"}, {"target": "熱埶丸", "source": "熱埶"}, {"target": "熱埶丸九", "source": "熱埶丸"}, {"target": "熱埶丸丶", "source": "熱埶丸"}, {"target": "熱埶坴", "source": "熱埶"}, {"target": "熱埶坴土", "source": "熱埶坴"}, {"target": "熱埶坴圥", "source": "熱埶坴"}], "nodes": [{"id": "熱灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}, {"id": "熱埶", "word": "埶", "hanViet": "NGHỆ", "detail": "Vốn là chữ nghệ [藝]. Cũng mượn làm chữ thế [勢]."}, {"id": "熱埶丸", "word": "丸", "hanViet": "HOÀN", "detail": "1. một khối; toàn bộ; nguyên vẹn\nVD: 丸太 (khúc gỗ tròn), 丸裸 (trần trụi), 一丸 (một khối)\n2. tròn; vật tròn; viên\nVD: 丸剤 (thuốc viên), 丸薬 (thuốc hoàn), 砲丸 (đạn pháo)\n3. hậu tố sau tên riêng (người, chó, kiếm, tàu thuyền, v.v.)\nVD: 牛若丸 (Ushiwakamaru)"}, {"id": "熱埶丸九", "word": "九", "hanViet": "CỬU, CƯU", "detail": "1. số chín\nVD: 九曜 (chín vì sao), 九輪 (chín vòng trên đỉnh tháp Phật giáo)\n2. nhiều; vô số\nVD: 九死 (nguy hiểm đến mức gần chết), 九拝 (cúi lạy nhiều lần)"}, {"id": "熱埶丸丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "熱埶坴", "word": "坴", "hanViet": "LỤC", "detail": "clod of earth, land"}, {"id": "熱埶坴土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "熱埶坴圥", "word": "圥", "hanViet": "", "detail": "mushroom"}]}'::jsonb WHERE character = '熱' AND char_type = 'KANJI';
