UPDATE writing_characters SET comp_details_json = '[{"w": "頁", "h": "HIỆT", "d": "Đầu.##Một tờ giấy gọi là nhất hiệt [一頁]."}, {"w": "原", "h": "NGUYÊN", "d": "1. cánh đồng; vùng đất rộng và bằng phẳng\nVD: 原野 (đồng hoang), 草原 (thảo nguyên)\n2. nguồn gốc; khởi đầu; nguyên do \nVD: 原因 (nguyên nhân), 原始 (nguyên thủy)\n3. viết tắt của 原子力 (năng lượng hạt nhân)\nVD: 原発 (nhà máy điện hạt nhân)\n4. tha thứ; xá tội\nVD: 原宥 (tha thứ)\n5. tìm hiểu; tra xét"}]'::jsonb, comp_graph_json = '{"links": [{"target": "願頁", "source": "願"}, {"target": "願頁丆", "source": "願頁"}, {"target": "願頁貝", "source": "願頁"}, {"target": "願頁貝ハ", "source": "願頁貝"}, {"target": "願頁貝目", "source": "願頁貝"}, {"target": "願原", "source": "願"}, {"target": "願原厂", "source": "願原"}, {"target": "願原小", "source": "願原"}, {"target": "願原白", "source": "願原"}, {"target": "願原白ノ", "source": "願原白"}, {"target": "願原白日", "source": "願原白"}], "nodes": [{"id": "願頁", "word": "頁", "hanViet": "HIỆT", "detail": "Đầu.##Một tờ giấy gọi là nhất hiệt [一頁]."}, {"id": "願頁丆", "word": "丆", "hanViet": "", "detail": ""}, {"id": "願頁貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "願頁貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "願頁貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}, {"id": "願原", "word": "原", "hanViet": "NGUYÊN", "detail": "1. cánh đồng; vùng đất rộng và bằng phẳng\nVD: 原野 (đồng hoang), 草原 (thảo nguyên)\n2. nguồn gốc; khởi đầu; nguyên do \nVD: 原因 (nguyên nhân), 原始 (nguyên thủy)\n3. viết tắt của 原子力 (năng lượng hạt nhân)\nVD: 原発 (nhà máy điện hạt nhân)\n4. tha thứ; xá tội\nVD: 原宥 (tha thứ)\n5. tìm hiểu; tra xét"}, {"id": "願原厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "願原小", "word": "小", "hanViet": "TIỂU", "detail": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"id": "願原白", "word": "白", "hanViet": "BẠCH", "detail": "1. màu trắng \nVD: 白衣 (áo trắng), 紅白 (đỏ và trắng)\n2. làm cho trắng; tẩy trắng\nVD: 精白 (tinh luyện, làm trắng), 漂白 (tẩy trắng)\n3. sáng; rõ ràng; minh bạch\nVD: 白日 (ban ngày), 明白 (rõ ràng)\n4. trong sạch; không vẩn đục \nVD: 潔白 (trong sạch)\n5. trống trơn\nVD: 白紙 (giấy trắng), 空白 (khoảng trống)\n6. lời thoại\nVD: 科白 (lời thoại)\n7. nói ra; trình bày\nVD: 白状 (thú nhận), 建白 (kiến nghị)"}, {"id": "願原白ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "願原白日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]}'::jsonb WHERE character = '願' AND char_type = 'KANJI';
