UPDATE writing_characters SET comp_details_json = '[{"w": "乍", "h": "SẠ", "d": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "昨乍", "source": "昨"}, {"target": "昨乍𠂉", "source": "昨乍"}, {"target": "昨乍二", "source": "昨乍"}, {"target": "昨乍丨", "source": "昨乍"}, {"target": "昨日", "source": "昨"}], "nodes": [{"id": "昨乍", "word": "乍", "hanViet": "SẠ", "detail": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"id": "昨乍𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "昨乍二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "昨乍丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "昨日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (n