UPDATE writing_characters SET comp_details_json = '[{"w": "去", "h": "KHỨ", "d": "1. chết; qua đời\nVD: 死去 (qua đời), 逝去 (từ trần)\n2. rời đi; đi khỏi; rời khỏi \nVD: 去来 (đến và đi), 過去 (quá khứ) \n3. loại bỏ; lấy đi\nVD: 去勢 (thiến), 撤去 (tháo dỡ)\n4. thanh khứ (một trong bốn thanh của âm Hán)\nVD: 去声 (thanh khứ)"}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "法去", "word": "去", "hanViet": "KHỨ, KHU", "detail": "1. chết; qua đời\nVD: 死去 (qua đời), 逝去 (từ trần)\n2. rời đi; đi khỏi; rời khỏi \nVD: 去来 (đến và đi), 過去 (quá khứ) \n3. loại bỏ; lấy đi\nVD: 去勢 (thiến), 撤去 (tháo dỡ)\n4. thanh khứ (một trong bốn thanh của âm Hán)\nVD: 去声 (thanh khứ)"}, {"id": "法去厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "法去土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "法氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "法", "target": "法去"}, {"source": "法去", "target": "法去厶"}, {"source": "法去", "target": "法去土"}, {"source": "法", "target": "法氵"}]}'::jsonb WHERE character = '法' AND char_type = 'KANJI';
