UPDATE writing_characters SET comp_details_json = '[{"w": "口", "h": "KHẨU", "d": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"w": "乎", "h": "HỒ", "d": "Vậy, ôi, ư, rư ! Nhời nói có ý nghi hoặc. Như quân tử giả hồ [君子者乎] quân tử ấy ư ?##Tiếng gọi. Như Sâm hồ [參乎], người Sâm kia ơi !##Nhời nói tán thán. Như nguy nguy hồ [巍巍乎] cao vòi vọi vậy ôi !, tất dã chánh danh hồ ! [必也正名乎] ắt vậy phải chánh cái danh vậy ôi !##Chưng. Như sở cầu hồ tử [所求乎子] cầu chưng đạo làm con.##Một âm là hô. Nhời sót thương. Như [於] cùng nghĩa với chữ hô [呼]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "呼口", "source": "呼"}, {"target": "呼乎", "source": "呼"}, {"target": "呼乎ノ", "source": "呼乎"}, {"target": "呼乎丷", "source": "呼乎"}, {"target": "呼乎一", "source": "呼乎"}, {"target": "呼乎亅", "source": "呼乎"}], "nodes": [{"id": "呼口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "呼乎", "word": "乎", "hanViet": "HỒ, HÔ", "detail": "Vậy, ôi, ư, rư ! Nhời nói có ý nghi hoặc. Như quân tử giả hồ [君子者乎] quân tử ấy ư ?##Tiếng gọi. Như Sâm hồ [參乎], người Sâm kia ơi !##Nhời nói tán thán. Như nguy nguy hồ [巍巍乎] cao vòi vọi vậy ôi !, tất dã chánh danh hồ ! [必也正名乎] ắt vậy phải chánh cái danh vậy ôi !##Chưng. Như sở cầu hồ tử [所求乎子] cầu chưng đạo làm con.##Một âm là hô. Nhời sót thương. Như [於] cùng nghĩa với chữ hô [呼]."}, {"id": "呼乎ノ", "word": "ノ", "hanViet": 