UPDATE writing_characters SET comp_details_json = '[{"w": "甫", "h": "PHỦ", "d": "Tiếng gọi tôn quý của đàn ông. Như đức Khổng Tử gọi là Ni phủ [尼甫].##Tên chữ biểu hiệu, cho nên hỏi tên tự người ta thì nói là thai phủ [台甫].##Cha, mình nói đến cha người khác thì kêu là tôn phủ [尊甫].##Vừa mới. Như phủ nhập môn [甫入門] vừa bước vào cửa.##Lớn."}, {"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "捕甫", "word": "甫", "hanViet": "PHỦ", "detail": "Tiếng gọi tôn quý của đàn ông. Như đức Khổng Tử gọi là Ni phủ [尼甫].##Tên chữ biểu hiệu, cho nên hỏi tên tự người ta thì nói là thai phủ [台甫].##Cha, mình nói đến cha người khác thì kêu là tôn phủ [尊甫].##Vừa mới. Như phủ nhập môn [甫入門] vừa bước vào cửa.##Lớn."}, {"id": "捕甫用", "word": "用", "hanViet": "DỤNG", "detail": "1. dùng; sử dụng; làm cho có ích \nVD: 用意 (chuẩn bị), 使用 (sử dụng)\n2. cách dùng; mục đích sử dụng\nVD: 薬用 (dùng làm thuốc), 浴用 (dùng để tắm)\n3. tác dụng; hiệu quả\nVD: 作用 (tác dụng), 効用 (hiệu quả)\n4. đi đại tiểu tiện\nVD: 用便 (đi vệ sinh)\n5. bằng; nhờ vào\n6. chi phí hoặc vật dụng cần thiết\nVD: 用度 (chi phí), 費用 (chi phí)\n7. công việc phải làm\nVD: 用件 (việc cần bàn), 所用 (việc riêng)"}, {"id": "捕甫十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "捕甫十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "捕甫十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "捕甫丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "捕扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}], "links": [{"source": "捕", "target": "捕甫"}, {"source": "捕甫", "target": "捕甫用"}, {"source": "捕甫", "target": "捕甫十"}, {"source": "捕甫十", "target": "捕甫十一"}, {"source": "捕甫十", "target": "捕甫十丨"}, {"source": "捕甫", "target": "捕甫丶"}, {"source": "捕", "target": "捕扌"}]}'::jsonb WHERE character = '捕' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "貫", "h": "QUÁN", "d": "1. (ワン) kéo; giương cung hết mức\nVD: 貫弓 (giương cung)\n2. (カン) tập quán \nVD: 旧貫 (tập quán cũ)\n3. (カン) xuyên qua; làm đến cùng\nVD: 貫通 (xuyên suốt), 貫流 (chảy xuyên qua), 縦貫 (chạy dọc qua)\n4. (カン) hộ tịch; sổ hộ khẩu\nVD: 郷貫 (quê quán), 籍貫 (nguyên quán)\n5. (カン) đơn vị tiền tệ, trọng lượng hoặc bổng lộc; trong tiền tệ, bằng 1000 <i>mon</i> (đơn vị tiền cổ) ; trong trọng lượng, tương đương 3,75 kg; trong bổng lộc, bằng 10 <i>koku</i> (đơn vị đo lường sản lượng gạo cổ)"}, {"w": "忄", "h": "TÂM", "d": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "慣貫", "word": "貫", "hanViet": "QUÁN", "detail": "1. (ワン) kéo; giương cung hết mức\nVD: 貫弓 (giương cung)\n2. (カン) tập quán \nVD: 旧貫 (tập quán cũ)\n3. (カン) xuyên qua; làm đến cùng\nVD: 貫通 (xuyên suốt), 貫流 (chảy xuyên qua), 縦貫 (chạy dọc qua)\n4. (カン) hộ tịch; sổ hộ khẩu\nVD: 郷貫 (quê quán), 籍貫 (nguyên quán)\n5. (カン) đơn vị tiền tệ, trọng lượng hoặc bổng lộc; trong tiền tệ, bằng 1000 <i>mon</i> (đơn vị tiền cổ) ; trong trọng lượng, tương đương 3,75 kg; trong bổng lộc, bằng 10 <i>koku</i> (đơn vị đo lường sản lượng gạo cổ)"}, {"id": "慣貫毌", "word": "毌", "hanViet": "QUÁN", "detail": "mother radical variant (no.80)"}, {"id": "慣貫貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "慣貫貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "慣貫貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}, {"id": "慣忄", "word": "忄", "hanViet": "TÂM", "detail": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}], "links": [{"source": "慣", "target": "慣貫"}, {"source": "慣貫", "target": "慣貫毌"}, {"source": "慣貫", "target": "慣貫貝"}, {"source": "慣貫貝", "target": "慣貫貝ハ"}, {"source": "慣貫貝", "target": "慣貫貝目"}, {"source": "慣", "target": "慣忄"}]}'::jsonb WHERE character = '慣' AND char_type = 'KANJI';
