UPDATE writing_characters SET comp_details_json = '[{"w": "召", "h": "TRIỆU", "d": "1. gọi đến; mời \nVD: 召喚 (triệu hồi), 召集 (tập hợp), 徴召 (triệu tập theo lệnh)\n2. kính ngữ của các từ như 食う (ăn), 着る (mặc)"}, {"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "招召", "word": "召", "hanViet": "TRIỆU", "detail": "1. gọi đến; mời \nVD: 召喚 (triệu hồi), 召集 (tập hợp), 徴召 (triệu tập theo lệnh)\n2. kính ngữ của các từ như 食う (ăn), 着る (mặc)"}, {"id": "招召刀", "word": "刀", "hanViet": "ĐAO", "detail": "1. đao; kiếm; vật có lưỡi sắc\nVD: 刀剣 (đao kiếm), 短刀 (dao găm)\n2. tiền cổ hình đao của Trung Quốc\nVD: 刀銭 (tiền hình đao), 刀幣 (tiền tệ đao)"}, {"id": "招召口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "招扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}], "links": [{"source": "招", "target": "招召"}, {"source": "招召", "target": "招召刀"}, {"source": "招召", "target": "招召口"}, {"source": "招", "target": "招扌"}]}'::jsonb WHERE character = '招' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "乍", "h": "SẠ", "d": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"w": "殳", "h": "THÙ", "d": "Cái thù, một thứ đồ binh dài một trượng hai thước, không có mũi nhọn."}]'::jsonb, comp_graph_json = '{"links": [{"target": "段乍", "source": "段"}, {"target": "段乍𠂉", "source": "段乍"}, {"target": "段乍二", "source": "段乍"}, {"target": "段乍丨", "source": "段乍"}, {"target": "段殳", "source": "段"}, {"target": "段殳几", "source": "段殳"}, {"target": "段殳又", "source": "段殳"}], "nodes": [{"id": "段乍", "word": "乍", "hanViet": "SẠ", "detail": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"id": "段乍𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "段乍二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "段乍丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "段殳", "word": "殳", "hanViet": "THÙ", "detail": "Cái thù, một thứ đồ binh dài một trượng hai thước, không có mũi nhọn."}, {"id": "段殳几", "word": "几", "hanViet": "KỈ", "detail": "Cái ghế dựa.##Cái kỉ tre.##Giản thể của chữ [幾]."}, {"id": "段殳又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}]}'::jsonb WHERE character = '段' AND char_type = 'KANJI';
