UPDATE writing_characters SET comp_details_json = '[{"w": "化", "h": "HÓA", "d": "1. biến hóa; thay đổi; trở thành vật khác\nVD: 化身 (hóa thân), 変化 (biến hóa), 老化 (lão hóa)\n2. trời đất tự nhiên sinh ra vạn vật\nVD: 化育 (tạo hóa), 化工 (sinh dưỡng)\n3. các chất khác nhau kết hợp tạo thành chất mới\nVD: 化合 (phản ứng hóa học)\n4. dạy dỗ dẫn dắt; gây ảnh hưởng\nVD: 感化 (cảm hóa), 教化 (giáo hóa), 陶化 (uốn nắn)"}, {"w": "革", "h": "CÁCH", "d": "1. da; da thuộc \nVD: 皮革 (da thuộc)\n2. thay đổi; cải cách; làm mới\nVD: 革新 (đổi mới), 革命 (cách mạng), 改革 (cải cách)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "靴化", "word": "化", "hanViet": "HÓA", "detail": "1. biến hóa; thay đổi; trở thành vật khác\nVD: 化身 (hóa thân), 変化 (biến hóa), 老化 (lão hóa)\n2. trời đất tự nhiên sinh ra vạn vật\nVD: 化育 (tạo hóa), 化工 (sinh dưỡng)\n3. các chất khác nhau kết hợp tạo thành chất mới\nVD: 化合 (phản ứng hóa học)\n4. dạy dỗ dẫn dắt; gây ảnh hưởng\nVD: 感化 (cảm hóa), 教化 (giáo hóa), 陶化 (uốn nắn)"}, {"id": "靴化亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "靴化匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}, {"id": "靴革", "word": "革", "hanViet": "CÁCH, CỨC", "detail": "1. da; da thuộc \nVD: 皮革 (da thuộc)\n2. thay đổi; cải cách; làm mới\nVD: 革新 (đổi mới), 革命 (cách mạng), 改革 (cải cách)"}, {"id": "靴革中", "word": "中", "hanViet": "TRUNG, TRÚNG", "detail": "1. chính giữa\nVD: 中央 (trung ương), 中心 (trung tâm), 中核 (cốt lõi)\n2. bên trong phạm vi; phía trong\nVD: 意中 (trong lòng), 車中 (trong xe), 忌中 (trong thời gian chịu tang)\n3. khoảng giữa; đoạn giữa trong 3 đoạn\nVD: 中等 (tầm trung), 中流 (tầng lớp trung lưu), 中盤 (giai đoạn giữa)\n4. ở giữa; khoảng cách giữa hai bên\nVD: 中間 (trung gian), 中継 (phát sóng), 中腹 (sườn núi)\n5. suốt; toàn bộ\nVD: 年中 (quanh năm), 世界中 (trên toàn thế giới)\n6. viết tắt của trung học hoặc Trung Quốc\nVD: 中卒 (tốt nghiệp trung học), 訪中 (thăm Trung Quốc)\n7. không thiên vị\nVD: 中立 (trung lập), 中道 (trung đạo), 折中 (dung )\n8. trúng; nhắm trúng\nVD: 中毒 (trúng độc), 命中 (trúng đích)\n9. mọi người; trong nhóm bạn bè\nVD: 講中 (nhóm tín đồ), 連中 (đám người)"}, {"id": "靴革中口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "靴革中丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "靴革廿", "word": "廿", "hanViet": "NHẬP, CHẤP", "detail": "Hai mươi. Như nhập bát tinh tú [廿八星宿] hai mươi tám sao, tức \"Nhị thập bát tú\" [二十八宿]. $ Ta quen đọc là chữ chấp."}, {"id": "靴革廿十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "靴革廿十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "靴革廿十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}], "links": [{"source": "靴", "target": "靴化"}, {"source": "靴化", "target": "靴化亻"}, {"source": "靴化", "target": "靴化匕"}, {"source": "靴", "target": "靴革"}, {"source": "靴革", "target": "靴革中"}, {"source": "靴革中", "target": "靴革中口"}, {"source": "靴革中", "target": "靴革中丨"}, {"source": "靴革", "target": "靴革廿"}, {"source": "靴革廿", "target": "靴革廿十"}, {"source": "靴革廿十", "target": "靴革廿十一"}, {"source": "靴革廿十", "target": "靴革廿十丨"}]}'::jsonb WHERE character = '靴' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "余", "h": "DƯ", "d": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"w": "⻌", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "途余", "word": "余", "hanViet": "DƯ", "detail": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"id": "途余𠆢", "word": "𠆢", "hanViet": "", "detail": ""}, {"id": "途余于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "途余于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "途余于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}, {"id": "途余ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "途⻌", "word": "⻌", "hanViet": "", "detail": ""}], "links": [{"source": "途", "target": "途余"}, {"source": "途余", "target": "途余𠆢"}, {"source": "途余", "target": "途余于"}, {"source": "途余于", "target": "途余于二"}, {"source": "途余于", "target": "途余于亅"}, {"source": "途余", "target": "途余ハ"}, {"source": "途", "target": "途⻌"}]}'::jsonb WHERE character = '途' AND char_type = 'KANJI';
