UPDATE writing_characters SET comp_details_json = '[{"w": "孚", "h": "PHU", "d": "Tin, trung phu [中孚] tên một quẻ trong kinh Dịch.##Phu giáp [孚甲] nứt nanh, nghĩa là cây cỏ nứt nanh nở ra hạt ra lá.##Cũng có nghĩa như chữ phu [孵]."}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "浮孚", "word": "孚", "hanViet": "PHU", "detail": "Tin, trung phu [中孚] tên một quẻ trong kinh Dịch.##Phu giáp [孚甲] nứt nanh, nghĩa là cây cỏ nứt nanh nở ra hạt ra lá.##Cũng có nghĩa như chữ phu [孵]."}, {"id": "浮孚子", "word": "子", "hanViet": "TỬ, TÍ", "detail": "1. con; con cái\nVD: 子息 (con trai), 妻子 (vợ con)\n2. nhỏ; vật nhỏ\nVD: 子細 (chi tiết), 原子 (nguyên tử)\n3. hậu tố thêm vào tên đồ vật\nVD: 椅子 (ghế), 扇子 (quạt giấy)\n4. người\nVD: 才子 (người tài), 遊子 (kẻ tha hương)\n5. đàn ông\nVD: 男子 (nam giới)\n6. tử (tước vị thứ tư trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam))\nVD: 子爵 (tử tước)\n7. kính xưng dành cho nam giới đã trưởng thành; đặc biệt là đối với người có địa vị hoặc học vấn đức độ cao\nVD: 君子 (quân tử), 孔子 (Khổng Tử), 夫子 (bậc thầy)\n8. Tý (con giáp đầu tiên trong mười hai con giáp); con chuột; phương Bắc; giờ Tý\n9. hạt; quả; trứng\nVD: 子房 (bầu nhụy), 種子 (hạt giống)"}, {"id": "浮孚爫", "word": "爫", "hanViet": "TRẢO", "detail": "Một hình thức của bộ trảo [爪]."}, {"id": "浮氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "浮", "target": "浮孚"}, {"source": "浮孚", "target": "浮孚子"}, {"source": "浮孚", "target": "浮孚爫"}, {"source": "浮", "target": "浮氵"}]}'::jsonb WHERE character = '浮' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "走", "h": "TẨU", "d": "1. người sai vặt; người hầu\nVD: 走狗 (tay sai, chó săn)\n2. chạy; chạy nhanh; cho chạy\nVD: 走行 (chạy), 疾走 (chạy nhanh)\n3. chạy trốn; trốn thoát\nVD: 脱走 (đào tẩu), 逃走 (bỏ chạy)"}, {"w": "戉", "h": "MẬU VIỆT", "d": "warrior, arms, savage, Ainu"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "越走", "word": "走", "hanViet": "TẨU", "detail": "1. người sai vặt; người hầu\nVD: 走狗 (tay sai, chó săn)\n2. chạy; chạy nhanh; cho chạy\nVD: 走行 (chạy), 疾走 (chạy nhanh)\n3. chạy trốn; trốn thoát\nVD: 脱走 (đào tẩu), 逃走 (bỏ chạy)"}, {"id": "越戉", "word": "戉", "hanViet": "MẬU VIỆT", "detail": "warrior, arms, savage, Ainu"}, {"id": "越戉戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "越戉𠄌", "word": "𠄌", "hanViet": "", "detail": ""}], "links": [{"source": "越", "target": "越走"}, {"source": "越", "target": "越戉"}, {"source": "越戉", "target": "越戉戈"}, {"source": "越戉", "target": "越戉𠄌"}]}'::jsonb WHERE character = '越' AND char_type = 'KANJI';
