UPDATE writing_characters SET comp_details_json = '[{"w": "余", "h": "DƯ", "d": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"w": "⻖", "h": "PHỤ / ẤP", "d": "Bộ Phụ (gò đất, phía bên trái) hoặc bộ Ấp (làng xóm, bên phải)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "除余", "word": "余", "hanViet": "DƯ", "detail": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"id": "除余𠆢", "word": "𠆢", "hanViet": "", "detail": ""}, {"id": "除余于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "除余于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "除余于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}, {"id": "除余ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "除⻖", "word": "⻖", "hanViet": "PHỤ / ẤP", "detail": "Bộ Phụ (gò đất, phía bên trái) hoặc bộ Ấp (làng xóm, bên phải)"}], "links": [{"source": "除", "target": "除余"}, {"source": "除余", "target": "除余𠆢"}, {"source": "除余", "target": "除余于"}, {"source": "除余于", "target": "除余于二"}, {"source": "除余于", "target": "除余于亅"}, {"source": "除余", "target": "除余ハ"}, {"source": "除", "target": "除⻖"}]}'::jsonb WHERE character = '除' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "戍", "h": "THÚ", "d": "Đóng thú, lính phải ra đóng canh phòng ngoài biên gọi là lính thú. Có tội bị đầy ra ngoài biên làm lính thú gọi là trích thú [讁戍].##Ở, nhà ở."}, {"w": "幺", "h": "YÊU", "d": "Nhỏ.##Tục gọi số một là yêu, vì số một là số đầu (nhỏ); đánh tổ tôm, tài bàn, chắn, v.v. gọi nhất là yêu là vì đó.##Dị dạng của chữ [么].##Giản thể của chữ [么]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "幾戍", "word": "戍", "hanViet": "THÚ", "detail": "Đóng thú, lính phải ra đóng canh phòng ngoài biên gọi là lính thú. Có tội bị đầy ra ngoài biên làm lính thú gọi là trích thú [讁戍].##Ở, nhà ở."}, {"id": "幾戍人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "幾戍戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "幾幺", "word": "幺", "hanViet": "YÊU", "detail": "Nhỏ.##Tục gọi số một là yêu, vì số một là số đầu (nhỏ); đánh tổ tôm, tài bàn, chắn, v.v. gọi nhất là yêu là vì đó.##Dị dạng của chữ [么].##Giản thể của chữ [么]."}, {"id": "幾幺糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}], "links": [{"source": "幾", "target": "幾戍"}, {"source": "幾戍", "target": "幾戍人"}, {"source": "幾戍", "target": "幾戍戈"}, {"source": "幾", "target": "幾幺"}, {"source": "幾幺", "target": "幾幺糸"}]}'::jsonb WHERE character = '幾' AND char_type = 'KANJI';
