UPDATE writing_characters SET comp_details_json = '[{"w": "穴", "h": "HUYỆT", "d": "1. lỗ; chỗ trũng\nVD: 穴居 (sống trong hang), 墓穴 (phần mộ)\n2. thâm hụt; thua lỗ (kế toán)\n3. kết quả bất ngờ\nVD: 大穴 (thắng lớn bất ngờ)\n4. huyệt đạo trên cơ thể\nVD: 灸穴 (huyệt châm cứu)\n5.  chỗ hời mà ít người biết\nVD: 穴場 (chỗ hay ít người biết)"}, {"w": "厶", "h": "KHƯ", "d": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "窓穴", "source": "窓"}, {"target": "窓穴ハ", "source": "窓穴"}, {"target": "窓穴宀", "source": "窓穴"}, {"target": "窓厶", "source": "窓"}, {"target": "窓心", "source": "窓"}], "nodes": [{"id": "窓穴", "word": "穴", "hanViet": "HUYỆT", "detail": "1. lỗ; chỗ trũng\nVD: 穴居 (sống trong hang), 墓穴 (phần mộ)\n2. thâm hụt; thua lỗ (kế toán)\n3. kết quả bất ngờ\nVD: 大穴 (thắng lớn bất ngờ)\n4. huyệt đạo trên cơ thể\nVD: 灸穴 (huyệt châm cứu)\n5.  chỗ hời mà ít người biết\nVD: 穴場 (chỗ hay ít người biết)"}, {"id": "窓穴ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "窓穴宀", "word": "宀", "hanViet": "MIÊN", "detail": "Lợp trùm nhà ngoài với nhà trong."}, {"id": "窓厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "窓心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]}'::jsonb WHERE character = '窓' AND char_type = 'KANJI';
