UPDATE writing_characters SET comp_details_json = '[{"w": "菫", "h": "CẬN", "d": "Rau cần cạn."}, {"w": "力", "h": "LỰC", "d": "1. sức lực; sức mạnh\nVD: 力士 (võ sĩ sumo), 体力 (thể lực)\n2. hoạt động; chức năng; hiệu quả\nVD: 効力 (hiệu lực), 視力 (thị lực)\n3. gồng mình; dồn sức\n4. uy thế; thế lực\nVD: 威力 (sức mạnh), 勢力 (thế lực)\n5. cố gắng; nỗ lực; chăm chỉ\nVD: 力作 (tác phẩm tâm huyết), 努力 (nỗ lực)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "勤菫", "word": "菫", "hanViet": "CẬN", "detail": "Rau cần cạn."}, {"id": "勤菫主", "word": "主", "hanViet": "CHỦ, CHÚA", "detail": "1. chủ thể hành động; phía thực hiện \nVD: 主語 (chủ ngữ), 主体 (chủ thể)\n2. chính; yếu tố trung tâm \nVD: 主題 (chủ đề), 主力 (lực lượng chính)\n3. chủ; chủ nhân; người đứng đầu \nVD: 主人 (chủ nhân), 城主 (thành chủ)\n4. quản lý; chủ trì; đóng vai trò trung tâm\nVD: 主管 (người quản lý chính), 主宰 (chủ trì)"}, {"id": "勤菫主王", "word": "王", "hanViet": "VƯƠNG, VƯỢNG", "detail": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"id": "勤菫主王一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "勤菫主王土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "勤菫主丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "勤菫艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "勤菫口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "勤力", "word": "力", "hanViet": "LỰC", "detail": "1. sức lực; sức mạnh\nVD: 力士 (võ sĩ sumo), 体力 (thể lực)\n2. hoạt động; chức năng; hiệu quả\nVD: 効力 (hiệu lực), 視力 (thị lực)\n3. gồng mình; dồn sức\n4. uy thế; thế lực\nVD: 威力 (sức mạnh), 勢力 (thế lực)\n5. cố gắng; nỗ lực; chăm chỉ\nVD: 力作 (tác phẩm tâm huyết), 努力 (nỗ lực)"}], "links": [{"source": "勤", "target": "勤菫"}, {"source": "勤菫", "target": "勤菫主"}, {"source": "勤菫主", "target": "勤菫主王"}, {"source": "勤菫主王", "target": "勤菫主王一"}, {"source": "勤菫主王", "target": "勤菫主王土"}, {"source": "勤菫主", "target": "勤菫主丶"}, {"source": "勤菫", "target": "勤菫艹"}, {"source": "勤菫", "target": "勤菫口"}, {"source": "勤", "target": "勤力"}]}'::jsonb WHERE character = '勤' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "亥", "h": "HỢI", "d": "Chi Hợi, một chi cuối cùng trong mười hai chi. Từ chín giờ đến mười một đêm gọi là giờ Hợi."}, {"w": "刂", "h": "ĐAO", "d": "Một hình thức của bộ đao [刀]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "刻亥", "word": "亥", "hanViet": "HỢI", "detail": "Chi Hợi, một chi cuối cùng trong mười hai chi. Từ chín giờ đến mười một đêm gọi là giờ Hợi."}, {"id": "刻亥幺", "word": "幺", "hanViet": "YÊU", "detail": "Nhỏ.##Tục gọi số một là yêu, vì số một là số đầu (nhỏ); đánh tổ tôm, tài bàn, chắn, v.v. gọi nhất là yêu là vì đó.##Dị dạng của chữ [么].##Giản thể của chữ [么]."}, {"id": "刻亥幺糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"id": "刻亥亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "刻刂", "word": "刂", "hanViet": "ĐAO", "detail": "Một hình thức của bộ đao [刀]."}], "links": [{"source": "刻", "target": "刻亥"}, {"source": "刻亥", "target": "刻亥幺"}, {"source": "刻亥幺", "target": "刻亥幺糸"}, {"source": "刻亥", "target": "刻亥亠"}, {"source": "刻", "target": "刻刂"}]}'::jsonb WHERE character = '刻' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "羊", "h": "DƯƠNG", "d": "con cừu\nVD: 羊毛 (lông cừu), 綿羊 (cừu nuôi)"}, {"w": "尸", "h": "THI", "d": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"w": "⻌", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"links": [{"target": "遅羊", "source": "遅"}, {"target": "遅尸", "source": "遅"}, {"target": "遅⻌", "source": "遅"}], "nodes": [{"id": "遅羊", "word": "羊", "hanViet": "DƯƠNG", "detail": "con cừu\nVD: 羊毛 (lông cừu), 綿羊 (cừu nuôi)"}, {"id": "遅尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "遅⻌", "word": "⻌", "hanViet": "", "detail": ""}]}'::jsonb WHERE character = '遅' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "石", "h": "THẠCH", "d": "1. đá; tảng đá; vật làm bằng đá\nVD: 石器 (đồ đá), 石工 (thợ đá), 石仏 (tượng Phật bằng đá)\n2. ví với vật không có giá trị\nVD: 瓦石 (ngói và đá), 玉石混交 (tốt xấu lẫn lộn)\n3. ví với vật cứng như đá\nVD: 石心 (lòng dạ sắt đá), 金石 (kim loại và đá), 木石 (cây cỏ và đá)\n4. <i>koku</i>\n(a) đơn vị đo dung tích trong hệ <i>shakkanho</i> (hệ đo lường cổ của Nhật Bản); khoảng 180 lít\n(b) đơn vị đo dung tích của tàu thuyền hoặc gỗ; khoảng 0,28 mét khối\n5. viết tắt của tỉnh cổ Iwami\nVD: 石州 (Sekishu - tỉnh Iwami)\n6. thuốc; thuốc có nguồn gốc khoáng vật\nVD: 薬石 (thuốc thang)"}, {"w": "皮", "h": "BÌ", "d": "1. lớp bao phủ bên ngoài; da; vỏ\nVD: 皮膚 (da người), 樹皮 (vỏ cây)\n2. bề ngoài; bề mặt\nVD: 皮相 (bề ngoài, nông cạn)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "破石", "word": "石", "hanViet": "THẠCH", "detail": "1. đá; tảng đá; vật làm bằng đá\nVD: 石器 (đồ đá), 石工 (thợ đá), 石仏 (tượng Phật bằng đá)\n2. ví với vật không có giá trị\nVD: 瓦石 (ngói và đá), 玉石混交 (tốt xấu lẫn lộn)\n3. ví với vật cứng như đá\nVD: 石心 (lòng dạ sắt đá), 金石 (kim loại và đá), 木石 (cây cỏ và đá)\n4. <i>koku</i>\n(a) đơn vị đo dung tích trong hệ <i>shakkanho</i> (hệ đo lường cổ của Nhật Bản); khoảng 180 lít\n(b) đơn vị đo dung tích của tàu thuyền hoặc gỗ; khoảng 0,28 mét khối\n5. viết tắt của tỉnh cổ Iwami\nVD: 石州 (Sekishu - tỉnh Iwami)\n6. thuốc; thuốc có nguồn gốc khoáng vật\nVD: 薬石 (thuốc thang)"}, {"id": "破石丆", "word": "丆", "hanViet": "", "detail": ""}, {"id": "破石口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "破皮", "word": "皮", "hanViet": "BÌ", "detail": "1. lớp bao phủ bên ngoài; da; vỏ\nVD: 皮膚 (da người), 樹皮 (vỏ cây)\n2. bề ngoài; bề mặt\nVD: 皮相 (bề ngoài, nông cạn)"}, {"id": "破皮丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "破皮厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "破皮又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}], "links": [{"source": "破", "target": "破石"}, {"source": "破石", "target": "破石丆"}, {"source": "破石", "target": "破石口"}, {"source": "破", "target": "破皮"}, {"source": "破皮", "target": "破皮丨"}, {"source": "破皮", "target": "破皮厂"}, {"source": "破皮", "target": "破皮又"}]}'::jsonb WHERE character = '破' AND char_type = 'KANJI';
