UPDATE writing_characters SET comp_details_json = '[{"w": "彳", "h": "XÍCH", "d": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}, {"w": "皮", "h": "BÌ", "d": "1. lớp bao phủ bên ngoài; da; vỏ\nVD: 皮膚 (da người), 樹皮 (vỏ cây)\n2. bề ngoài; bề mặt\nVD: 皮相 (bề ngoài, nông cạn)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "彼彳", "source": "彼"}, {"target": "彼皮", "source": "彼"}, {"target": "彼皮丨", "source": "彼皮"}, {"target": "彼皮厂", "source": "彼皮"}, {"target": "彼皮又", "source": "彼皮"}], "nodes": [{"id": "彼彳", "word": "彳", "hanViet": "XÍCH", "detail": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}, {"id": "彼皮", "word": "皮", "hanViet": "BÌ", "detail": "1. lớp bao phủ bên ngoài; da; vỏ\nVD: 皮膚 (da người), 樹皮 (vỏ cây)\n2. bề ngoài; bề mặt\nVD: 皮相 (bề ngoài, nông cạn)"}, {"id": "彼皮丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "彼皮厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "彼皮又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}]}'::jsonb WHERE character = '彼' AND char_type = 'KANJI';
