UPDATE writing_characters SET comp_details_json = '[{"w": "至", "h": "CHÍ", "d": "1. hết mức; cực kỳ\nVD: 至言 (lời nói chí lý), 至急 (khẩn cấp)\n2. đến; tới; đạt đến\nVD: 乃至 (cho đến), 必至 (tất yếu)\n3. ngày chí (ngày mặt trời đạt đến điểm cực)\nVD: 夏至 (hạ chí), 冬至 (đông chí)"}, {"w": "刂", "h": "ĐAO", "d": "Một hình thức của bộ đao [刀]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "到至", "word": "至", "hanViet": "CHÍ", "detail": "1. hết mức; cực kỳ\nVD: 至言 (lời nói chí lý), 至急 (khẩn cấp)\n2. đến; tới; đạt đến\nVD: 乃至 (cho đến), 必至 (tất yếu)\n3. ngày chí (ngày mặt trời đạt đến điểm cực)\nVD: 夏至 (hạ chí), 冬至 (đông chí)"}, {"id": "到至一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "到至厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "到至土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "到刂", "word": "刂", "hanViet": "ĐAO", "detail": "Một hình thức của bộ đao [刀]."}], "links": [{"source": "到", "target": "到至"}, {"source": "到至", "target": "到至一"}, {"source": "到至", "target": "到至厶"}, {"source": "到至", "target": "到至土"}, {"source": "到", "target": "到刂"}]}'::jsonb WHERE character = '到' AND char_type = 'KANJI';
