UPDATE writing_characters SET comp_details_json = '[{"w": "也", "h": "DÃ", "d": "Vậy, nhời nói hết câu. Như nghĩa giả nghi dã [義者宜也] nghĩa, ấy là sự nên thế thì làm vậy.##Có chỗ dùng làm lời mở đầu. Như dã tri hương tín nhật ưng sơ [也知鄉信日應疎] vậy biết tin làng ngày phải thưa."}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "池也", "source": "池"}, {"target": "池氵", "source": "池"}], "nodes": [{"id": "池也", "word": "也", "hanViet": "DÃ", "detail": "Vậy, nhời nói hết câu. Như nghĩa giả nghi dã [義者宜也] nghĩa, ấy là sự nên thế thì làm vậy.##Có chỗ dùng làm lời mở đầu. Như dã tri hương tín nhật ưng sơ [也知鄉信日應疎] vậy biết tin làng ngày phải thưa."}, {"id": "池氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]}'::jsonb WHERE character = '池' AND char_type = 'KANJI';
