UPDATE writing_characters SET comp_details_json = '[{"w": "喬", "h": "KIỀU", "d": "Cao. Như kiều mộc [喬木] cây cao. Kinh Thi nói : Xuất tự u cốc, thiên vu kiều mộc [出自幽谷遷于喬木] Từ hang tối ra, thiên lên cây cao. Ý nói chim nó còn biết chọn chỗ cao, huống chi người. Nay dùng hai chữ kiều thiên [喬遷]để tỏ ý lên chốn cao thượng sáng láng.##Giả. Như kiều trang [喬妝] ăn mặc giả lốt.##Cái móc trên cái giáo.##Cùng nghĩa với chữ kiêu [驕]."}, {"w": "木", "h": "MỘC", "d": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "橋喬", "source": "橋"}, {"target": "橋喬冋", "source": "橋喬"}, {"target": "橋喬冋冂", "source": "橋喬冋"}, {"target": "橋喬冋口", "source": "橋喬冋"}, {"target": "橋喬呑", "source": "橋喬"}, {"target": "橋喬呑夭", "source": "橋喬呑"}, {"target": "橋喬呑夭ノ", "source": "橋喬呑夭"}, {"target": "橋喬呑夭大", "source": "橋喬呑夭"}, {"target": "橋喬呑夭大一", "source": "橋喬呑夭大"}, {"target": "橋喬呑夭大人", "source": "橋喬呑夭大"}, {"target": "橋喬呑口", "source": "橋喬呑"}, {"target": "橋木", "source": "橋"}, {"target": "橋木大", "source": "橋木"}, {"target": "橋木大一", "source": "橋木大"}, {"target": "橋木大人", "source": "橋木大"}, {"target": "橋木丨", "source": "橋木"}], "nodes": [{"id": "橋喬", "word": "喬", "hanViet": "KIỀU", "detail": "Cao. Như kiều mộc [喬木] cây cao. Kinh Thi nói : Xuất tự u cốc, thiên vu kiều mộc [出自幽谷遷于喬木] Từ hang tối ra, thiên lên cây cao. Ý nói chim nó còn biết chọn chỗ cao, huống chi người. Nay dùng hai chữ kiều thiên [喬遷]để tỏ ý lên chốn cao thượng sáng láng.##Giả. Như kiều trang [喬妝] ăn mặc giả lốt.##Cái móc trên cái giáo.##Cùng nghĩa với chữ kiêu [驕]."}, {"id": "橋喬冋", "word": "冋", "hanViet": "QUYNH", "detail": "desert, border prairie, the 1st form is radical 13"}, {"id": "橋喬冋冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "橋喬冋口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 