UPDATE writing_characters SET comp_details_json = '[{"w": "龶", "h": "", "d": ""}, {"w": "毋", "h": "VÔ", "d": "Chớ, đừng.##Chớ, dùng làm tiếng giúp lời. Như vô nãi [毋乃] chớ bèn (cùng nghĩa với hoặc giả [或者]); tương vô [將毋] hầu chớ, v.v. đều là lời hỏi lấy ý mình đoán mà chưa dám quyết đoán.##Một âm là mưu. Hẳn. Mưu đôi [毋追] một thứ mũ vải đen."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "毒龶", "word": "龶", "hanViet": "", "detail": ""}, {"id": "毒毋", "word": "毋", "hanViet": "VÔ, MƯU", "detail": "Chớ, đừng.##Chớ, dùng làm tiếng giúp lời. Như vô nãi [毋乃] chớ bèn (cùng nghĩa với hoặc giả [或者]); tương vô [將毋] hầu chớ, v.v. đều là lời hỏi lấy ý mình đoán mà chưa dám quyết đoán.##Một âm là mưu. Hẳn. Mưu đôi [毋追] một thứ mũ vải đen."}], "links": [{"source": "毒", "target": "毒龶"}, {"source": "毒", "target": "毒毋"}]}'::jsonb WHERE character = '毒' AND char_type = 'KANJI';
