UPDATE writing_characters SET comp_details_json = '[{"w": "筑", "h": "TRÚC", "d": "Một thứ âm nhạc. Như cái đàn của xẩm.##Giản thể của chữ [築]."}, {"w": "木", "h": "MỘC", "d": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "築筑", "source": "築"}, {"target": "築筑凡", "source": "築筑"}, {"target": "築筑凡几", "source": "築筑凡"}, {"target": "築筑凡丶", "source": "築筑凡"}, {"target": "築筑工", "source": "築筑"}, {"target": "築筑⺮", "source": "築筑"}, {"target": "築木", "source": "築"}, {"target": "築木大", "source": "築木"}, {"target": "築木大一", "source": "築木大"}, {"target": "築木大人", "source": "築木大"}, {"target": "築木丨", "source": "築木"}], "nodes": [{"id": "築筑", "word": "筑", "hanViet": "TRÚC", "detail": "Một thứ âm nhạc. Như cái đàn của xẩm.##Giản thể của chữ [築]."}, {"id": "築筑凡", "word": "凡", "hanViet": "PHÀM", "detail": "1. tầm thường; bình thường; phổ biến\nVD: 凡人 (người bình thường), 凡夫 (người tầm thường), 平凡 (tầm thường)\n2. tất cả; mọi thứ; nhìn chung\nVD: 凡例 (chú thích), 凡百 (muôn vàn)\n3. đại khái; khoảng chừng"}, {"id": "築筑凡几", "word": "几", "hanViet": "KỈ", "detail": "Cái ghế dựa.##Cái kỉ tre.##Giản thể của chữ [幾]."}, {"id": "築筑凡丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "築筑工", "word": "工", "hanViet": "CÔNG", "detail": "1. viết tắt của 工業 (công nghiệp)\nVD: 商工 (thương mại và công nghiệp)\n2. chế tạo đồ vật; khéo léo; công việc; kỹ nghệ\nVD: 工作 (thủ công), 細工 (chế tác tinh xảo)\n3. người chế tạo đồ vật; thợ thủ công\nVD: 職工 (thợ thủ công), 大工 (thợ mộc)"}, {"id": "築筑⺮", "word": "⺮", "hanViet": "", "detail": ""}, {"id": "築木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"id": "築木大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "築木大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "築木大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "築木丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}]}'::jsonb WHERE character = '築' AND char_type = 'KANJI';
