UPDATE writing_characters SET comp_details_json = '[{"w": "于", "h": "VU", "d": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"w": "宀", "h": "MIÊN", "d": "Lợp trùm nhà ngoài với nhà trong."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "宇于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "宇于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "宇于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}, {"id": "宇宀", "word": "宀", "hanViet": "MIÊN", "detail": "Lợp trùm nhà ngoài với nhà trong."}], "links": [{"source": "宇", "target": "宇于"}, {"source": "宇于", "target": "宇于二"}, {"source": "宇于", "target": "宇于亅"}, {"source": "宇", "target": "宇宀"}]}'::jsonb WHERE character = '宇' AND char_type = 'KANJI';
