UPDATE writing_characters SET comp_details_json = '[{"w": "⻗", "h": "", "d": ""}, {"w": "辰", "h": "THẦN", "d": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "震⻗", "word": "⻗", "hanViet": "", "detail": ""}, {"id": "震辰", "word": "辰", "hanViet": "THẦN, THÌN", "detail": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"id": "震辰二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "震辰𧘇", "word": "𧘇", "hanViet": "", "detail": ""}, {"id": "震辰厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}], "links": [{"source": "震", "target": "震⻗"}, {"source": "震", "target": "震辰"}, {"source": "震辰", "target": "震辰二"}, {"source": "震辰", "target": "震辰𧘇"}, {"source": "震辰", "target": "震辰厂"}]}'::jsonb WHERE character = '震' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "戒", "h": "GIỚI", "d": "1. lời răn; giới luật trong tôn giáo\nVD: 戒壇 (giới đàn), 戒律 (giới luật), 破戒 (phá giới)\n2. đề phòng; cảnh giác\nVD: 戒厳 (giới nghiêm), 戒心 (lòng cảnh giác), 警戒 (cảnh giác)\n3. răn dạy; khuyên bảo; cẩn trọng\nVD: 戒告 (cảnh cáo), 訓戒 (lời răn dạy), 自戒 (tự răn mình)"}, {"w": "木", "h": "MỘC", "d": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "械戒", "source": "械"}, {"target": "械戒廾", "source": "械戒"}, {"target": "械戒廾十", "source": "械戒廾"}, {"target": "械戒廾十一", "source": "械戒廾十"}, {"target": "械戒廾十丨", "source": "械戒廾十"}, {"target": "械戒戈", "source": "械戒"}, {"target": "械木", "source": "械"}, {"target": "械木大", "source": "械木"}, {"target": "械木大一", "source": "械木大"}, {"target": "械木大人", "source": "械木大"}, {"target": "械木丨", "source": "械木"}], "nodes": [{"id": "械戒", "word": "戒", "hanViet": "GIỚI", "detail": "1. lời răn; giới luật trong tôn giáo\nVD: 戒壇 (giới đàn), 戒律 (giới luật), 破戒 (phá giới)\n2. đề phòng; cảnh giác\nVD: 戒厳 (giới nghiêm), 戒心 (lòng cảnh giác), 警戒 (cảnh giác)\n3. răn dạy; khuyên bảo; cẩn trọng\nVD: 戒告 (cảnh cáo), 訓戒 (lời răn dạy), 自戒 (tự răn mình)"}, {"id": "械戒廾", "word": "廾", "hanViet": "CỦNG", "detail": "Chắp tay."}, {"id": "械戒廾十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "械戒廾十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "械戒廾十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "械戒戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "械木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"id": "械木大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "械木大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "械木大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "械木丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}]}'::jsonb WHERE character = '械' AND char_type = 'KANJI';
