UPDATE writing_characters SET comp_details_json = '[{"w": "乚", "h": "HÀO ẤT", "d": "hidden, mysterious, secret, to conceal, small, minute, fishhook radical variant (no. 5)"}, {"w": "孚", "h": "PHU", "d": "Tin, trung phu [中孚] tên một quẻ trong kinh Dịch.##Phu giáp [孚甲] nứt nanh, nghĩa là cây cỏ nứt nanh nở ra hạt ra lá.##Cũng có nghĩa như chữ phu [孵]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "乳乚", "source": "乳"}, {"target": "乳孚", "source": "乳"}, {"target": "乳孚子", "source": "乳孚"}, {"target": "乳孚爫", "source": "乳孚"}], "nodes": [{"id": "乳乚", "word": "乚", "hanViet": "HÀO ẤT", "detail": "hidden, mysterious, secret, to conceal, small, minute, fishhook radical variant (no. 5)"}, {"id": "乳孚", "word": "孚", "hanViet": "PHU", "detail": "Tin, trung phu [中孚] tên một quẻ trong kinh Dịch.##Phu giáp [孚甲] nứt nanh, nghĩa là cây cỏ nứt nanh nở ra hạt ra lá.##Cũng có nghĩa như chữ phu [孵]."}, {"id": "乳孚子", "word": "子", "hanViet": "TỬ, TÍ", "detail": "1. con; con cái\nVD: 子息 (con trai), 妻子 (vợ con)\n2. nhỏ; vật nhỏ\nVD: 子細 (chi tiết), 原子 (nguyên tử)\n3. hậu tố thêm vào tên đồ vật\nVD: 椅子 (ghế), 扇子 (quạt giấy)\n4. người\nVD: 才子 (người tài), 遊子 (kẻ tha hương)\n5. đàn ông\nVD: 男子 (nam giới)\n6. tử (tước vị thứ tư trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam))\nVD: 子爵 (tử tước)\n7. kính xưng dành cho nam giới đã trưởng thành; đặc biệt là đối với người có địa vị hoặc học vấn đức độ cao\nVD: 君子 (quân tử), 孔子 (Khổng Tử), 夫子 (bậc thầy)\n8. Tý (con giáp đầu tiên trong mười hai con giáp); con chuột; phương Bắc; giờ Tý\n9. hạt; quả; trứng\nVD: 子房 (bầu nhụy), 種子 (hạt giống)"}, {"id": "乳孚爫", "word": "爫", "hanViet": "TRẢO", "detail": "Một hình thức của bộ trảo [爪]."}]}'::jsonb WHERE character = '乳' AND char_type = 'KANJI';
