UPDATE writing_characters SET comp_details_json = '[{"w": "由", "h": "DO", "d": "1. từ; biểu thị điểm bắt đầu của hành động hoặc thời gian\n2. chỗ dựa; căn cứ; lý do\nVD: 由来 (nguồn gốc), 由緒 (lai lịch, lịch sử), 理由 (lý do)\n3. dựa vào; căn cứ vào\nVD: 経由 (thông qua), 自由 (tự do)\n4. giống như; tựa như\n5. nghe nói là (truyền đạt lại điều đã nghe)"}, {"w": "尸", "h": "THI", "d": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "届由", "word": "由", "hanViet": "DO", "detail": "1. từ; biểu thị điểm bắt đầu của hành động hoặc thời gian\n2. chỗ dựa; căn cứ; lý do\nVD: 由来 (nguồn gốc), 由緒 (lai lịch, lịch sử), 理由 (lý do)\n3. dựa vào; căn cứ vào\nVD: 経由 (thông qua), 自由 (tự do)\n4. giống như; tựa như\n5. nghe nói là (truyền đạt lại điều đã nghe)"}, {"id": "届尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}], "links": [{"source": "届", "target": "届由"}, {"source": "届", "target": "届尸"}]}'::jsonb WHERE character = '届' AND char_type = 'KANJI';
