UPDATE writing_characters SET comp_details_json = '[{"w": "曽", "h": "TẰNG", "d": "1. chồng chất; lặp lại; lớp \nVD: 曽孫 (chắt)\n2. đã từng; trước đây\nVD: 曽遊 (đã từng đến), 未曽有 (chưa từng có)\n3. tức là; chính là\n4. thêm vào; tăng lên"}, {"w": "尸", "h": "THI", "d": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "層曽", "word": "曽", "hanViet": "TẰNG", "detail": "1. chồng chất; lặp lại; lớp \nVD: 曽孫 (chắt)\n2. đã từng; trước đây\nVD: 曽遊 (đã từng đến), 未曽有 (chưa từng có)\n3. tức là; chính là\n4. thêm vào; tăng lên"}, {"id": "層曽丷", "word": "丷", "hanViet": "", "detail": ""}, {"id": "層曽田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "層曽日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "層尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}], "links": [{"source": "層", "target": "層曽"}, {"source": "層曽", "target": "層曽丷"}, {"source": "層曽", "target": "層曽田"}, {"source": "層曽", "target": "層曽日"}, {"source": "層", "target": "層尸"}]}'::jsonb WHERE character = '層' AND char_type = 'KANJI';
