UPDATE writing_characters SET comp_details_json = '[{"w": "兄", "h": "HUYNH", "d": "1. anh trai \nVD: 兄弟 (anh em), 長兄 (anh cả)\n2. kính xưng đối với bạn bè hoặc người cùng vai vế\nVD: 貴兄 (quý anh)"}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "況兄", "word": "兄", "hanViet": "HUYNH", "detail": "1. anh trai \nVD: 兄弟 (anh em), 長兄 (anh cả)\n2. kính xưng đối với bạn bè hoặc người cùng vai vế\nVD: 貴兄 (quý anh)"}, {"id": "況兄口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "況兄儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}, {"id": "況氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "況", "target": "況兄"}, {"source": "況兄", "target": "況兄口"}, {"source": "況兄", "target": "況兄儿"}, {"source": "況", "target": "況氵"}]}'::jsonb WHERE character = '況' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "甫", "h": "PHỦ", "d": "Tiếng gọi tôn quý của đàn ông. Như đức Khổng Tử gọi là Ni phủ [尼甫].##Tên chữ biểu hiệu, cho nên hỏi tên tự người ta thì nói là thai phủ [台甫].##Cha, mình nói đến cha người khác thì kêu là tôn phủ [尊甫].##Vừa mới. Như phủ nhập môn [甫入門] vừa bước vào cửa.##Lớn."}, {"w": "衤", "h": "Y", "d": "Bộ Y (biến thể bộ Y 衣: y phục, quần áo)"}]'::jsonb, comp_graph_json = '{"links": [{"target": "補甫", "source": "補"}, {"target": "補甫用", "source": "補甫"}, {"target": "補甫十", "source": "補甫"}, {"target": "補甫十一", "source": "補甫十"}, {"target": "補甫十丨", "source": "補甫十"}, {"target": "補甫丶", "source": "補甫"}, {"target": "補衤", "source": "補"}], "nodes": [{"id": "補甫", "word": "甫", "hanViet": "PHỦ", "detail": "Tiếng gọi tôn quý của đàn ông. Như đức Khổng Tử gọi là Ni phủ [尼甫].##Tên chữ biểu hiệu, cho nên hỏi tên tự người ta thì nói là thai phủ [台甫].##Cha, mình nói đến cha người khác thì kêu là tôn phủ [尊甫].##Vừa mới. Như phủ nhập môn [甫入門] vừa bước vào cửa.##Lớn."}, {"id": "補甫用", "word": "用", "hanViet": "DỤNG", "detail": "1. dùng; sử dụng; làm cho có ích \nVD: 用意 (chuẩn bị), 使用 (sử dụng)\n2. cách dùng; mục đích sử dụng\nVD: 薬用 (dùng làm thuốc), 浴用 (dùng để tắm)\n3. tác dụng; hiệu quả\nVD: 作用 (tác dụng), 効用 (hiệu quả)\n4. đi đại tiểu tiện\nVD: 用便 (đi vệ sinh)\n5. bằng; nhờ vào\n6. chi phí hoặc vật dụng cần thiết\nVD: 用度 (chi phí), 費用 (chi phí)\n7. công việc phải làm\nVD: 用件 (việc cần bàn), 所用 (việc riêng)"}, {"id": "補甫十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "補甫十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "補甫十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "補甫丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "補衤", "word": "衤", "hanViet": "Y", "detail": "Bộ Y (biến thể bộ Y 衣: y phục, quần áo)"}]}'::jsonb WHERE character = '補' AND char_type = 'KANJI';
