UPDATE writing_characters SET comp_details_json = '[{"w": "升", "h": "THĂNG", "d": "1. lên; tăng lên \nVD: 升平 (thái bình và thịnh vượng), 上升 (tăng lên)\n2. đơn vị đo dung tích; khoảng 1,8 lít\n3. <i>masu</i> (dụng cụ đo dung tích của vật) \nVD: 升酒 (rượu uống bằng chén gỗ <i>masu</i>)"}, {"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "昇升", "word": "升", "hanViet": "THĂNG", "detail": "1. lên; tăng lên \nVD: 升平 (thái bình và thịnh vượng), 上升 (tăng lên)\n2. đơn vị đo dung tích; khoảng 1,8 lít\n3. <i>masu</i> (dụng cụ đo dung tích của vật) \nVD: 升酒 (rượu uống bằng chén gỗ <i>masu</i>)"}, {"id": "昇升ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "昇升廾", "word": "廾", "hanViet": "CỦNG", "detail": "Chắp tay."}, {"id": "昇升廾十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "昇升廾十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "昇升廾十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ