UPDATE writing_characters SET comp_details_json = '[{"w": "農", "h": "NÔNG", "d": "1. cày cấy; trồng trọt\nVD: 農業 (nông nghiệp), 農耕 (canh tác)\n2. người làm ruộng; nông dân\nVD: 農民 (nông dân), 農夫 (người làm ruộng)"}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "濃農", "word": "農", "hanViet": "NÔNG", "detail": "1. cày cấy; trồng trọt\nVD: 農業 (nông nghiệp), 農耕 (canh tác)\n2. người làm ruộng; nông dân\nVD: 農民 (nông dân), 農夫 (người làm ruộng)"}, {"id": "濃農辰", "word": "辰", "hanViet": "THẦN, THÌN", "detail": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"id": "濃農辰二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "濃農辰𧘇", "word": "𧘇", "hanViet": "", "detail": ""}, {"id": "濃農辰厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "濃農曲", "word": "曲", "hanViet": "KHÚC", "detail": "1. cong; uốn cong; bẻ cong \nVD: 曲折 (quanh co), 曲線 (đường cong)\n2. gian tà; sai lệch \nVD: 曲学 (học vấn lệch lạc), 曲説 (lý luận sai lệch), 歪曲 (xuyên tạc)\n3. góc; chỗ uốn cong\nVD: 湾曲 (uốn cong)\n4. thú vị; biến hóa\nVD: 曲芸 (xiếc)\n5. giai điệu; bản nhạc\nVD: 曲目 (danh mục bài hát), 歌曲 (ca khúc)\n6. tỉ mỉ; chi tiết; tường tận\nVD: 曲尽 (tận tường), 委曲 (chi tiết)"}, {"id": "濃氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "濃", "target": "濃農"}, {"source": "濃農", "target": "濃農辰"}, {"source": "濃農辰", "target": "濃農辰二"}, {"source": "濃農辰", "target": "濃農辰𧘇"}, {"source": "濃農辰", "target": "濃農辰厂"}, {"source": "濃農", "target": "濃農曲"}, {"source": "濃", "target": "濃氵"}]}'::jsonb WHERE character = '濃' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "木", "h": "MỘC", "d": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"w": "亟", "h": "CỨC", "d": "Kíp. Như nhu dụng thậm cức [需用甚亟] cần dùng rất kíp.##Một âm là khí. Luôn luôn. Như khí vấn khí quỹ đỉnh nhục [亟問亟饋鼎肉] hỏi luôn đưa thịt ăn luôn."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "極木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"id": "極木大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "極木大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)