UPDATE writing_characters SET comp_details_json = '[{"w": "亢", "h": "KHÁNG", "d": "Cao. Như bất kháng bất ti [不亢不卑] không kiêu ngạo không siểm nịnh.##Quá. Như kháng dương [亢陽] chân dương thái quá, kháng hạn [亢旱] nắng quá.##Che chở. Như kháng tông chi tử [亢宗之子] đứa con có thể làm phên che chở cho họ được.##Một âm là cang. Cổ. Như ách kỳ cang [搤其亢] bóp thửa cổ.##Sao Cang, một vì sao trong Nhị thập bát tú, cũng đọc là chữ cương."}, {"w": "舟", "h": "CHU", "d": "1. thuyền; thuyền nhỏ\nVD: 舟運 (vận tải đường thủy), 舟艇 (thuyền nhỏ)\n2. bồn tắm hình dạng giống thuyền\nVD: 湯舟 (bồn tắm)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "航亢", "word": "亢", "hanViet": "KHÁNG, CANG, CƯƠNG", "detail": "Cao. Như bất kháng bất ti [不亢不卑] không kiêu ngạo không siểm nịnh.##Quá. Như kháng dương [亢陽] chân dương thái quá, kháng hạn [亢旱] nắng quá.##Che chở. Như kháng tông chi tử [亢宗之子] đứa con có thể làm phên che chở cho họ được.##Một âm là cang. Cổ. Như ách kỳ cang [搤其亢] bóp thửa cổ.##Sao Cang, một vì sao trong Nhị thập bát tú, cũng đọc là chữ cương."}, {"id": "航亢几", "word": "几", "hanViet": "KỈ", "detail": "Cái ghế dựa.##Cái kỉ tre.##Giản thể của chữ [幾]."}, {"id": "航亢亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "航舟", "word": "舟", "hanViet": "CHU", "detail": "1. thuyền; thuyền nhỏ\nVD: 舟運 (vận tải đường thủy), 舟艇 (thuyền nhỏ)\n2. bồn tắm hình dạng giống thuyền\nVD: 湯舟 (bồn tắm)"}, {"id": "航舟ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "航舟一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "航舟冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "航舟丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}], "links": [{"source": "航", "target": "航亢"}, {"source": "航亢", "target": "航亢几"}, {"source": "航亢", "target": "航亢亠"}, {"source": "航", "target": "航舟"}, {"source": "航舟", "target": "航舟ノ"}, {"source": "航舟", "target": "航舟一"}, {"source": "航舟", "target": "航舟冂"}, {"source": "航舟", "target": "航舟丶"}]}'::jsonb WHERE character = '航' AND char_type = 'KANJI';
