UPDATE writing_characters SET comp_details_json = '[{"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"w": "並", "h": "TỊNH", "d": "1. cùng với; đồng thời; kết hợp \n2. đứng thành hàng; xếp hàng \nVD: 並行 (đồng thời), 並立 (cùng tồn tại)\n3. bình thường; phổ thông; hạng trung\nVD: 並製 (bản thường)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "普日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "普並", "word": "並", "hanViet": "TỊNH, TINH", "detail": "1. cùng với; đồng thời; kết hợp \n2. đứng thành hàng; xếp hàng \nVD: 並行 (đồng thời), 並立 (cùng tồn tại)\n3. bình thường; phổ thông; hạng trung\nVD: 並製 (bản thường)"}, {"id": "普並立", "word": "立", "hanViet": "LẬP", "detail": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}], "links": [{"source": "普", "target": "普日"}, {"source": "普", "target": "普並"}, {"source": "普並", "target": "普並立"}]}'::jsonb WHERE character = '普' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"w": "帚", "h": "TRỬU", "d": "Cái chổi, cái dùng để quét để giặt rửa đều gọi là trửu."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "掃扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"id": "掃帚", "word": "帚", "hanViet": "TRỬU, CHỬU", "detail": "Cái chổi, cái dùng để quét để giặt rửa đều gọi là trửu."}, {"id": "掃帚⺕", "word": "⺕", "hanViet": "", "detail": ""}, {"id": "掃帚冖", "word": "冖", "hanViet": "MỊCH", "detail": "Trùm, lấy khăn trùm lên trên đồ."}, {"id": "掃帚巾", "word": "巾", "hanViet": "CÂN", "detail": "1. mảnh vải; khăn tay; khăn lau\nVD: 手巾 (khăn tay)\n2.  mũ trùm; khăn trùm đầu\nVD: 頭巾 (mũ trùm đầu)"}], "links": [{"source": "掃", "target": "掃扌"}, {"source": "掃", "target": "掃帚"}, {"source": "掃帚", "target": "掃帚⺕"}, {"source": "掃帚", "target": "掃帚冖"}, {"source": "掃帚", "target": "掃帚巾"}]}'::jsonb WHERE character = '掃' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "尼", "h": "NI", "d": "ni cô; phụ nữ xuất gia; viết tắt của 比丘尼 (tỳ-kheo-ni)\nVD: 尼寺 (ni viện), 尼僧 (ni cô)"}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "泥尼", "word": "尼", "hanViet": "NI, NỆ, NẶC, NẬT", "detail": "ni cô; phụ nữ xuất gia; viết tắt của 比丘尼 (tỳ-kheo-ni)\nVD: 尼寺 (ni viện), 尼僧 (ni cô)"}, {"id": "泥尼尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "泥尼匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}, {"id": "泥氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "泥", "target": "泥尼"}, {"source": "泥尼", "target": "泥尼尸"}, {"source": "泥尼", "target": "泥尼匕"}, {"source": "泥", "target": "泥氵"}]}'::jsonb WHERE character = '泥' AND char_type = 'KANJI';
