UPDATE writing_characters SET comp_details_json = '[{"w": "丶", "h": "CHỦ", "d": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"w": "卯", "h": "MÃO", "d": "Chi Mão. Chi thứ tư trong 12 chi. Từ năm giờ sáng đến bảy giờ sáng là giờ Mão.##Lệ các quan làm việc từ gìờ Mão, cho nên điểm tên gọi là điểm mão [點卯], xưng đến tên dạ lên gọi là ứng mão [應卯], sổ sách gọi là mão bạ [卯簿]. Lập ra kì hẹn để thu tiền lương và so sánh nhiều ít gọi là tỉ mão [比卯]."}]'::jsonb, comp_graph_json = '{"links": [{"target": "卵丶", "source": "卵"}, {"target": "卵卯", "source": "卵"}, {"target": "卵卯ノ", "source": "卵卯"}, {"target": "卵卯卬", "source": "卵卯"}, {"target": "卵卯卬匚", "source": "卵卯卬"}, {"target": "卵卯卬卩", "source": "卵卯卬"}], "nodes": [{"id": "卵丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "卵卯", "word": "卯", "hanViet": "MÃO, MẸO", "detail": "Chi Mão. Chi thứ tư trong 12 chi. Từ năm giờ sáng đến bảy giờ sáng là giờ Mão.##Lệ các quan làm việc từ gìờ Mão, cho nên điểm tên gọi là điểm mão [點卯], xưng đến tên dạ lên gọi là ứng mão [應卯], sổ sách gọi là mão bạ [卯簿]. Lập ra kì hẹn để thu tiền lương và so sánh nhiều ít gọi là tỉ mão [比卯]."}, {"id": "卵卯ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "卵卯卬", "word": "卬", "hanViet": "NGANG", "detail": "Ta. Ngày xưa dùng như chữ ngang [昂] và chữ ngưỡng [仰]."}, {"id": "卵卯卬匚", "word": "匚", "hanViet": "PHƯƠNG", "detail": "Cái đồ để đựng đồ."}, {"id": "卵卯卬卩", "word": "卩", "hanViet": "TIẾT", "detail": "Bộ tiết."}]}'::jsonb WHERE character = '卵' AND char_type = 'KANJI';
