UPDATE writing_characters SET comp_details_json = '[{"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"w": "屈", "h": "KHUẤT", "d": "1. mạnh mẽ \nVD: 屈強 (lực lưỡng)\n2. cúi xuống; co lại; uốn cong \nVD: 屈曲 (khúc khuỷu), 屈折 (khúc xạ)\n3. bế tắc; cùng cực\nVD: 窮屈 (gò bó)\n4. nản lòng; thua cuộc và khuất phục\nVD: 屈辱 (nhục nhã), 屈服 (khuất phục)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "掘扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"id": "掘屈", "word": "屈", "hanViet": "KHUẤT, QUẬT", "detail": "1. mạnh mẽ \nVD: 屈強 (lực lưỡng)\n2. cúi xuống; co lại; uốn cong \nVD: 屈曲 (khúc khuỷu), 屈折 (khúc xạ)\n3. bế tắc; cùng cực\nVD: 窮屈 (gò bó)\n4. nản lòng; thua cuộc và khuất phục\nVD: 屈辱 (nhục nhã), 屈服 (khuất phục)"}, {"id": "掘屈尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "掘屈出", "word": "出", "hanViet": "XUẤT, XÚY", "detail": "1. nguồn gốc; xuất thân\nVD: 出自 (nguồn gốc), 出身 (xuất thân)\n2. đi đến; tham gia; hoạt động\nVD: 出演 (trình diễn), 出場 (tham gia thi đấu)\n3. ra ngoài; đưa ra ngoài \nVD: 出家 (xuất gia), 出版 (xuất bản), 抽出 (trích xuất)\n4. xuất hiện; lộ ra\nVD: 出現 (xuất hiện), 出世 (thăng tiến), 露出 (lộ ra)\n5. ưu tú; vượt trội\nVD: 出色 (xuất sắc), 傑出 (kiệt xuất)"}], "links": [{"source": "掘", "target": "掘扌"}, {"source": "掘", "target": "掘屈"}, {"source": "掘屈", "target": "掘屈尸"}, {"source": "掘屈", "target": "掘屈出"}]}'::jsonb WHERE character = '掘' AND char_type = 'KANJI';
