UPDATE writing_characters SET comp_details_json = '[{"w": "敕", "h": "SẮC", "d": "Sắc lệnh, tờ chiếu mệnh của vua ban cho quan dân gọi là sắc [敕].##Cảnh tỉnh cho biết đạo mà chấn chỉnh cho nên công bình trị (sửa trị)."}, {"w": "正", "h": "CHÁNH", "d": "1. đúng; chính xác; hợp đạo lý \nVD: 正解 (đáp án đúng), 正義 (chính nghĩa), 公正 (công bằng)\n2. sửa cho đúng; sửa lại\nVD: 改正 (sửa đổi), 修正 (chỉnh sửa), 是正 (chỉnh đốn)\n3. đúng lúc; chính xác; vừa vặn\nVD: 正午 (đúng 12 giờ trưa), 正方形 (hình vuông)\n4. nguyên gốc; thực sự; chính \nVD: 正式 (chính thức), 正統 (chính thống)\n5. số dương; cực dương  \nVD: 正極 (cực dương), 正数 (số dương)\n6. đầu năm\nVD: 正月 (Tết)\n7. người đứng đầu; trưởng; quan đứng đầu\nVD: 僧正 (vị sư chức vị cao)\n8. cấp bậc cao hơn trong cùng phẩm hàm \nVD: 正三位 (Chánh tam vị)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "整敕", "word": "敕", "hanViet": "SẮC", "detail": "Sắc lệnh, tờ chiếu mệnh của vua ban cho quan dân gọi là sắc [敕].##Cảnh tỉnh cho biết đạo mà chấn chỉnh cho nên công bình trị (sửa trị)."}, {"id": "整敕攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}, {"id": "整敕束", "word": "束", "hanViet": "THÚC, THÚ", "detail": "1. buộc; trói\nVD: 束縛 (ràng buộc)\n2. giữ lại; trói buộc\nVD: 拘束 (giam giữ)\n3. bó; buộc thành bó\nVD: 束髪 (kiểu tóc búi phong cách phương Tây thời Meiji)\n4. đơn vị đếm các vật được bó lại\n5. đơn vị đo chiều dài mũi tên"}, {"id": "整敕束口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "整敕束木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"id": "整敕束木大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "整敕束木大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "整敕束木大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "整敕束木丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "整正", "word": "正", "hanViet": "CHÁNH, CHÍNH", "detail": "1. đúng; chính xác; hợp đạo lý \nVD: 正解 (đáp án đúng), 正義 (ch