UPDATE writing_characters SET comp_details_json = '[{"w": "我", "h": "NGÃ", "d": "ta; mình; bản thân; của mình\nVD: 我見 (ý kiến bản thân), 我慢 (chịu đựng), 自我 (bản ngã), 我を張る (khăng khăng theo ý mình)"}, {"w": "𦍌", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "義我", "word": "我", "hanViet": "NGÃ", "detail": "ta; mình; bản thân; của mình\nVD: 我見 (ý kiến bản thân), 我慢 (chịu đựng), 自我 (bản ngã), 我を張る (khăng khăng theo ý mình)"}, {"id": "義我戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "義我扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"id": "義𦍌", "word": "𦍌", "hanViet": "", "detail": ""}], "links": [{"source": "義", "target": "義我"}, {"source": "義我", "target": "義我戈"}, {"source": "義我", "target": "義我扌"}, {"source": "義", "target": "義𦍌"}]}'::jsonb WHERE character = '義' AND char_type = 'KANJI';
