UPDATE writing_characters SET comp_details_json = '[{"w": "魚", "h": "NGƯ", "d": "cá\nVD: 魚介 (hải sản), 魚肉 (thịt cá), 養魚 (nuôi cá)"}, {"w": "羊", "h": "DƯƠNG", "d": "con cừu\nVD: 羊毛 (lông cừu), 綿羊 (cừu nuôi)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "鮮魚", "word": "魚", "hanViet": "NGƯ", "detail": "cá\nVD: 魚介 (hải sản), 魚肉 (thịt cá), 養魚 (nuôi cá)"}, {"id": "鮮魚⺈", "word": "⺈", "hanViet": "", "detail": ""}, {"id": "鮮魚田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "鮮魚灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}, {"id": "鮮羊", "word": "羊", "hanViet": "DƯƠNG", "detail": "con cừu\nVD: 羊毛 (lông cừu), 綿羊 (cừu nuôi)"}], "links": [{"source": "鮮", "target": "鮮魚"}, {"source": "鮮魚", "target": "鮮魚⺈"}, {"source": "鮮魚", "target": "鮮魚田"}, {"source": "鮮魚", "target": "鮮魚灬"}, {"source": "鮮", "target": "鮮羊"}]}'::jsonb WHERE character = '鮮' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "ノ", "h": "PHIỆT", "d": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"w": "冂", "h": "QUYNH", "d": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"w": "虫", "h": "TRÙNG", "d": "1. sâu bọ; côn trùng\nVD: 益虫 (côn trùng có ích), 幼虫 (ấu trùng)\n2. các loài động vật nói chung"}, {"w": "尸", "h": "THI", "d": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "属ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "属冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "属虫", "word": "虫", "hanViet": "TRÙNG", "detail": "1. sâu bọ; côn trùng\nVD: 益虫 (côn trùng có ích), 幼虫 (ấu trùng)\n2. các loài động vật nói chung"}, {"id": "属虫一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "属虫丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "属虫中", "word": "中", "hanViet": "TRUNG, TRÚNG", "detail": "1. chính giữa\nVD: 中央 (trung ương), 中心 (trung tâm), 中核 (cốt lõi)\n2. bên trong phạm vi; phía trong\nVD: 意中 (trong lòng), 車中 (trong xe), 忌中 (trong thời gian chịu tang)\n3. khoảng giữa; đoạn giữa trong 3 đoạn\nVD: 中等 (tầm trung), 中流 (tầng lớp trung lưu), 中盤 (giai đoạn giữa)\n4. ở giữa; khoảng cách giữa hai bên\nVD: 中間 (trung gian), 中継 (phát sóng), 中腹 (sườn núi)\n5. suốt; toàn bộ\nVD: 年中 (quanh năm), 世界中 (trên toàn thế giới)\n6. viết tắt của trung học hoặc Trung Quốc\nVD: 中卒 (tốt nghiệp trung học), 訪中 (thăm Trung Quốc)\n7. không thiên vị\nVD: 中立 (trung lập), 中道 (trung đạo), 折中 (dung )\n8. trúng; nhắm trúng\nVD: 中毒 (trúng độc), 命中 (trúng đích)\n9. mọi người; trong nhóm bạn bè\nVD: 講中 (nhóm tín đồ), 連中 (đám người)"}, {"id": "属虫中口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "属虫中丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "属尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}], "links": [{"source": "属", "target": "属ノ"}, {"source": "属", "target": "属冂"}, {"source": "属", "target": "属虫"}, {"source": "属虫", "target": "属虫一"}, {"source": "属虫", "target": "属虫丶"}, {"source": "属虫", "target": "属虫中"}, {"source": "属虫中", "target": "属虫中口"}, {"source": "属虫中", "target": "属虫中丨"}, {"source": "属", "target": "属尸"}]}'::jsonb WHERE character = '属' AND char_type = 'KANJI';
