UPDATE writing_characters SET comp_details_json = '[{"w": "倉", "h": "THƯƠNG", "d": "1. nhà kho; kho chứa \nVD: 倉庫 (kho hàng), 船倉 (khoang tàu)\n2. đột ngột; vội vàng; hốt hoảng \nVD: 倉皇 (hốt hoảng), 倉卒 (vội vã)"}, {"w": "刂", "h": "ĐAO", "d": "Một hình thức của bộ đao [刀]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "創倉", "word": "倉", "hanViet": "THƯƠNG, THẢNG", "detail": "1. nhà kho; kho chứa \nVD: 倉庫 (kho hàng), 船倉 (khoang tàu)\n2. đột ngột; vội vàng; hốt hoảng \nVD: 倉皇 (hốt hoảng), 倉卒 (vội vã)"}, {"id": "創倉亼", "word": "亼", "hanViet": "", "detail": ""}, {"id": "創倉亼一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "創倉亼人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "創倉口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "創倉尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "創刂", "word": "刂", "hanViet": "ĐAO", "detail": "Một hình thức của bộ đao [刀]."}], "links": [{"source": "創", "target": "創倉"}, {"source": "創倉", "target": "創倉亼"}, {"source": "創倉亼", "target": "創倉亼一"}, {"source": "創倉亼", "target": "創倉亼人"}, {"source": "創倉", "target": "創倉口"}, {"source": "創倉", "target": "創倉尸"}, {"source": "創", "target": "創刂"}]}'::jsonb WHERE character = '創' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "主", "h": "CHỦ", "d": "1. chủ thể hành động; phía thực hiện \nVD: 主語 (chủ ngữ), 主体 (chủ thể)\n2. chính; yếu tố trung tâm \nVD: 主題 (chủ đề), 主力 (lực lượng chính)\n3. chủ; chủ nhân; người đứng đầu \nVD: 主人 (chủ nhân), 城主 (thành chủ)\n4. quản lý; chủ trì; đóng vai trò trung tâm\nVD: 主管 (người quản lý chính), 主宰 (chủ trì)"}, {"w": "彳", "h": "XÍCH", "d": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "往主", "word": "主", "hanViet": "CHỦ, CHÚA", "detail": "1. chủ thể hành động; phía thực hiện \nVD: 主語 (chủ ngữ), 主体 (chủ thể)\n2. chính; yếu tố trung tâm \nVD: 主題 (chủ đề), 主力 (lực lượng chính)\n3. chủ; chủ nhân; người đứng đầu \nVD: 主人 (chủ nhân), 城主 (thành chủ)\n4. quản lý; chủ trì; đóng vai trò trung tâm\nVD: 主管 (người quản lý chính), 主宰 (chủ trì)"}, {"id": "往主王", "word": "王", "hanViet": "VƯƠNG, VƯỢNG", "detail": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"id": "往主王一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "往主王土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "往主丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "往彳", "word": "彳", "hanViet": "XÍCH", "detail": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}], "links": [{"source": "往", "target": "往主"}, {"source": "往主", "target": "往主王"}, {"source": "往主王", "target": "往主王一"}, {"source": "往主王", "target": "往主王土"}, {"source": "往主", "target": "往主丶"}, {"source": "往", "target": "往彳"}]}'::jsonb WHERE character = '往' AND char_type = 'KANJI';
