UPDATE writing_characters SET comp_details_json = '[{"w": "辰", "h": "THẦN", "d": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "振辰", "word": "辰", "hanViet": "THẦN, THÌN", "detail": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"id": "振辰二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "振辰𧘇", "word": "𧘇", "hanViet": "", "detail": ""}, {"id": "振辰厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "振扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}], "links": [{"source": "振", "target": "振辰"}, {"source": "振辰", "target": "振辰二"}, {"source": "振辰", "target": "振辰𧘇"}, {"source": "振辰", "target": "振辰厂"}, {"source": "振", "target": "振扌"}]}'::jsonb WHERE character = '振' AND char_type = 'KANJI';
