UPDATE writing_characters SET comp_details_json = '[{"w": "尸", "h": "THI", "d": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"w": "出", "h": "XUẤT", "d": "1. nguồn gốc; xuất thân\nVD: 出自 (nguồn gốc), 出身 (xuất thân)\n2. đi đến; tham gia; hoạt động\nVD: 出演 (trình diễn), 出場 (tham gia thi đấu)\n3. ra ngoài; đưa ra ngoài \nVD: 出家 (xuất gia), 出版 (xuất bản), 抽出 (trích xuất)\n4. xuất hiện; lộ ra\nVD: 出現 (xuất hiện), 出世 (thăng tiến), 露出 (lộ ra)\n5. ưu tú; vượt trội\nVD: 出色 (xuất sắc), 傑出 (kiệt xuất)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "屈尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "屈出", "word": "出", "hanViet": "XUẤT, XÚY", "detail": "1. nguồn gốc; xuất thân\nVD: 出自 (nguồn gốc), 出身 (xuất thân)\n2. đi đến; tham gia; hoạt động\nVD: 出演 (trình diễn), 出場 (tham gia thi đấu)\n3. ra ngoài; đưa ra ngoài \nVD: 出家 (xuất gia), 出版 (xuất bản), 抽出 (trích xuất)\n4. xuất hiện; lộ ra\nVD: 出現 (xuất hiện), 出世 (thăng tiến), 露出 (lộ ra)\n5. ưu tú; vượt trội\nVD: 出色 (xuất sắc), 傑出 (kiệt xuất)"}], "links": [{"source": "屈", "target": "屈尸"}, {"source": "屈", "target": "屈出"}]}'::jsonb WHERE character = '屈' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "叚", "h": "GIẢ", "d": "Cũng như chữ [假]."}, {"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "暇叚", "word": "叚", "hanViet": "GIẢ", "detail": "Cũng như chữ [假]."}, {"id": "暇叚コ", "word": "コ", "hanViet": "", "detail": ""}, {"id": "暇叚尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "暇叚又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}, {"id": "暇日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}], "links": [{"source": "暇", "target": "暇叚"}, {"source": "暇叚", "target": "暇叚コ"}, {"source": "暇叚", "target": "暇叚尸"}, {"source": "暇叚", "target": "暇叚又"}, {"source": "暇", "target": "暇日"}]}'::jsonb WHERE character = '暇' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"w": "戠", "h": "THỰC", "d": "sword, potter''s clay, to gather"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "織糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"id": "織戠", "word": "戠", "hanViet": "THỰC", "detail": "sword, potter''s clay, to gather"}, {"id": "織戠戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "織戠音", "word": "音", "hanViet": "ÂM", "detail": "1. âm thanh; giai điệu; âm sắc\nVD: 音階 (thang âm), 音楽 (âm nhạc), 音曲 (khúc nhạc)\n2. âm; âm đọc chữ Hán \nVD: 音訳 (phiên âm), 漢音 (âm Hán), 呉音 (âm Ngô)\n3. giọng nói; âm thanh từ miệng\nVD: 音韻 (ngữ âm), 音声 (âm thanh), 音便 (biến âm)\n4. thông báo; thư từ; tin tức\nVD: 音信 (tin tức), 音書 (thư từ), 音問 (hỏi thăm tin tức)"}, {"id": "織戠音日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "織戠音立", "word": "立", "hanViet": "LẬP", "detail": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}], "links": [{"source": "織", "target": "織糸"}, {"source": "織", "target": "織戠"}, {"source": "織戠", "target": "織戠戈"}, {"source": "織戠", "target": "織戠音"}, {"source": "織戠音", "target": "織戠音日"}, {"source": "織戠音", "target": "織戠音立"}]}'::jsonb WHERE character = '織' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "或", "h": "HOẶC", "d": "Hoặc, là lời nói còn ngờ, chưa quyết định hẳn. Như hoặc nhân [或人] hoặc người nào, hoặc viết [或曰] hoặc có kẻ nói rằng, v.v.##Ngờ, cũng như chữ hoặc [惑].##Có.##Ai."}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "惑或", "word": "或", "hanViet": "HOẶC", "detail": "Hoặc, là lời nói còn ngờ, chưa quyết định hẳn. Như hoặc nhân [或人] hoặc người nào, hoặc viết [或曰] hoặc có kẻ nói rằng, v.v.##Ngờ, cũng như chữ hoặc [惑].##Có.##Ai."}, {"id": "惑或戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "惑或口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "惑或一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "惑心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}], "links": [{"source": "惑", "target": "惑或"}, {"source": "惑或", "target": "惑或戈"}, {"source": "惑或", "target": "惑或口"}, {"source": "惑或", "target": "惑或一"}, {"source": "惑", "target": "惑心"}]}'::jsonb WHERE character = '惑' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "秀", "h": "TÚ", "d": "vượt trội; ưu tú; vươn lên\nVD: 秀逸 (xuất sắc), 秀才 (người tài), 優秀 (ưu tú)"}, {"w": "言", "h": "NGÔN", "d": "1. nói; phát biểu; trình bày\nVD: 言論 (phát ngôn), 断言 (khẳng định)\n2. lời nói; ngôn từ\nVD: 言行 (lời nói và hành động), 金言 (lời vàng ý ngọc)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "誘秀", "word": "秀", "hanViet": "TÚ", "detail": "vượt trội; ưu tú; vươn lên\nVD: 秀逸 (xuất sắc), 秀才 (người tài), 優秀 (ưu tú)"}, {"id": "誘秀乃", "word": "乃", "hanViet": "NÃI, ÁI", "detail": "Bèn, tiếng nói nối câu trên. Tô Thức [蘇軾] : Dư nãi nhiếp y nhi thướng [予乃攝衣而上] (Hậu Xích Bích phú [後赤壁賦]) Tôi bèn vén áo mà lên.##Tiếng gọi mày tao. Như nãi huynh [乃兄] anh mày, nãi đệ [乃第] em mày.##Một âm là ái. Như ai ái [欸乃] lối hát chèo đò. $ Có chỗ viết là [廼], cũng một nghĩa như chữ [乃]."}, {"id": "誘秀乃ㄋ", "word": "ㄋ", "hanViet": "", "detail": ""}, {"id": "誘秀乃ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "誘秀禾", "word": "禾", "hanViet": "HÒA", "detail": "Lúa, lúa chưa cắt rơm rạ đi gọi là hòa."}, {"id": "誘言", "word": "言", "hanViet": "NGÔN, NGÂN", "detail": "1. nói; phát biểu; trình bày\nVD: 言論 (phát ngôn), 断言 (khẳng định)\n2. lời nói; ngôn từ\nVD: 言行 (lời nói và hành động), 金言 (lời vàng ý ngọc)"}, {"id": "誘言一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "誘言口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}], "links": [{"source": "誘", "target": "誘秀"}, {"source": "誘秀", "target": "誘秀乃"}, {"source": "誘秀乃", "target": "誘秀乃ㄋ"}, {"source": "誘秀乃", "target": "誘秀乃ノ"}, {"source": "誘秀", "target": "誘秀禾"}, {"source": "誘", "target": "誘言"}, {"source": "誘言", "target": "誘言一"}, {"source": "誘言", "target": "誘言口"}]}'::jsonb WHERE character = '誘' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "京", "h": "KINH", "d": "1. viết tắt của Kyoto\nVD: 京洛 (Kyoraku - cách gọi khác của Kyoto)\n2. viết tắt của Tokyo\nVD: 上京 (lên Tokyo)\n3. kinh đô nơi thiên tử hoặc thiên hoàng ở; kinh đô lớn\nVD: 京師 (kinh đô)\n4. kinh (10 triệu tỉ)"}, {"w": "尤", "h": "VƯU", "d": "Lạ, rất, càng. Như thù vưu tuyệt tích [殊尤絕迹] lạ lùng hết mực, nghĩa là nó khác hẳn các cái tầm thường. Con gái đẹp gọi là vưu vật [尤物].##Oán trách, lầm lỗi. Như hiệu vưu [效尤] bắt chước làm điều lầm lạc. Đặng Trần Côn [鄧陳琨] : Quân tâm thảng dữ thiếp tâm tự, Thiếp diệc ư quân hà oán vưu [君心倘與妾心似, 妾亦於君何怨尤] (Chinh Phụ ngâm [征婦吟]) Nếu lòng chàng cũng giống lòng thiếp, Thiếp cũng không có cớ gì oán trách chàng. Đoàn Thị Điểm dịch thơ : Lòng chàng ví cũng bằng như thế, Lòng thiếp đâu dám nghĩ gần xa.##Hơn. Như vưu ngận [尤狠] tàn nhẫn hơn."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "就京", "word": "京", "hanViet": "KINH", "detail": "1. viết tắt của Kyoto\nVD: 京洛 (Kyoraku - cách gọi khác của Kyoto)\n2. viết tắt của Tokyo\nVD: 上京 (lên Tokyo)\n3. kinh đô nơi thiên tử hoặc thiên hoàng ở; kinh đô lớn\nVD: 京師 (kinh đô)\n4. kinh (10 triệu tỉ)"}, {"id": "就京小", "word": "小", "hanViet": "TIỂU", "detail": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"id": "就京口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi r