UPDATE writing_characters SET comp_details_json = '[{"w": "而", "h": "NHI", "d": "Mày. Như nhi ông [而翁] cha mày.##Mà, vậy, dùng làm trợ ngữ. Như nhi kim an tại [而今安在] mà nay còn đâu, dĩ nhi [已而] đã mà.##Bèn, lời nói chuyển xuống. Như nhi mưu động can qua ư bang nội [而謀動干戈於邦內] bèn mưu khởi sự đánh nhau ở trong nước.##Lông má."}, {"w": "立", "h": "LẬP", "d": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}, {"w": "山", "h": "SAN", "d": "1. núi; địa hình nhô cao\nVD: 山脈 (dãy núi), 登山 (leo núi)\n2. chất cao như núi\nVD: 山積 (chất đống)\n3. ngôi chùa; danh hiệu của chùa chiền\nVD: 山号 (tên núi), 開山 (người khai lập chùa)\n4. mỏ; núi khai thác khoáng sản\nVD: 閉山 (đóng mỏ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "端而", "word": "而", "hanViet": "NHI", "detail": "Mày. Như nhi ông [而翁] cha mày.##Mà, vậy, dùng làm trợ ngữ. Như nhi kim an tại [而今安在] mà nay còn đâu, dĩ nhi [已而] đã mà.##Bèn, lời nói chuyển xuống. Như nhi mưu động can qua ư bang nội [而謀動干戈於邦內] bèn mưu khởi sự đánh nhau ở trong nước.##Lông má."}, {"id": "端立", "word": "立", "hanViet": "LẬP", "detail": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}, {"id": "端山", "word": "山", "hanViet": "SAN, SƠN", "detail": "1. núi; địa hình nhô cao\nVD: 山脈 (dãy núi), 登山 (leo núi)\n2. chất cao như núi\nVD: 山積 (chất đống)\n3. ngôi chùa; danh hiệu của chùa chiền\nVD: 山号 (tên núi), 開山 (người khai lập chùa)\n4. mỏ; núi khai thác khoáng sản\nVD: 閉山 (đóng mỏ)"}], "links": [{"source": "端", "target": "端而"}, {"source": "端", "target": "端立"}, {"source": "端", "target":