UPDATE writing_characters SET comp_details_json = '[{"w": "攸", "h": "DU", "d": "Vụt, thoáng, tả cái dáng nhanh chóng. Như du nhiên nhi thệ [攸然而逝] vụt vậy mà đi.##Chốn, nơi. Như tướng du [相攸] kén nơi đáng lấy làm chồng.##Thửa, dùng làm tiếng trợ từ. Như danh tiết du quan [名節攸關] danh tiết thửa quan hệ.##Du du [攸攸] dằng dặc.##Tên người. Như Nguyễn Du [阮攸] (Việt Nam, 1765-1820)."}, {"w": "彡", "h": "SAM", "d": "Lông dài.##Một âm là tiệm. Tiệm thả [彡姐] tên họ, giống rợ Khương."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "修攸", "word": "攸", "hanViet": "DU", "detail": "Vụt, thoáng, tả cái dáng nhanh chóng. Như du nhiên nhi thệ [攸然而逝] vụt vậy mà đi.##Chốn, nơi. Như tướng du [相攸] kén nơi đáng lấy làm chồng.##Thửa, dùng làm tiếng trợ từ. Như danh tiết du quan [名節攸關] danh tiết thửa quan hệ.##Du du [攸攸] dằng dặc.##Tên người. Như Nguyễn Du [阮攸] (Việt Nam, 1765-1820)."}, {"id": "修攸亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "修攸丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "修攸攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}, {"id": "修彡", "word": "彡", "hanViet": "SAM, TIỆM", "detail": "Lông dài.##Một âm là tiệm. Tiệm thả [彡姐] tên họ, giống rợ Khương."}], "links": [{"source": "修", "target": "修攸"}, {"source": "修攸", "target": "修攸亻"}, {"source": "修攸", "target": "修攸丨"}, {"source": "修攸", "target": "修攸攵"}, {"source": "修", "target": "修彡"}]}'::jsonb WHERE character = '修' AND char_type = 'KANJI';
