UPDATE writing_characters SET comp_details_json = '[{"w": "忝", "h": "THIỂM", "d": "Nhục.##Tục dùng làm lời nói khiêm. Như thiểm quyến [忝眷] gia quyến của kẻ hèn mọn này."}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "添忝", "word": "忝", "hanViet": "THIỂM", "detail": "Nhục.##Tục dùng làm lời nói khiêm. Như thiểm quyến [忝眷] gia quyến của kẻ hèn mọn này."}, {"id": "添忝夭", "word": "夭", "hanViet": "YÊU, YỂU", "detail": "Yêu yêu [夭夭] nét mặt vui vẻ ôn tồn.##Rờn rờn, nhan sắc mầu mỡ đáng yêu.##Yêu kiểu [夭矯] uốn khúc. Nguyễn Du [阮攸] : Ngô văn thiên trì chi phần hữu long yêu kiểu [吾聞天池之濆有龍夭矯] (Mạnh Tử từ cổ liễu [孟子祠古柳]) Ta nghe bên bờ ao trời có con rồng uốn khúc.##Tai vạ.##Một âm là yểu. Chết non."}, {"id": "添忝夭ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "添忝夭大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "添忝夭大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "添忝夭大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "添忝⺗", "word": "⺗", "hanViet": "", "detail": ""}, {"id": "添氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "添", "target": "添忝"}, {"source": "添忝", "target": "添忝夭"}, {"source": "添忝夭", "target": "添忝夭ノ"}, {"source": "添忝夭", "target": "添忝夭大"}, {"source": "添忝夭大", "target": "添忝夭大一"}, {"source": "添忝夭大", "target": "添忝夭大人"}, {"source": "添忝", "target": "添忝⺗"}, {"source": "添", "target": "添氵"}]}'::jsonb WHERE character = '添' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "孟", "h": "MẠNH", "d": "Lớn, con trai trưởng dòng đích gọi là bá [伯], con trai trưởng dòng thứ gọi là mạnh [孟].##Mới, trước. Tháng đầu mùa gọi là mạnh nguyệt [孟月]. Như tháng giêng gọi là tháng mạnh xuân [孟春], tháng tư gọi là tháng mạnh hạ [孟夏], v.v.##Cố gắng, mạnh tấn [孟晉] gắng gỏi tiến lên.##Một âm là mãng. Mãng lãng [孟浪] bộp chộp, lỗ mỗ. Tả cái dáng không tinh tế, không thiết thực."}, {"w": "犭", "h": "KHUYỂN", "d": "Bộ Khuyển (biến thể bộ Khuyển 犬: chó, thú vật)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "猛孟", "word": "孟", "hanViet": "MẠNH, MÃNG", "detail": "Lớn, con trai trưởng dòng đích gọi là bá [伯], con trai trưởng dòng thứ gọi là mạnh [孟].##Mới, trước. Tháng đầu mùa gọi là mạnh nguyệt [孟月]. Như tháng giêng gọi là tháng mạnh xuân [孟春], tháng tư gọi là tháng mạnh hạ [孟夏], v.v.##Cố gắng, mạnh tấn [孟晉] gắng gỏi tiến lên.##Một âm là mãng. Mãng lãng [孟浪] bộp chộp, lỗ mỗ. Tả cái dáng không tinh tế, không thiết thực."}, {"id": "猛孟子", "word": "子", "hanViet": "TỬ, TÍ", "detail": "1. con; con cái\nVD: 子息 (con trai), 妻子 (vợ con)\n2. nhỏ; vật nhỏ\nVD: 子細 (chi tiết), 原子 (nguyên tử)\n3. hậu tố thêm vào tên đồ vật\nVD: 椅子 (ghế), 扇子 (quạt giấy)\n4. người\nVD: 才子 (người tài), 遊子 (kẻ tha hương)\n5. đàn ông\nVD: 男子 (nam giới)\n6. tử (tước vị thứ tư trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam))\nVD: 子爵 (tử tước)\n7. kính xưng dành cho nam giới đã trưởng thành; đặc biệt là đối với người có địa vị hoặc học vấn đức độ cao\nVD: 君子 (quân tử), 孔子 (Khổng Tử), 夫子 (bậc thầy)\n8. Tý (con giáp đầu tiên trong mười hai con giáp); con chuột; phương Bắc; giờ Tý\n9. hạt; quả; trứng\nVD: 子房 (bầu nhụy), 種子 (hạt giống)"}, {"id": "猛孟皿", "word": "皿", "hanViet": "MÃNH", "detail": "đĩa; vật phẳng để bày thức ăn"}, {"id": "猛犭", "word": "犭", "hanViet": "KHUYỂN", "detail": "Bộ Khuyển (biến thể bộ Khuyển 犬: chó, thú vật)"}], "links": [{"source": "猛", "target": "猛孟"}, {"source": "猛孟", "target": "猛孟子"}, {"source": "猛孟", "target": "猛孟皿"}, {"source": "猛", "target": "猛犭"}]}'::jsonb WHERE character = '猛' AND char_type = 'KANJI';
