UPDATE writing_characters SET comp_details_json = '[{"w": "未", "h": "VỊ", "d": "1. chưa; vẫn chưa làm \nVD: 未知 (chưa biết), 未来 (tương lai)\n2. Mùi (con giáp thứ tám trong mười hai con giáp); con dê; hướng Nam Tây Nam; giờ Mùi\nVD: 未申 (hướng tây nam)"}, {"w": "鬼", "h": "QUỶ", "d": "1. phi phàm; xuất chúng\nVD: 鬼才 (tài năng xuất chúng)\n2. quỷ; yêu quái; ma quái; ác thần\nVD: 鬼気 (bầu không khí rùng rợn), 鬼畜 (ác như quỷ), 鬼面 (mặt nạ quỷ)\n3. linh hồn của người chết\nVD: 鬼哭 (tiếng ma khóc), 鬼籍 (sổ ghi tên người chết), 霊鬼 (linh hồn)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "魅未", "word": "未", "hanViet": "VỊ, MÙI", "detail": "1. chưa; vẫn chưa làm \nVD: 未知 (chưa biết), 未来 (tương lai)\n2. Mùi (con giáp thứ tám trong mười hai con giáp); con dê; hướng Nam Tây Nam; giờ Mùi\nVD: 未申 (hướng tây nam)"}, {"id": "魅鬼", "word": "鬼", "hanViet": "QUỶ", "detail": "1. phi phàm; xuất chúng\nVD: 鬼才 (tài năng xuất chúng)\n2. quỷ; yêu quái; ma quái; ác thần\nVD: 鬼気 (bầu không khí rùng rợn), 鬼畜 (ác như quỷ), 鬼面 (mặt nạ quỷ)\n3. linh hồn của người chết\nVD: 鬼哭 (tiếng ma khóc), 鬼籍 (sổ ghi tên người chết), 霊鬼 (linh hồn)"}, {"id": "魅鬼甶", "word": "甶", "hanViet": "", "detail": ""}, {"id": "魅鬼甶丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "魅鬼甶田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "魅鬼厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "魅鬼儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}], "links": [{"source": "魅", "target": "魅未"}, {"source": "魅", "target": "魅鬼"}, {"source": "魅鬼", "target": "魅鬼甶"}, {"source": "魅鬼甶", "target": "魅鬼甶丶"}, {"source": "魅鬼甶", "target": "魅鬼甶田"}, {"source": "魅鬼", "target": "魅鬼厶"}, {"source": "魅鬼", "target": "魅鬼儿"}]}'::jsonb WHERE character = '魅' AND char_type = 'KANJI';
