UPDATE writing_characters SET comp_details_json = '[{"w": "其", "h": "KÌ", "d": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"w": "𠂉", "h": "", "d": "Thành phần nét phẩy và nét ngang"}, {"w": "方", "h": "PHƯƠNG", "d": "1. hướng\nVD: 方角 (hướng đi), 方向 (phương hướng)\n2. một bộ phận; lĩnh vực; khía cạnh\nVD: 方面 (lĩnh vực), 双方 (đôi bên)\n3. vùng đất; địa phương\nVD: 方言 (tiếng địa phương), 地方 (địa phương)\n4. cách thức; phương pháp; kỹ năng\nVD: 方式 (cách thức), 方法 (phương pháp), 方術 (thuật pháp)\n5.  hình vuông; vuông vức \nVD: 方形 (hình vuông), 方丈 (vuông một trượng)\n6. đúng đắn; ngay ngắn\nVD: 方正 (ngay thẳng)\n7. đang; đúng lúc\nVD: 方今 (hiện nay)\n8. vị; người; phương hướng; thời gian\n(a) kính ngữ chỉ người khác\n(b) người phụ trách\nVD: 裏方 (người làm hậu trường), 煮方 (người nấu)\n(c) chỗ ở; nơi nương tựa\n(d) thời điểm; lúc\nVD: 夕方 (chiều tối)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "旗其", "word": "其", "hanViet": "KÌ, KÍ, KI", "detail": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"id": "旗𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "旗方", "word": "方", "hanViet": "PHƯƠNG", "detail": "1. hướng\nVD: 方角 (hướng đi), 方向 (phương hướng)\n2. một bộ phận; lĩnh vực; khía cạnh\nVD: 方面 (lĩnh vực), 双方 (đôi bên)\n3. vùng đất; địa phương\nVD: 方言 (tiếng địa phương), 地方 (địa phương)\n4. cách thức; phương pháp; kỹ năng\nVD: 方式 (cách thức), 方法 (phương pháp), 方術 (thuật pháp)\n5.  hình vuông; vuông vức \nVD: 方形 (hình vuông), 方丈 (vuông một trượng)\n6. đúng đắn; ngay ngắn\nVD: 方正 (ngay thẳng)\n7. đang; đúng lúc\nVD: 方今 (hiện nay)\n8. vị; người; phương hướng; thời gian\n(a) kính n