UPDATE writing_characters SET comp_details_json = '[{"w": "ノ", "h": "PHIỆT", "d": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"w": "之", "h": "CHI", "d": "Chưng, dùng về lời nói liền nối nhau. Như đại học chi đạo [大學之道] chưng đạo đại học.##Đi. Như Đằng Văn Công tương chi Sở [滕文公將之楚] Đằng Văn Công sắp đi sang nước Sở.##Đến. Như chi tử mỹ tha [之死靡他] đến chết chẳng tới ai.##Đấy, là tiếng dùng thay một danh từ nào. Như Thang sử nhân vấn chi [湯使人問之] vua Thang khiến người hỏi đấy (hỏi ai ? tức là hỏi Cát Bá, chữ chi đây là thay hai chữ Cát Bá).##Ấy. Như chi tử vu quy [之子于歸] người ấy về nhà chồng."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "乏ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "乏之", "word": "之", "hanViet": "CHI", "detail": "Chưng, dùng về lời nói liền nối nhau. Như đại học chi đạo [大學之道] chưng đạo đại học.##Đi. Như Đằng Văn Công tương chi Sở [滕文公將之楚] Đằng Văn Công sắp đi sang nước Sở.##Đến. Như chi tử mỹ tha [之死靡他] đến chết chẳng tới ai.##Đấy, là tiếng dùng thay một danh từ nào. Như Thang sử nhân vấn chi [湯使人問之] vua Thang khiến người hỏi đấy (hỏi ai ? tức là hỏi Cát Bá, chữ chi đây là thay hai chữ Cát Bá).##Ấy. Như chi tử vu quy [之子于歸] người ấy về nhà chồng."}], "links": [{"source": "乏", "target": "乏ノ"}, {"source": "乏", "target": "乏之"}]}'::jsonb WHERE character = '乏' AND char_type = 'KANJI';
