UPDATE writing_characters SET comp_details_json = '[{"w": "隹", "h": "CHUY", "d": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"w": "离", "h": "LI", "d": "Giản thể của chữ [離]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "離隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "離离", "word": "离", "hanViet": "LI", "detail": "Giản thể của chữ [離]."}, {"id": "離离禸", "word": "禸", "hanViet": "NHỰU", "detail": "Vết ngón chân giống thú dẫm xuống đất."}, {"id": "離离禸冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "離离禸厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "離离凶", "word": "凶", "hanViet": "HUNG", "detail": "1. tai họa; vận rủi \nVD: 凶兆 (điềm xấu), 凶報 (tin dữ)\n2. mất mùa \nVD: 凶作 (mất mùa), 凶年 (năm mất mùa)\n3. sợ hãi; lo âu\n4. lòng dạ xấu xa; làm hại người khác\nVD: 凶悪 (hung ác), 凶行 (hành vi tàn ác)"}, {"id": "離离凶㐅", "word": "㐅", "hanViet": "", "detail": ""}, {"id": "離离凶凵", "word": "凵", "hanViet": "KHẢM", "detail": "Há miệng."}, {"id": "離离亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}], "links": [{"source": "離", "target": "離隹"}, {"source": "離", "target": "離离"}, {"source": "離离", "target": "離离禸"}, {"source": "離离禸", "target": "離离禸冂"}, {"source": "離离禸", "target": "離离禸厶"}, {"source": "離离", "target": "離离凶"}, {"source": "離离凶", "target": "離离凶㐅"}, {"source": "離离凶", "target": "離离凶凵"}, {"source": "離离", "target": "離离亠"}]}'::jsonb WHERE character = '離' AND char_type = 'KANJI';
