UPDATE writing_characters SET comp_details_json = '[{"w": "貞", "h": "TRINH", "d": "đúng đắn; lòng ngay thẳng; giữ gìn tiết hạnh\nVD: 貞淑 (hiền thục), 貞節 (trinh tiết)"}, {"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "偵貞", "word": "貞", "hanViet": "TRINH", "detail": "đúng đắn; lòng ngay thẳng; giữ gìn tiết hạnh\nVD: 貞淑 (hiền thục), 貞節 (trinh tiết)"}, {"id": "偵貞貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "偵貞貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "偵貞貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}, {"id": "偵貞卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "偵亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}], "links": [{"source": "偵", "target": "偵貞"}, {"source": "偵貞", "target": "偵貞貝"}, {"source": "偵貞貝", "target": "偵貞貝ハ"}, {"source": "偵貞貝", "target": "偵貞貝目"}, {"source": "偵貞", "target": "偵貞卜"}, {"source": "偵", "target": "偵亻"}]}'::jsonb WHERE character = '偵' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "奇", "h": "KÌ", "d": "1. hiếm; không bình thường\n(a) kỳ lạ; huyền bí\nVD: 奇術 (ảo thuật), 奇跡 (kì tích), 奇妙 (kì diệu)\n(b) đặc biệt xuất sắc\nVD: 奇偉 (phi thường), 奇才 (nhân tài xuất chúng), 奇麗 (đẹp đẽ)\n(c) bất ngờ; ngẫu nhiên\nVD: 奇禍 (tai họa bất ngờ), 奇遇 (cuộc gặp gỡ tình cờ), 奇襲 (tập kích bất ngờ), 奇をてらう (làm điều khác lạ để gây chú ý)\n2. số lẻ \nVD: 奇数 (số lẻ)"}, {"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "綺奇", "word": "奇", "hanViet": "KÌ, CƠ", "detail": "1. hiếm; không bình thường\n(a) kỳ lạ; huyền bí\nVD: 奇術 (ảo thuật), 奇跡 (kì tích), 奇妙 (kì diệu)\n(b) đặc biệt xuất sắc\nVD: 奇偉 (phi thường), 奇才 (nhân tài xuất chúng), 奇麗 (đẹp đẽ)\n(c) bất ngờ; ngẫu nhiên\nVD: 奇禍 (tai họa bất ngờ), 奇遇 (cuộc gặp gỡ tình cờ), 奇襲 (tập kích bất ngờ), 奇をてらう (làm điều khác lạ để gây chú ý)\n2. số lẻ \nVD: 奇数 (số lẻ)"}, {"id": "綺奇大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "綺奇大一", "word": "