UPDATE writing_characters SET comp_details_json = '[{"w": "享", "h": "HƯỞNG", "d": "1. đãi; chiêu đãi\nVD: 享宴 (yến tiệc chiêu đãi)\n2. tương ứng; phù hợp\n3. nhận; tiếp nhận\nVD: 享受 (hưởng thụ)\n4. cúng tế; dâng lên\nVD: 享祭 (lễ cúng tế)"}, {"w": "丸", "h": "HOÀN", "d": "1. một khối; toàn bộ; nguyên vẹn\nVD: 丸太 (khúc gỗ tròn), 丸裸 (trần trụi), 一丸 (một khối)\n2. tròn; vật tròn; viên\nVD: 丸剤 (thuốc viên), 丸薬 (thuốc hoàn), 砲丸 (đạn pháo)\n3. hậu tố sau tên riêng (người, chó, kiếm, tàu thuyền, v.v.)\nVD: 牛若丸 (Ushiwakamaru)"}, {"w": "灬", "h": "HỎA", "d": "Một hình thức của bộ hỏa [火]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "熟享", "word": "享", "hanViet": "HƯỞNG", "detail": "1. đãi; chiêu đãi\nVD: 享宴 (yến tiệc chiêu đãi)\n2. tương ứng; phù hợp\n3. nhận; tiếp nhận\nVD: 享受 (hưởng thụ)\n4. cúng tế; dâng lên\nVD: 享祭 (lễ cúng tế)"}, {"id": "熟享亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "熟享口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "熟享子", "word": "子", "hanViet": "TỬ, TÍ", "detail": "1. con; con cái\nVD: 子息 (con trai), 妻子 (vợ con)\n2. nhỏ; vật nhỏ\nVD: 子細 (chi tiết), 原子 (nguyên tử)\n3. hậu tố thêm vào tên đồ vật\nVD: 椅子 (ghế), 扇子 (quạt giấy)\n4. người\nVD: 才子 (người tài), 遊子 (kẻ tha hương)\n5. đàn ông\nVD: 男子 (nam giới)\n6. tử (tước vị thứ tư trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam))\nVD: 子爵 (tử tước)\n7. kính xưng dành cho nam giới đã trưởng thành; đặc biệt là đối với người có địa vị hoặc học vấn đức độ cao\nVD: 君子 (quân tử), 孔子 (Khổng Tử), 夫子 (bậc thầy)\n8. Tý (con giáp đầu tiên trong mười hai con giáp); con chuột; phương Bắc; giờ Tý\n9. hạt; quả; trứng\nVD: 子房 (bầu nhụy), 種子 (hạt