UPDATE writing_characters SET comp_details_json = '[{"w": "山", "h": "SAN", "d": "1. núi; địa hình nhô cao\nVD: 山脈 (dãy núi), 登山 (leo núi)\n2. chất cao như núi\nVD: 山積 (chất đống)\n3. ngôi chùa; danh hiệu của chùa chiền\nVD: 山号 (tên núi), 開山 (người khai lập chùa)\n4. mỏ; núi khai thác khoáng sản\nVD: 閉山 (đóng mỏ)"}, {"w": "朋", "h": "BẰNG", "d": "Bè bạn.##Đảng. Như bằng tị vi gian [朋比爲奸] kết đảng làm gian.##Sánh tầy. Như thạc đại vô bằng [碩大無朋] to lớn không gì sánh tầy.##Năm vỏ sò là một bằng. Đời xưa dùng vỏ sò làm tiền, cho nên tạ ơn người ta cho nhiều của gọi là bách bằng chi tích [百朋之錫]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "崩山", "word": "山", "hanViet": "SAN, SƠN", "detail": "1. núi; địa hình nhô cao\nVD: 山脈 (dãy núi), 登山 (leo núi)\n2. chất cao như núi\nVD: 山積 (chất đống)\n3. ngôi chùa; danh hiệu của chùa chiền\nVD: 山号 (tên núi), 開山 (người khai lập chùa)\n4. mỏ; núi khai thác khoáng sản\nVD: 閉山 (đóng mỏ)"}, {"id": "崩朋", "word": "朋", "hanViet": "BẰNG", "detail": "Bè bạn.##Đảng. Như bằng tị vi gian [朋比爲奸] kết đảng làm gian.##Sánh tầy. Như thạc đại vô bằng [碩大無朋] to lớn không gì sánh tầy.##Năm vỏ sò là một bằng. Đời xưa dùng vỏ sò làm tiền, cho nên tạ ơn người ta cho nhiều của gọi là bách bằng chi tích [百朋之錫]."}, {"id": "崩朋月", "word": "月", "hanViet": "NGUYỆT", "detail": "1. thứ Hai\n2. mặt trăng \nVD: 月光 (ánh trăng), 満月 (trăng tròn)\n3. tháng\nVD: 歳月 (thời gian dài), 年月 (năm tháng) "}], "links": [{"source": "崩", "target": "崩山"}, {"source": "崩", "target": "崩朋"}, {"source": "崩朋", "target": "崩朋月"}]}'::jsonb WHERE character = '崩' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "亢", "h": "KHÁNG", "d": "Cao. Như bất kháng bất ti [不亢不卑] không kiêu ngạo không siểm nịnh.##Quá. Như kháng dương [亢陽] chân dương thái quá, kháng hạn [亢旱] nắng quá.##Che chở. Như kháng tông chi tử [亢宗之子] đứa con có thể làm phên che chở cho họ được.##Một âm là cang. Cổ. Như ách kỳ cang [搤其亢] bóp thửa cổ.##Sao Cang, một vì sao trong Nhị thập bát tú, cũng đọc là chữ cương."}, {"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "抗亢", "word": "亢", "hanViet": "KHÁNG, CANG, CƯƠNG", "detail": "Cao. Như bất kháng bất ti [不亢不卑] không kiêu ngạo không siểm nịnh.##Quá. Như kháng dương [亢陽] chân dương thái quá, kháng hạn [亢旱] nắng quá.##Che chở. Như kháng tông chi tử [亢宗之子] đứa con có thể làm phên che chở cho họ được.##Một âm là cang. Cổ. Như ách kỳ cang [搤其亢] bóp thửa cổ.##Sao Cang, một vì sao trong Nhị thập bát tú, cũng đọc là chữ cương."}, {"id": "抗亢几", "word": "几", "hanViet": "KỈ", "detail": "Cái ghế dựa.##Cái kỉ tre.##Giản thể của chữ [幾]."}, {"id": "抗亢亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "抗扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}], "links": [{"source": "抗", "target": "抗亢"}, {"source": "抗亢", "target": "抗亢几"}, {"source": "抗亢", "target": "抗亢亠"}, {"source": "抗", "target": "抗扌"}]}'::jsonb WHERE character = '抗' AND char_type = 'KANJI';
