UPDATE writing_characters SET comp_details_json = '[{"w": "而", "h": "NHI", "d": "Mày. Như nhi ông [而翁] cha mày.##Mà, vậy, dùng làm trợ ngữ. Như nhi kim an tại [而今安在] mà nay còn đâu, dĩ nhi [已而] đã mà.##Bèn, lời nói chuyển xuống. Như nhi mưu động can qua ư bang nội [而謀動干戈於邦內] bèn mưu khởi sự đánh nhau ở trong nước.##Lông má."}, {"w": "⻗", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "需而", "word": "而", "hanViet": "NHI", "detail": "Mày. Như nhi ông [而翁] cha mày.##Mà, vậy, dùng làm trợ ngữ. Như nhi kim an tại [而今安在] mà nay còn đâu, dĩ nhi [已而] đã mà.##Bèn, lời nói chuyển xuống. Như nhi mưu động can qua ư bang nội [而謀動干戈於邦內] bèn mưu khởi sự đánh nhau ở trong nước.##Lông má."}, {"id": "需⻗", "word": "⻗", "hanViet": "", "detail": ""}], "links": [{"source": "需", "target": "需而"}, {"source": "需", "target": "需⻗"}]}'::jsonb WHERE character = '需' AND char_type = 'KANJI';
