UPDATE writing_characters SET comp_details_json = '[{"w": "去", "h": "KHỨ", "d": "1. chết; qua đời\nVD: 死去 (qua đời), 逝去 (từ trần)\n2. rời đi; đi khỏi; rời khỏi \nVD: 去来 (đến và đi), 過去 (quá khứ) \n3. loại bỏ; lấy đi\nVD: 去勢 (thiến), 撤去 (tháo dỡ)\n4. thanh khứ (một trong bốn thanh của âm Hán)\nVD: 去声 (thanh khứ)"}, {"w": "卩", "h": "TIẾT", "d": "Bộ tiết."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "却去", "word": "去", "hanViet": "KHỨ, KHU", "detail": "1. chết; qua đời\nVD: 死去 (qua đời), 逝去 (từ trần)\n2. rời đi; đi khỏi; rời khỏi \nVD: 去来 (đến và đi), 過去 (quá khứ) \n3. loại bỏ; lấy đi\nVD: 去勢 (thiến), 撤去 (tháo dỡ)\n4. thanh khứ (một trong bốn thanh của âm Hán)\nVD: 去声 (thanh khứ)"}, {"id": "却去厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "却去土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "却卩", "word": "卩", "hanViet": "TIẾT", "detail": "Bộ tiết."}], "links": [{"source": "却", "target": "却去"}, {"source": "却去", "target": "却去厶"}, {"source": "却去", "target": "却去土"}, {"source": "却", "target": "却卩"}]}'::jsonb WHERE character = '却' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "虍", "h": "HÔ", "d": "Vằn con hổ, vằn con vện."}, {"w": "思", "h": "TƯ", "d": "1. suy nghĩ; tâm tư; tấm lòng\nVD: 思案 (suy tính), 思索 (ngẫm nghĩ), 意思 (ý nghĩ)\n2. thương nhớ; yêu mến\nVD: 思慕 (thương nhớ), 相思 (tương tư)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "慮虍", "word": "虍", "hanViet": "HÔ", "detail": "Vằn con hổ, vằn con vện."}, {"id": "慮虍卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "慮虍厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "慮虍七", "word": "七", "hanViet": "THẤT", "detail": "1. số bảy\nVD: 七賢 (bảy vị hiền triết), 七夕 (lễ Thất tịch), 七曜 (bảy ngày trong tuần)\n2. nhiều; số lượng lớn\nVD: 七珍万宝 (muôn vàn châu báu)"}, {"id": "慮思", "word": "思", "hanViet": "TƯ, TỨ, TAI", "detail": "1. suy nghĩ; tâm tư; tấm lòng\nVD: 思案 (suy tính), 思索 (ngẫm nghĩ), 意思 (ý nghĩ)\n2. thương nhớ; yêu mến\nVD: 思慕 (thương nhớ), 相思 (tương tư)"}, {"id": "慮思心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}, {"id": "慮思田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}], "links": [{"source": "慮", "target": "慮虍"