UPDATE writing_characters SET comp_details_json = '[{"w": "戸", "h": "HỘ", "d": "1. nhà; phòng\nVD: 戸主 (chủ hộ)\n2. cửa; cánh cửa; lối ra vào\nVD: 門戸 (cánh cửa)\n3. tửu lượng\nVD: 下戸 (người không uống được rượu)"}, {"w": "方", "h": "PHƯƠNG", "d": "1. hướng\nVD: 方角 (hướng đi), 方向 (phương hướng)\n2. một bộ phận; lĩnh vực; khía cạnh\nVD: 方面 (lĩnh vực), 双方 (đôi bên)\n3. vùng đất; địa phương\nVD: 方言 (tiếng địa phương), 地方 (địa phương)\n4. cách thức; phương pháp; kỹ năng\nVD: 方式 (cách thức), 方法 (phương pháp), 方術 (thuật pháp)\n5.  hình vuông; vuông vức \nVD: 方形 (hình vuông), 方丈 (vuông một trượng)\n6. đúng đắn; ngay ngắn\nVD: 方正 (ngay thẳng)\n7. đang; đúng lúc\nVD: 方今 (hiện nay)\n8. vị; người; phương hướng; thời gian\n(a) kính ngữ chỉ người khác\n(b) người phụ trách\nVD: 裏方 (người làm hậu trường), 煮方 (người nấu)\n(c) chỗ ở; nơi nương tựa\n(d) thời điểm; lúc\nVD: 夕方 (chiều tối)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "房戸", "word": "戸", "hanViet": "HỘ", "detail": "1. nhà; phòng\nVD: 戸主 (chủ hộ)\n2. cửa; cánh cửa; lối ra vào\nVD: 門戸 (cánh cửa)\n3. tửu lượng\nVD: 下戸 (người không uống được rượu)"}, {"id": "房戸一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "房戸尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "房方", "word": "方", "hanViet": "PHƯƠNG", "detail": "1. hướng\nVD: 方角 (hướng đi), 方向 (phương hướng)\n2. một bộ phận; lĩnh vực; khía cạnh\nVD: 方面 (lĩnh vực), 双方 (đôi bên)\n3. vùng đất; địa phương\nVD: 方言 (tiếng địa phương), 地方 (địa phương)\n4. cách thức; phương pháp; kỹ năng\nVD: 方式 (cách thức), 方法 (phương pháp), 方術 (thuật pháp)\n5.  hình vuông; vuông vức \nVD: 方形 (hình vuông), 方丈 (vuông một trượng)\n6. đúng đắn; ngay ngắn\nVD: 方正 (ngay thẳng)\n7. đang; đúng lúc\nVD: 方今 (hiện nay)\n8. vị; người; phương hướng; thời gian\n(a) kính ngữ chỉ người khác\n(b) người phụ trách\nVD: 裏方 (người làm hậu trường), 煮方 (người nấu)\n(c) chỗ ở; nơi nương tựa\n(d) thời điểm; lúc\nVD: 夕方 (chiều tối)"}], "links": [{"source": "房", "target": "房戸"}, {"source": "房戸", "target": "房戸一"}, {"source": "房戸", "target": "房戸尸"}, {"source": "房", "target": "房方"}]}'::jsonb WHERE character = '房' AND char_type = 'KANJI';
