UPDATE writing_characters SET comp_details_json = '[{"w": "辟", "h": "TÍCH", "d": "Vua. Như duy tích tác phúc [惟辟作福] chỉ vua làm được phúc.##Đòi, vời. Như tam trưng thất tích [三徵七辟] ba lần đòi bảy lần vời.##Phép.##Sáng, tỏ.##Một âm là tịch. Hình pháp. Như tội xử tử gọi là đại tịch [大辟].##Trừ bỏ đi.##Lánh ra, lánh đi.##Đánh sợi.##Lại một âm là phích. Cong queo.##Khéo giả bộ.##Vỗ ngực.##Què, khập khiễng.##Một âm là nữa là bễ. Lánh.##Lại một âm nữa là thí. Cùng nghĩa với chữ thí [譬]."}, {"w": "土", "h": "THỔ", "d": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "壁辟", "word": "辟", "hanViet": "TÍCH, TỊCH, PHÍCH, BỄ, THÍ", "detail": "Vua. Như duy tích tác phúc [惟辟作福] chỉ vua làm được phúc.##Đòi, vời. Như tam trưng thất tích [三徵七辟] ba lần đòi bảy lần vời.##Phép.##Sáng, tỏ.##Một âm là tịch. Hình pháp. Như tội xử tử gọi là đại tịch [大辟].##Trừ bỏ đi.##Lánh ra, lánh đi.##Đánh sợi.##Lại một âm là phích. Cong queo.##Khéo giả bộ.##Vỗ ngực.##Què, khập khiễng.##Một âm là nữa là bễ. Lánh.##Lại một âm nữa là thí. Cùng nghĩa với chữ thí [譬]."}, {"id": "壁辟口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "壁辟尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "壁辟辛", "word": "辛", "hanViet": "TÂN", "detail": "1. khổ sở; đau đớn\nVD: 辛苦 (gian khổ), 辛酸 (cay đắng), 辛労 (vất vả)\n2. cay; vị kích thích lưỡi\nVD: 香辛料 (gia vị)\n3. khó khăn lắm mới; vừa vặn\nVD: 辛勝 (thắng lợi sít sao)\n4. Tân (can thứ 8 trong Thập can)\nVD: 辛亥 (năm Canh Hợi)"}, {"id": "壁辟辛立", "word": "立", "hanViet": "LẬP", "detail": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}, {"id": "壁辟辛十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "壁辟辛十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "壁辟辛十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "壁土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}], "links": [{"source": "壁", "target": "壁辟"}, {"source": "壁辟", "target": "壁辟口"}, {"source": "壁辟", "target": "壁辟尸"}, {"source": "壁辟", "target": "壁辟辛"}, {"source": "壁辟辛", "target": "壁辟辛立"}, {"source": "壁辟辛", "target": "壁辟辛十"}, {"source": "壁辟辛十", "target": "壁辟辛十一"}, {"source": "壁辟辛十", "target": "壁辟辛十丨"}, {"source": "壁", "target": "壁土"}]}'::jsonb WHERE character = '壁' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "其", "h": "KÌ", "d": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"w": "木", "h": "MỘC", "d": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "棋其", "word": "其", "hanViet": "KÌ, KÍ, KI", "detail": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"id": "棋木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"id": "棋木大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "棋木大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "棋木大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "棋木丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}], "links": [{"source": "棋", "target": "棋其"}, {"source": "棋", "target": "棋木"}, {"source": "棋木", "target": "棋木大"}, {"source": "棋木大", "target": "棋木大一"}, {"source": "棋木大", "target": "棋木大人"}, {"source": "棋木", "target": "棋木丨"}]}'::jsonb WHERE character = '棋' AND char_type = 'KANJI';
