UPDATE writing_characters SET comp_details_json = '[{"w": "𠫓", "h": "ĐỘT", "d": ""}, {"w": "儿", "h": "NHÂN", "d": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "充𠫓", "word": "𠫓", "hanViet": "", "detail": ""}, {"id": "充𠫓厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "充𠫓亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "充儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}], "links": [{"source": "充", "target": "充𠫓"}, {"source": "充𠫓", "target": "充𠫓厶"}, {"source": "充𠫓", "target": "充𠫓亠"}, {"source": "充", "target": "充儿"}]}'::jsonb WHERE character = '充' AND char_type = 'KANJI';
