UPDATE writing_characters SET comp_details_json = '[{"w": "雇", "h": "CỐ", "d": "thuê; trả tiền công để dùng người\nVD: 雇用 (thuê mướn), 解雇 (sa thải)"}, {"w": "頁", "h": "HIỆT", "d": "Đầu.##Một tờ giấy gọi là nhất hiệt [一頁]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "顧雇", "word": "雇", "hanViet": "CỐ", "detail": "thuê; trả tiền công để dùng người\nVD: 雇用 (thuê mướn), 解雇 (sa thải)"}, {"id": "顧雇隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "顧雇戸", "word": "戸", "hanViet": "HỘ", "detail": "1. nhà; phòng\nVD: 戸主 (chủ hộ)\n2. cửa; cánh cửa; lối ra vào\nVD: 門戸 (cánh cửa)\n3. tửu lượng\nVD: 下戸 (người không uống được rượu)"}, {"id": "顧雇戸一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "顧雇戸尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "顧頁", "word": "頁", "hanViet": "HIỆT", "detail": "Đầu.##Một tờ giấy gọi là nhất hiệt [一頁]."}, {"id": "顧頁丆", "word": "丆", "hanViet": "", "detail": ""}, {"id": "顧頁貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "顧頁貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "顧頁貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}], "links": [{"source": "顧", "target": "顧雇"}, {"source": "顧雇", "target": "顧雇隹"}, {"source": "顧雇", "target": "顧雇戸"}, {"source": "顧雇戸", "target": "顧雇戸一"}, {"source": "顧雇戸", "target": "顧雇戸尸"}, {"source": "顧", "target": "顧頁"}, {"source": "顧頁", "target": "顧頁丆"}, {"source": "顧頁", "target": "顧頁貝"}, {"source": "顧頁貝", "target": "顧頁貝ハ"}, {"source": "顧頁貝", "target": "顧頁貝目"}]}'::jsonb WHERE character = '顧' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "馬", "h": "MÃ", "d": "con ngựa\nVD: 馬脚 (chân ngựa), 騎馬 (cưỡi ngựa)"}, {"w": "区", "h": "KHU", "d": "1. phần được chia; khu vực \nVD: 区域 (khu vực), 学区 (khu vực tuyển sinh)\n2. phân chia; ngăn cách\nVD: 区画 (khu đất), 区別 (phân biệt)\n3. rời rạc; nhỏ bé\nVD: 区区 (tầm thường)\n4. đơn vị hành chính\nVD: 市区 (quận nội thành)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "駆馬", "word": "馬", "hanViet": "MÃ", "detail": "con ngựa\nVD: 馬脚 (chân ngựa), 騎馬 (cưỡi ngựa)"}, {"id": "駆馬隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "駆馬灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}, {"id": "駆区", "word": "区", "hanViet": "KHU, ÂU", "detail": "1. phần được chia; khu vực \nVD: 区域 (khu vực), 学区 (khu vực tuyển sinh)\n2. phân chia; ngăn cách\nVD: 区画 (khu đất), 区別 (phân biệt)\n3. rời rạc; nhỏ bé\nVD: 区区 (tầm thường)\n4. đơn vị hành chính\nVD: 市区 (quận nội thành)"}, {"id": "駆区㐅", "word": "㐅", "hanViet": "", "detail": ""}, {"id": "駆区匚", "word": "匚", "hanViet": "PHƯƠNG", "detail": "Cái đồ để đựng đồ."}], "links": [{"source": "駆", "target": "駆馬"}, {"source": "駆馬", "target": "駆馬隹"}, {"source": "駆馬", "target": "駆馬灬"}, {"source": "駆", "target": "駆区"}, {"source": "駆区", "target": "駆区㐅"}, {"source": "駆区", "target": "駆区匚"}]}'::jsonb WHERE character = '駆' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "昌", "h": "XƯƠNG", "d": "Tương đang, lời nói hay. Như Vũ bái xương ngôn [禹拜昌言] vua Vũ nghe lời nói hay thì kính tạ. Nói thẳng không kỵ húy gì gọi là xương ngôn [昌言].##Sáng sủa. Như xương minh [昌明] sáng láng rõ rệt.##Thịnh. Như bang nãi kì xương [邦乃其昌] nước mới được thịnh. Nguyễn Trãi [阮廌] : Xương kì nhất ngộ hổ sinh phong [昌期一遇虎生風] (Đề kiếm [題劍]) Khi gặp đời thịnh thì hổ sinh ra gió.##Tốt đẹp, đẫy đà.##Vật được thỏa sự sinh sản gọi là xương, vì thế nên trăm vật gọi là bách xương [百昌]."}, {"w": "口", "h": "KHẨU", "d": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "唱昌", "word": "昌", "hanViet": "XƯƠNG", "detail": "Tương đang, lời nói hay. Như Vũ bái xương ngôn [禹拜昌言] vua Vũ nghe lời nói hay thì kính tạ. Nói thẳng không kỵ húy gì gọi là xương ngôn [昌言].##Sáng sủa. Như xương minh [昌明] sáng láng rõ rệt.##Thịnh. Như bang nãi kì xương [邦乃其昌] nước mới được thịnh. Nguyễn Trãi [阮廌] : Xương kì nhất ngộ hổ sinh phong [昌期一遇虎生風] (Đề kiếm [題劍]) Khi gặp đời thịnh thì hổ sinh ra gió.##Tốt đẹp, đẫy đà.##Vật được thỏa sự sinh sản gọi là xương, vì thế nên trăm vật gọi là bách xương [百昌]."}, {"id": "唱昌日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "唱口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}], "links": [{"source": "唱", "target": "唱昌"}, {"source": "唱昌", "target": "唱昌日"}, {"source": "唱", "target": "唱口"}]}'::jsonb WHERE character = '唱' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"w": "夋", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "俊亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "俊夋", "word": "夋", "hanViet": "", "detail": ""}, {"id": "俊夋允", "word": "允", "hanViet": "DUẪN, DOÃN", "detail": "Thành thực.##Đáng. Như bình duẫn [平允] xử đoán phải chăng."}, {"id": "俊夋允厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "俊夋允儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}, {"id": "俊夋夂", "word": "夂", "hanViet": "TRI, TRUY", "detail": "Theo sau mà đến. Ngày xưa dùng như chữ chung [終]. $ Chữ này [夂] viết không có nét ló ra phía trên góc bên trái, khác với chữ tuy [夊] có nét ló ra phía trên góc bên trái."}], "links": [{"source": "俊", "target": "俊亻"}, {"source": "俊", "target": "俊夋"}, {"source": "俊夋", "target": "俊夋允"}, {"source": "俊夋允", "target": "俊夋允厶"}, {"source": "俊夋允", "target": "俊夋允儿"}, {"source": "俊夋", "target": "俊夋夂"}]}'::jsonb WHERE character = '俊' AND char_type = 'KANJI';
