UPDATE writing_characters SET comp_details_json = '[{"w": "廾", "h": "CỦNG", "d": "Chắp tay."}, {"w": "戈", "h": "QUA", "d": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "戒廾", "word": "廾", "hanViet": "CỦNG", "detail": "Chắp tay."}, {"id": "戒廾十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "戒廾十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "戒廾十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "戒戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}], "links": [{"source": "戒", "target": "戒廾"}, {"source": "戒廾", "target": "戒廾十"}, {"source": "戒廾十", "target": "戒廾十一"}, {"source": "戒廾十", "target": "戒廾十丨"}, {"source": "戒", "target": "戒戈"}]}'::jsonb WHERE character = '戒' AND char_type = 'KANJI';
