UPDATE writing_characters SET comp_details_json = '[{"w": "乃", "h": "NÃI", "d": "Bèn, tiếng nói nối câu trên. Tô Thức [蘇軾] : Dư nãi nhiếp y nhi thướng [予乃攝衣而上] (Hậu Xích Bích phú [後赤壁賦]) Tôi bèn vén áo mà lên.##Tiếng gọi mày tao. Như nãi huynh [乃兄] anh mày, nãi đệ [乃第] em mày.##Một âm là ái. Như ai ái [欸乃] lối hát chèo đò. $ Có chỗ viết là [廼], cũng một nghĩa như chữ [乃]."}, {"w": "隹", "h": "CHUY", "d": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "携乃", "word": "乃", "hanViet": "NÃI, ÁI", "detail": "Bèn, tiếng nói nối câu trên. Tô Thức [蘇軾] : Dư nãi nhiếp y nhi thướng [予乃攝衣而上] (Hậu Xích Bích phú [後赤壁賦]) Tôi bèn vén áo mà lên.##Tiếng gọi mày tao. Như nãi huynh [乃兄] anh mày, nãi đệ [乃第] em mày.##Một âm là ái. Như ai ái [欸乃] lối hát chèo đò. $ Có chỗ viết là [廼], cũng một nghĩa như chữ [乃]."}, {"id": "携乃ㄋ", "word": "ㄋ", "hanViet": "", "detail": ""}, {"id": "携乃ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "携隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "携扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}], "links": [{"source": "携", "target": "携乃"}, {"source": "携乃", "target": "携乃ㄋ"}, {"source": "携乃", "target": "携乃ノ"}, {"source": "携", "target": "携隹"}, {"source": "携", "target": "携扌"}]}'::jsonb WHERE character = '携' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "毎", "h": "MỖI", "d": "1. mỗi; thường xuyên; luôn luôn\nVD: 毎次 (mỗi lần), 毎毎 (thường xuyên)\n2. tham lam; tìm kiếm"}, {"w": "攵", "h": "PHỘC", "d": "strike, hit, folding chair radical variant (no. 66)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "敏毎", "word": "毎", "hanViet": "MỖI", "detail": "1. mỗi; thường xuyên; luôn luôn\nVD: 毎次 (mỗi lần), 毎毎 (thường xuyên)\n2. tham lam; tìm kiếm"}, {"id": "敏毎𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "敏毎毋", "word": "毋", "hanViet": "VÔ, MƯU", "detail": "Chớ, đừng.##Chớ, dùng làm tiếng giúp lời. Như vô nãi [毋乃] chớ bèn (cùng nghĩa với hoặc giả [或者]); tương vô [將毋] hầu chớ, v.v. đều là lời hỏi lấy ý mình đoán mà chưa dám quyết đoán.##Một âm là mưu. Hẳn. Mưu đôi [毋追] một thứ mũ vải đen."}, {"id": "敏攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}], "links": [{"source": "敏", "target": "敏毎"}, {"source": "敏毎", "target": "敏毎𠂉"}, {"source": "敏毎", "target": "敏毎毋"}, {"source": "敏", "target": "敏攵"}]}'::jsonb WHERE character = '敏' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "旉", "h": "PHU", "d": "Cũng như chữ phu [敷]"}, {"w": "攵", "h": "PHỘC", "d": "strike, hit, folding chair radical variant (no. 66)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "敷旉", "word": "旉", "hanViet": "PHU", "detail": "Cũng như chữ phu [敷]"}, {"id": "敷旉甫", "word": "甫", "hanViet": "PHỦ", "detail": "Tiếng gọi tôn quý của đàn ông. Như đức Khổng Tử gọi là Ni phủ [尼甫].##Tên chữ biểu hiệu, cho nên hỏi tên tự người ta thì nói là thai phủ [台甫].##Cha, mình nói đến cha người khác thì kêu là tôn phủ [尊甫].##Vừa mới. Như phủ nhập môn [甫入門] vừa bước vào cửa.##Lớn."}, {"id": "敷旉甫用", "word": "用", "hanViet": "DỤNG", "detail": "1. dùng; sử dụng; làm cho có ích \nVD: 用意 (chuẩn bị), 使用 (sử dụng)\n2. cách dùng; mục đích sử dụng\nVD: 薬用 (dùng làm thuốc), 浴用 (dùng để tắm)\n3. tác dụng; hiệu quả\nVD: 作用 (tác dụng), 効用 (hiệu quả)\n4. đi đại tiểu tiện\nVD: 用便 (đi vệ sinh)\n5. bằng; nhờ vào\n6. chi phí hoặc vật dụng cần thiết\nVD: 用度 (chi phí), 費用 (chi phí)\n7. công việc phải làm\nVD: 用件 (việc cần bàn), 所用 (việc riêng)"}, {"id": "敷旉甫十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "敷旉甫十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "敷旉甫十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "敷旉甫丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "敷旉方", "word": "方", "hanViet": "PHƯƠNG", "detail": "1. hướng\nVD: 方角 (hướng đi), 方向 (phương hướng)\n2. một bộ phận; lĩnh vực; khía cạnh\nVD: 方面 (lĩnh vực), 双方 (đôi bên)\n3. vùng đất; địa phương\nVD: 方言 (tiếng địa phương), 地方 (địa phương)\n4. cách thức; phương pháp; kỹ năng\nVD: 方式 (cách thức), 方法 (phương pháp), 方術 (thuật pháp)\n5.  hình vuông; vuông vức \nVD: 方形 (hình vuông), 方丈 (vuông một trượng)\n6. đúng đắn; ngay ngắn\nVD: 方正 (ngay thẳng)\n7. đang; đúng lúc\nVD: 方今 (hiện nay)\n8. vị; người; phương hướng; thời gian\n(a) kính ngữ chỉ người khác\n(b) người phụ trách\nVD: 裏方 (người làm hậu trường), 煮方 (người nấu)\n(c) chỗ ở; nơi nương tựa\n(d) thời điểm; lúc\nVD: 夕方 (chiều tối)"}, {"id": "敷攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}], "links": [{"source": "敷", "target": "敷旉"}, {"source": "敷旉", "target": "敷旉甫"}, {"source": "敷旉甫", "target": "敷旉甫用"}, {"source": "敷旉甫", "target": "敷旉甫十"}, {"source": "敷旉甫十", "target": "敷旉甫十一"}, {"source": "敷旉甫十", "target": "敷旉甫十丨"}, {"source": "敷旉甫", "target": "敷旉甫丶"}, {"source": "敷旉", "target": "敷旉方"}, {"source": "敷", "target": "敷攵"}]}'::jsonb WHERE character = '敷' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "牜", "h": "NGƯU", "d": "ox, cow, cow radical (no. 93)"}, {"w": "義", "h": "NGHĨA", "d": "1. lý do; ý nghĩa\nVD: 義解 (giải thích ý nghĩa), 字義 (nghĩa của chữ)\n2. quan hệ thân tộc không cùng huyết thống\nVD: 義父 (cha nuôi)\n3. giả; thay thế\nVD: 義歯 (răng giả)\n4. đạo lý; lẽ phải; nghĩa khí \nVD: 義人 (nghĩa nhân), 信義 (tín nghĩa)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "犠牜", "word": "牜", "hanViet": "NGƯU", "detail": "ox, cow, cow radical (no. 93)"}, {"id": "犠義", "word": "義", "hanViet": "NGHĨA", "detail": "1. lý do; ý nghĩa\nVD: 義解 (giải thích ý nghĩa), 字義 (nghĩa của chữ)\n2. quan hệ thân tộc không cùng huyết thống\nVD: 義父 (cha nuôi)\n3. giả; thay thế\nVD: 義歯 (răng giả)\n4. đạo lý; lẽ phải; nghĩa khí \nVD: 義人 (nghĩa nhân), 信義 (tín nghĩa)"}, {"id": "犠義我", "word": "我", "hanViet": "NGÃ", "detail": "ta; mình; bản thân; của mình\nVD: 我見 (ý kiến bản thân), 我慢 (chịu đựng), 自我 (bản ngã), 我を張る (khăng khăng theo ý mình)"}, {"id": "犠義我戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "犠義我扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"id": "犠義𦍌", "word": "𦍌", "hanViet": "", "detail": ""}], "links": [{"source": "犠", "target": "犠牜"}, {"source": "犠", "target": "犠義"}, {"source": "犠義", "target": "犠義我"}, {"source": "犠義我", "target": "犠義我戈"}, {"source": "犠義我", "target": "犠義我扌"}, {"source": "犠義", "target": "犠義𦍌"}]}'::jsonb WHERE character = '犠' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "蒦", "h": "HOẠCH", "d": "to measure, to calculate"}, {"w": "犭", "h": "KHUYỂN", "d": "Bộ Khuyển (biến thể bộ Khuyển 犬: chó, thú vật)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "獲蒦", "word": "蒦", "hanViet": "HOẠCH", "detail": "to measure, to calculate"}, {"id": "獲蒦萑", "word": "萑", "hanViet": "HOÀN, CHUY", "detail": "Cỏ hoàn, cỏ lau.##Một âm là chuy. Cỏ bượp, cỏ mọc nhiều.##Cỏ ích mẫu."}, {"id": "獲蒦萑隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "獲蒦萑艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "獲蒦又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}, {"id": "獲犭", "word": "犭", "hanViet": "KHUYỂN", "detail": "Bộ Khuyển (biến thể bộ Khuyển 犬: chó, thú vật)"}], "links": [{"source": "獲", "target": "獲蒦"}, {"source": "獲蒦", "target": "獲蒦萑"}, {"source": "獲蒦萑", "target": "獲蒦萑隹"}, {"source": "獲蒦萑", "target": "獲蒦萑艹"}, {"source": "獲蒦", "target": "獲蒦又"}, {"source": "獲", "target": "獲犭"}]}'::jsonb WHERE character = '獲' AND char_type = 'KANJI';
