UPDATE writing_characters SET comp_details_json = '[{"w": "敏", "h": "MẪN", "d": "1. nhanh nhẹn; mau lẹ\nVD: 敏速 (nhanh chóng), 敏捷 (nhanh nhẹn), 機を見るに敏だ (nhạy bén nắm bắt thời cơ)\n2. nhạy cảm; thông minh; sáng suốt\nVD: 敏感 (nhạy cảm), 鋭敏 (nhạy bén)"}, {"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "繁敏", "word": "敏", "hanViet": "MẪN", "detail": "1. nhanh nhẹn; mau lẹ\nVD: 敏速 (nhanh chóng), 敏捷 (nhanh nhẹn), 機を見るに敏だ (nhạy bén nắm bắt thời cơ)\n2. nhạy cảm; thông minh; sáng suốt\nVD: 敏感 (nhạy cảm), 鋭敏 (nhạy bén)"}, {"id": "繁敏毎", "word": "毎", "hanViet": "MỖI", "detail": "1. mỗi; thường xuyên; luôn luôn\nVD: 毎次 (mỗi lần), 毎毎 (thường xuyên)\n2. tham lam; tìm kiếm"}, {"id": "繁敏毎𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "繁敏毎毋", "word": "毋", "hanViet": "VÔ, MƯU", "detail": "Chớ, đừng.##Chớ, dùng làm tiếng giúp lời. Như vô nãi [毋乃] chớ bèn (cùng nghĩa với hoặc giả [或者]); tương vô [將毋] hầu chớ, v.v. đều là lời hỏi lấy ý mình đoán mà chưa dám quyết đoán.##Một âm là mưu. Hẳn. Mưu đôi [毋追] một thứ mũ vải đen."}, {"id": "繁敏攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}, {"id": "繁糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}], "links": [{"source": "繁", "target": "繁敏"}, {"source": "繁敏", "target": "繁敏毎"}, {"source": "繁敏毎", "target": "繁敏毎𠂉"}, {"source": "繁敏毎", "target": "繁敏毎毋"}, {"source": "繁敏", "target": "繁敏攵"}, {"source": "繁", "target": "繁糸"}]}'::jsonb WHERE character = '繁' AND 