UPDATE writing_characters SET comp_details_json = '[{"w": "虍", "h": "HÔ", "d": "Vằn con hổ, vằn con vện."}, {"w": "儿", "h": "NHÂN", "d": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "虎虍", "word": "虍", "hanViet": "HÔ", "detail": "Vằn con hổ, vằn con vện."}, {"id": "虎虍卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "虎虍厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "虎虍七", "word": "七", "hanViet": "THẤT", "detail": "1. số bảy\nVD: 七賢 (bảy vị hiền triết), 七夕 (lễ Thất tịch), 七曜 (bảy ngày trong tuần)\n2. nhiều; số lượng lớn\nVD: 七珍万宝 (muôn vàn châu báu)"}, {"id": "虎儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}], "links": [{"source": "虎", "target": "虎虍"}, {"source": "虎虍", "target": "虎虍卜"}, {"source": "虎虍", "target": "虎虍厂"}, {"source": "虎虍", "target": "虎虍七"}, {"source": "虎", "target": "虎儿"}]}'::jsonb WHERE character = '虎' AND char_type = 'KANJI';
