UPDATE writing_characters SET comp_details_json = '[{"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"w": "罔", "h": "VÕNG", "d": "Cái lưới đánh chim đánh cá. Ngày xưa viết là [网], bây giờ hay viết là [網].##Giáng võng [降罔] giáng tội, mắc vào lưới tội.##Vu khống, lừa. Nguyễn Trãi [阮廌] : Khi thiên võng thượng [欺天罔上] (Hạ tiệp [賀捷]) Dối trời lừa vua.##Không, dùng làm trợ từ. Như võng hoang vu du [罔荒于遊] chớ có chơi bời hoang đãng.##Không thẳng."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "網糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"id": "網罔", "word": "罔", "hanViet": "VÕNG", "detail": "Cái lưới đánh chim đánh cá. Ngày xưa viết là [网], bây giờ hay viết là [網].##Giáng võng [降罔] giáng tội, mắc vào lưới tội.##Vu khống, lừa. Nguyễn Trãi [阮廌] : Khi thiên võng thượng [欺天罔上] (Hạ tiệp [賀捷]) Dối trời lừa vua.##Không, dùng làm trợ từ. Như võng hoang vu du [罔荒于遊] chớ có chơi bời hoang đãng.##Không thẳng."}, {"id": "網罔冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "網罔亡", "word": "亡", "hanViet": "VONG, VÔ", "detail": "1. không có; mất đi; chết\nVD: 亡霊 (vong linh), 死亡 (tử vong)\n2. mất; đánh mất\nVD: 亡失 (mất mát), 損亡 (tổn thất)\n3. diệt vong; tiêu diệt \nVD: 亡国 (nước mất), 興亡 (hưng thịnh và suy vong)\n4. chạy trốn\nVD: 亡命 (lưu vong), 逃亡 (bỏ trốn)"}, {"id": "網罔亡𠃊", "word": "𠃊", "hanViet": "", "detail": ""}, {"id": "網罔亡亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "網罔䒑", "word": "䒑", "hanViet": "", "detail": ""}], "links": [{"so