UPDATE writing_characters SET comp_details_json = '[{"w": "之", "h": "CHI", "d": "Chưng, dùng về lời nói liền nối nhau. Như đại học chi đạo [大學之道] chưng đạo đại học.##Đi. Như Đằng Văn Công tương chi Sở [滕文公將之楚] Đằng Văn Công sắp đi sang nước Sở.##Đến. Như chi tử mỹ tha [之死靡他] đến chết chẳng tới ai.##Đấy, là tiếng dùng thay một danh từ nào. Như Thang sử nhân vấn chi [湯使人問之] vua Thang khiến người hỏi đấy (hỏi ai ? tức là hỏi Cát Bá, chữ chi đây là thay hai chữ Cát Bá).##Ấy. Như chi tử vu quy [之子于歸] người ấy về nhà chồng."}, {"w": "艹", "h": "THẢO", "d": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "芝之", "word": "之", "hanViet": "CHI", "detail": "Chưng, dùng về lời nói liền nối nhau. Như đại học chi đạo [大學之道] chưng đạo đại học.##Đi. Như Đằng Văn Công tương chi Sở [滕文公將之楚] Đằng Văn Công sắp đi sang nước Sở.##Đến. Như chi tử mỹ tha [之死靡他] đến chết chẳng tới ai.##Đấy, là tiếng dùng thay một danh từ nào. Như Thang sử nhân vấn chi [湯使人問之] vua Thang khiến người hỏi đấy (hỏi ai ? tức là hỏi Cát Bá, chữ chi đây là thay hai chữ Cát Bá).##Ấy. Như chi tử vu quy [之子于歸] người ấy về nhà chồng."}, {"id": "芝艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}], "links": [{"source": "芝", "target": "芝之"}, {"source": "芝", "target": "芝艹"}]}'::jsonb WHERE character = '芝' AND char_type = 'KANJI';
