UPDATE writing_characters SET comp_details_json = '[{"w": "戌", "h": "TUẤT", "d": "Chi Tuất, chi thứ mười trong 12 chi. Từ 7 giờ tối đến 9 giờ tối là giờ Tuất.##Khuất tuất [屈戌] cái kê-môn (crémone, espagnolette); làm bằng một thanh sắt đứng, khi vặn tay nắm, kéo lên hạ xuống được, để đóng cánh cửa."}, {"w": "女", "h": "NỮ", "d": "1. phụ nữ; phái nữ \nVD: 女王 (nữ hoàng), 女性 (phụ nữ), 女流 (nữ giới)\n2. con gái; thiếu nữ\nVD: 少女 (thiếu nữ), 処女 (con gái chưa chồng), 息女 (con gái người khác)\n3. nhà ngươi; mày \n4. gả đi; cho đi lấy chồng"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "威戌", "word": "戌", "hanViet": "TUẤT", "detail": "Chi Tuất, chi thứ mười trong 12 chi. Từ 7 giờ tối đến 9 giờ tối là giờ Tuất.##Khuất tuất [屈戌] cái kê-môn (crémone, espagnolette); làm bằng một thanh sắt đứng, khi vặn tay nắm, kéo lên hạ xuống được, để đóng cánh cửa."}, {"id": "威戌戊", "word": "戊", "hanViet": "MẬU", "detail": "Can Mậu [戊], can thứ năm trong mười can."}, {"id": "威戌戊戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "威戌一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "威女", "word": "女", "hanViet": "NỮ, NỨ, NHỮ", "detail": "1. phụ nữ; phái nữ \nVD: 女王 (nữ hoàng), 女性 (phụ nữ), 女流 (nữ giới)\n2. con gái; thiếu nữ\nVD: 少女 (thiếu nữ), 処女 (con gái chưa chồng), 息女 (con gái người khác)\n3. nhà ngươi; mày \n4. gả đi; cho đi lấy chồng"}], "links": [{"source": "威", "target": "威戌"}, {"source": "威戌", "target": "威戌戊"}, {"source": "威戌戊", "target": "威戌戊戈"}, {"source": "威戌", "target": "威戌一"}, {"source": "威", "target": "威女"}]}'::jsonb WHERE character = '威' AND char_type = 'KANJI';
