UPDATE writing_characters SET comp_details_json = '[{"w": "尉", "h": "ÚY", "d": "1. cấp úy (cấp bậc quân đội)\nVD: 尉官 (sĩ quan cấp úy)\n2. <i>jou</i> (quan bậc ba tại Vệ môn phủ và Binh vệ phủ)"}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "慰尉", "word": "尉", "hanViet": "ÚY, UẤT", "detail": "1. cấp úy (cấp bậc quân đội)\nVD: 尉官 (sĩ quan cấp úy)\n2. <i>jou</i> (quan bậc ba tại Vệ môn phủ và Binh vệ phủ)"}, {"id": "慰尉示", "word": "示", "hanViet": "KÌ, THỊ", "detail": "cho thấy; chỉ ra; trình bày\nVD: 示威 (thị uy), 掲示 (niêm yết), 図示 (minh họa bằng hình vẽ)"}, {"id": "慰尉示二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "慰尉示小", "word": "小", "hanViet": "TIỂU", "detail": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"id": "慰尉寸", "word": "寸", "hanViet": "THỐN", "detail": "1. chiều dài\nVD: 寸法 (kích thước), 原寸 (kích thước thực tế)\n2. một chút; một ít; một lát\nVD: 寸暇 (chút thời gian rảnh rỗi), 寸志 (chút lòng thành), 寸時 (giây lát)\n3. đơn vị đo chiều cao của ngựa\nVD: 一寸 (một đơn vị đo chiều cao ngựa)\n4. đơn vị đo chiều dài trong hệ Thước Quán (khoảng 3,03 cm)"}, {"id": "慰尉尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "慰心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}], "links": [{"source": "慰", "target": "慰尉"}, {"source": "慰尉", "target": "慰尉示"}, {"source": "慰尉示", "target": "慰尉示二"}, {"source": "慰尉示", "target": "慰尉示小"}, {"source": "慰尉", "target": "慰尉寸"}, {"source": "慰尉", "target": "慰尉尸"}, {"source": "慰", "target": "慰心"}]}'::jsonb WHERE character = '慰' AND char_type = 'KANJI';
