UPDATE writing_characters SET comp_details_json = '[{"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}, {"w": "烕", "h": "DIỆT", "d": "to destroy, to exterminate, to extinguish"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "滅氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}, {"id": "滅烕", "word": "烕", "hanViet": "DIỆT", "detail": "to destroy, to exterminate, to extinguish"}, {"id": "滅烕火", "word": "火", "hanViet": "HỎA", "detail": "1. lửa; ngọn lửa\nVD: 火気 (nguồn nhiệt), 火炎 (ngọn lửa), 発火 (bắt lửa)\n2. hỏa (một trong ngũ hành)\n3. thứ Ba\n4. ánh sáng; ngọn đèn\nVD: 漁火 (lửa chài), 灯火 (ánh đèn)\n5. cháy; đốt\nVD: 火災 (hỏa hoạn), 火事 (đám cháy)\n6. cảm xúc mãnh liệt, cháy bỏng\nVD: 情火 (ngọn lửa tình)\n7. vội vã; cấp bách\nVD: 火急 (khẩn cấp)"}, {"id": "滅烕火丷", "word": "丷", "hanViet": "", "detail": ""}, {"id": "滅烕火人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "滅烕戌", "word": "戌", "hanViet": "TUẤT", "detail": "Chi Tuất, chi thứ mười trong 12 chi. Từ 7 giờ tối đến 9 giờ tối là giờ Tuất.##Khuất tuất [屈戌] cái kê-môn (crémone, espagnolette); làm bằng một thanh sắt đứng, khi vặn tay nắm, kéo lên hạ xuống được, để đóng cánh cửa."}, {"id": "滅烕戌戊", "word": "戊", "hanViet": "MẬU", "detail": "Can Mậu [戊], can thứ năm trong mười can."}, {"id": "滅烕戌戊戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "滅烕戌一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}], "links": [{"source": "滅", "target": "滅氵"}, {"source": "滅", "target": "滅烕"}, {"source": "滅烕", "target": "滅烕火"}, {"source": "滅烕火", "target": "滅烕火丷"}, {"source": "滅烕火", "target": "滅烕火人"}, {"source": "滅烕", "target": "滅烕戌"}, {"source": "滅烕戌", "target": "滅烕戌戊"}, {"source": "滅烕戌戊", "target": "滅烕戌戊戈"}, {"source": "滅烕戌", "target": "滅烕戌一"}]}'::jsonb WHERE character = '滅' AND char_type = 'KANJI';
