UPDATE writing_characters SET comp_details_json = '[{"w": "戸", "h": "HỘ", "d": "1. nhà; phòng\nVD: 戸主 (chủ hộ)\n2. cửa; cánh cửa; lối ra vào\nVD: 門戸 (cánh cửa)\n3. tửu lượng\nVD: 下戸 (người không uống được rượu)"}, {"w": "火", "h": "HỎA", "d": "1. lửa; ngọn lửa\nVD: 火気 (nguồn nhiệt), 火炎 (ngọn lửa), 発火 (bắt lửa)\n2. hỏa (một trong ngũ hành)\n3. thứ Ba\n4. ánh sáng; ngọn đèn\nVD: 漁火 (lửa chài), 灯火 (ánh đèn)\n5. cháy; đốt\nVD: 火災 (hỏa hoạn), 火事 (đám cháy)\n6. cảm xúc mãnh liệt, cháy bỏng\nVD: 情火 (ngọn lửa tình)\n7. vội vã; cấp bách\nVD: 火急 (khẩn cấp)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "炉戸", "word": "戸", "hanViet": "HỘ", "detail": "1. nhà; phòng\nVD: 戸主 (chủ hộ)\n2. cửa; cánh cửa; lối ra vào\nVD: 門戸 (cánh cửa)\n3. tửu lượng\nVD: 下戸 (người không uống được rượu)"}, {"id": "炉戸一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "炉戸尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "炉火", "word": "火", "hanViet": "HỎA", "detail": "1. lửa; ngọn lửa\nVD: 火気 (nguồn nhiệt), 火炎 (ngọn lửa), 発火 (bắt lửa)\n2. hỏa (một trong ngũ hành)\n3. thứ Ba\n4. ánh sáng; ngọn đèn\nVD: 漁火 (lửa chài), 灯火 (ánh đèn)\n5. cháy; đốt\nVD: 火災 (hỏa hoạn), 火事 (đám cháy)\n6. cảm xúc mãnh liệt, cháy bỏng\nVD: 情火 (ngọn lửa tình)\n7. vội vã; cấp bách\nVD: 火急 (khẩn cấp)"}, {"id": "炉火丷", "word": "丷", "hanViet": "", "detail": ""}, {"id": "炉火人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}], "links": [{"source": "炉", "target": "炉戸"}, {"source": "炉戸", "target": "炉戸一"}, {"source": "炉戸", "target": "炉戸尸"}, {"source": "炉", "target": "炉火"}, {"source": "炉火", "target": "炉火丷"}, {"source": "炉火", "target": "炉火人"}]}'::jsonb WHERE character = '炉' AND char_type = 'KANJI';
