UPDATE writing_characters SET comp_details_json = '[{"w": "牙", "h": "NHA", "d": "1. răng nanh; ngà\nVD: 牙爪 (nanh vuốt), 牙牌 (thẻ bài bằng ngà)\n2. cờ hiệu; doanh trại nơi cắm cờ này (cờ của vua hoặc tướng quân)\nVD: 牙旗 (cờ lệnh), 牙城 (thành trì), 牙門 (cổng doanh trại)\n3. răng\nVD: 歯牙 (răng)\n4. người môi giới; người trung gian\nVD: 牙郎 (người môi giới)"}, {"w": "艹", "h": "THẢO", "d": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "芽牙", "word": "牙", "hanViet": "NHA", "detail": "1. răng nanh; ngà\nVD: 牙爪 (nanh vuốt), 牙牌 (thẻ bài bằng ngà)\n2. cờ hiệu; doanh trại nơi cắm cờ này (cờ của vua hoặc tướng quân)\nVD: 牙旗 (cờ lệnh), 牙城 (thành trì), 牙門 (cổng doanh trại)\n3. răng\nVD: 歯牙 (răng)\n4. người môi giới; người trung gian\nVD: 牙郎 (người môi giới)"}, {"id": "芽牙ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "芽牙于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "芽牙于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "芽牙于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}, {"id": "芽艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}], "links": [{"source": "芽", "target": "芽牙"}, {"source": "芽牙", "target": "芽牙ノ"}, {"source": "芽牙", "target": "芽牙于"}, {"source": "芽牙于", "target": "芽牙于二"}, {"source": "芽牙于", "target": "芽牙于亅"}, {"source": "芽", "target": "芽艹"}]}'::jsonb WHERE character = '芽' AND char_type = 'KANJI';
