UPDATE writing_characters SET comp_details_json = '[{"w": "辟", "h": "TÍCH", "d": "Vua. Như duy tích tác phúc [惟辟作福] chỉ vua làm được phúc.##Đòi, vời. Như tam trưng thất tích [三徵七辟] ba lần đòi bảy lần vời.##Phép.##Sáng, tỏ.##Một âm là tịch. Hình pháp. Như tội xử tử gọi là đại tịch [大辟].##Trừ bỏ đi.##Lánh ra, lánh đi.##Đánh sợi.##Lại một âm là phích. Cong queo.##Khéo giả bộ.##Vỗ ngực.##Què, khập khiễng.##Một âm là nữa là bễ. Lánh.##Lại một âm nữa là thí. Cùng nghĩa với chữ thí [譬]."}, {"w": "疒", "h": "NẠCH", "d": "Tật bệnh."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "癖辟", "word": "辟", "hanViet": "TÍCH, TỊCH, PHÍCH, BỄ, THÍ", "detail": "Vua. Như duy tích tác phúc [惟辟作福] chỉ vua làm được phúc.##Đòi, vời. Như tam trưng thất tích [三徵七辟] ba lần đòi bảy lần vời.##Phép.##Sáng, tỏ.##Một âm là tịch. Hình pháp. Như tội xử tử gọi là đại tịch [大辟].##Trừ bỏ đi.##Lánh ra, lánh đi.##Đánh sợi.##Lại một âm là phích. Cong queo.##Khéo giả bộ.##Vỗ ngực.##Què, khập khiễng.##Một âm là nữa là bễ. Lánh.##Lại một âm nữa là thí. Cùng nghĩa với chữ thí [譬]."}, {"id": "癖辟口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "癖辟尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "癖辟辛", "word": "辛", "hanViet": "TÂN", "detail": "1. khổ sở; đau đớn\nVD: 辛苦 (gian khổ), 辛酸 (cay đắng), 辛労 (vất vả)\n2. cay; vị kích thích lưỡi\nVD: 香辛料 (gia vị)\n3. khó khăn lắm mới; vừa vặn\nVD: 辛勝 (thắng lợi sít sao)\n4. Tân (can thứ 8 trong Thập can)\nVD: 辛亥 (năm Canh Hợi)"}, {"id": "癖辟辛立", "word": "立", "hanViet": "LẬP", "detail": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}, {"id": "癖辟辛十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "癖辟辛十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "癖辟辛十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "癖疒", "word": "疒", "hanViet": "NẠCH", "detail": "Tật bệnh."}], "links": [{"source": "癖", "target": "癖辟"}, {"source": "癖辟", "target": "癖辟口"}, {"source": "癖辟", "target": "癖辟尸"}, {"source": "癖辟", "target": "癖辟辛"}, {"source": "癖辟辛", "target": "癖辟辛立"}, {"source": "癖辟辛", "target": "癖辟辛十"}, {"source": "癖辟辛十", "target": "癖辟辛十一"}, {"source": "癖辟辛十", "target": "癖辟辛十丨"}, {"source": "癖", "target": "癖疒"}]}'::jsonb WHERE character = '癖' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "段", "h": "ĐOẠN", "d": "1. đoạn; chỗ ngắt; chia nhỏ\nVD: 段落 (đoạn văn), 分段 (chia đoạn)\n2. bậc; bậc thang; cầu thang\nVD: 段丘 (địa hình bậc thang), 階段 (cầu thang)\n3. phương pháp; cách thức\nVD: 算段 (xoay xở), 手段 (phương pháp)\n4. trình độ kỹ năng\nVD: 段位 (cấp bậc), 昇段 (thăng cấp)\n5. hơn hẳn; hơn một bậc\nVD: 一段 (hơn một bậc), 格段 (đáng kể)\n6. <i>tan</i> (đơn vị đo lường cổ của Nhật Bản)\n(a) đơn vị đo chiều dài của vải, khoảng 10 mét \n(b) đơn vị diện tích đất; khoảng 10 are (1000m²) \nVD: 段別 (diện tích ruộng đất tính theo đơn vị <i>tan</i>)\n(c) đơn vị khoảng cách, khoảng 11 mét "}, {"w": "金", "h": "KIM", "d": "1. kim loại\nVD: 金属 (kim loại), 合金 (hợp kim)\n2. kim (một trong ngũ hành)\n3. thứ Sáu\n4. vàng; vàng ròng\nVD: 金塊 (vàng thỏi), 純金 (vàng nguyên chất)\n5. tuyệt vời; đẹp đẽ\nVD: 金言 (lời vàng ý ngọc), 金剛 (kim cương)\n6. tiền bạc; tiền tệ\nVD: 金額 (số tiền), 貯金 (tiền tiết kiệm)\n7. viết tắt của quân Kim tướng trong cờ "}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "鍛段", "word": "段", "hanViet": "ĐOẠN", "detail": "1. đoạn; chỗ ngắt; chia nhỏ\nVD: 段落 (đoạn văn), 分段 (chia đoạn)\n2. bậc; bậc thang; cầu thang\nVD: 段丘 (địa hình bậc thang), 階段 (cầu thang)\n3. phương pháp; cách thức\nVD: 算段 (xoay xở), 手段 (phương pháp)\n4. trình độ kỹ năng\nVD: 段位 (cấp bậc), 昇段 (thăng cấp)\n5. hơn hẳn; hơn một bậc\nVD: 一段 (hơn một bậc), 格段 (đáng kể)\n6. <i>tan</i> (đơn vị đo lường cổ của Nhật Bản)\n(a) đơn vị đo chiều dài của vải, khoảng 10 mét \n(b) đơn vị diện tích đất; khoảng 10 are (1000m²) \nVD: 段別 (diện tích ruộng đất tính theo đơn vị <i>tan</i>)\n(c) đơn vị khoảng cách, khoảng 11 mét "}, {"id": "鍛段乍", "word": "乍", "hanViet": "SẠ", "detail": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"id": "鍛段乍𠂉", "word": "𠂉", "hanViet": "", "detail