UPDATE writing_characters SET comp_details_json = '[{"w": "其", "h": "KÌ", "d": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"w": "欠", "h": "KHIẾM", "d": "1. (ケツ) nghỉ; hủy bỏ \nVD: 欠航 (hủy chuyến), 欠席 (vắng mặt)\n2. (ケツ) sứt; mẻ; thiếu hụt \nVD: 欠落 (thiếu hụt), 補欠 (dự bị)\n3. (ケン) ngáp\nVD: 欠伸 (ngáp)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "欺其", "word": "其", "hanViet": "KÌ, KÍ, KI", "detail": "Thửa, lời nói chỉ vào chỗ nào. Như kì nhân kì sự [其人其事] người ấy sự ấy.##Một âm là kí. Như bỉ kí chi tử [彼其之子] con người như thế kia.##Lại một âm là ki, lời nói đưa đẩy. Như dạ như hà ki [夜如何其] đêm thế nào kia, đêm thế nào ư !"}, {"id": "欺欠", "word": "欠", "hanViet": "KHIẾM", "detail": "1. (ケツ) nghỉ; hủy bỏ \nVD: 欠航 (hủy chuyến), 欠席 (vắng mặt)\n2. (ケツ) sứt; mẻ; thiếu hụt \nVD: 欠落 (thiếu hụt), 補欠 (dự bị)\n3. (ケン) ngáp\nVD: 欠伸 (ngáp)"}, {"id": "欺欠人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "欺欠⺈", "word": "⺈", "hanViet": "", "detail": ""}], "links": [{"source": "欺", "target": "欺其"}, {"source": "欺", "target": "欺欠"}, {"source": "欺欠", "target": "欺欠人"}, {"source": "欺欠", "target": "欺欠⺈"}]}'::jsonb WHERE character = '欺' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "乍", "h": "SẠ", "d": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"w": "言", "h": "NGÔN", "d": "1. nói; phát biểu; trình bày\nVD: 言論 (phát ngôn), 断言 (khẳng định)\n2. lời nói; ngôn từ\nVD: 言行 (lời nói và hành động), 金言 (lời vàng ý ngọc)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "詐乍", "word": "乍", "hanViet": "SẠ", "detail": "Chợt, thốt nhiên xảy ra gọi là sạ [乍]. Như kim nhân sạ kiến nhụ tử [今人乍見孺子] nay người chợt thấy đứa bé. Nguyễn Du [阮攸] : Ngã sạ kiến chi bi thả tân [我乍見之悲且辛] (Thái Bình mại ca giả [太平賣歌者]) Ta chợt thấy vậy vừa đau buồn vừa chua xót."}, {"id": "詐乍𠂉", "word": "𠂉", "hanViet": "", "detail": "Thành phần nét phẩy và nét ngang"}, {"id": "詐乍二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "詐乍丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "詐言", "word": "言", "hanViet": "NGÔN, NGÂN", "detail": "1. nói; phát biểu; trình bày\nVD: 言論 (phát ngôn), 断言 (khẳng định)\n2. lời nói; ngôn từ\nVD: 言行 (lời nói và hành động), 金言 (lời vàng ý ngọc)"}, {"id": "詐言一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "詐言口