UPDATE writing_characters SET comp_details_json = '[{"w": "虫", "h": "TRÙNG", "d": "1. sâu bọ; côn trùng\nVD: 益虫 (côn trùng có ích), 幼虫 (ấu trùng)\n2. các loài động vật nói chung"}, {"w": "它", "h": "THA", "d": "Đời xưa dùng như chữ đà [佗] không phải, khác.##Ngày xưa dùng như chữ xà [蛇]. Đời thượng cổ ở hang ở tổ, hay bị rắn cắn, nên hỏi thăm nhau đều hỏi vô xà hồ [無它乎] nghĩa là không việc gì chứ ?"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "蛇虫", "word": "虫", "hanViet": "TRÙNG", "detail": "1. sâu bọ; côn trùng\nVD: 益虫 (côn trùng có ích), 幼虫 (ấu trùng)\n2. các loài động vật nói chung"}, {"id": "蛇虫一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "蛇虫丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "蛇虫中", "word": "中", "hanViet": "TRUNG, TRÚNG", "detail": "1. chính giữa\nVD: 中央 (trung ương), 中心 (trung tâm), 中核 (cốt lõi)\n2. bên trong phạm vi; phía trong\nVD: 意中 (trong lòng), 車中 (trong xe), 忌中 (trong thời gian chịu tang)\n3. khoảng giữa; đoạn giữa trong 3 đoạn\nVD: 中等 (tầm trung), 中流 (tầng lớp trung lưu), 中盤 (giai đoạn giữa)\n4. ở giữa; khoảng cách giữa hai bên\nVD: 中間 (trung gian), 中継 (phát sóng), 中腹 (sườn núi)\n5. suốt; toàn bộ\nVD: 年中 (quanh năm), 世界中 (trên toàn thế giới)\n6. viết tắt của trung học hoặc Trung Quốc\nVD: 中卒 (tốt nghiệp trung học), 訪中 (thăm Trung Quốc)\n7. không thiên vị\nVD: 中立 (trung lập), 中道 (trung đạo), 折中 (dung )\n8. trúng; nhắm trúng\nVD: 中毒 (trúng độc), 命中 (trúng đích)\n9. mọi người; trong nhóm bạn bè\nVD: 講中 (nhóm tín đồ), 連中 (đám người)"}, {"id": "蛇虫中口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "蛇虫中丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "蛇它", "word": "它", "hanViet": "THA, XÀ", "detail": "Đời xưa dùng như chữ đà [佗] không phải, khác.##Ngày xưa dùng như chữ xà [蛇]. Đời thượng cổ ở hang ở tổ, hay bị rắn cắn, nên hỏi thăm nhau đều hỏi vô xà hồ [無它乎] nghĩa là không việc gì chứ ?"}, {"id": "蛇它匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}, {"id": "蛇它宀", "word": "宀", "hanViet": "MIÊN", "detail": "Lợp trùm nhà ngoài với nhà trong."}], "links": [{"source": "蛇", "target": "蛇虫"}, {"source": "蛇虫", "target": "蛇虫一"}, {"source": "蛇虫", "target": "蛇虫丶"}, {"source": "蛇虫", "target": "蛇虫中"}, {"source": "蛇虫中", "target": "蛇虫中口"}, {"source": "蛇虫中", "target": "蛇虫中丨"}, {"source": "蛇", "target": "蛇它"}, {"source": "蛇它", "target": "蛇它匕"}, {"source": "蛇它", "target": "蛇它宀"}]}'::jsonb WHERE character = '蛇' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "辰", "h": "THẦN", "d": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"w": "寸", "h": "THỐN", "d": "1. chiều dài\nVD: 寸法 (kích thước), 原寸 (kích thước thực tế)\n2. một chút; một ít; một lát\nVD: 寸暇 (chút thời gian rảnh rỗi), 寸志 (chút lòng thành), 寸時 (giây lát)\n3. đơn vị đo chiều cao của ngựa\nVD: 一寸 (một đơn vị đo chiều cao ngựa)\n4. đơn vị đo chiều dài trong hệ Thước Quán (khoảng 3,03 cm)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "辱辰", "word": "辰", "hanViet": "THẦN, THÌN", "detail": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"id": "辱辰二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "辱辰𧘇", "word": "𧘇", "hanViet": "", "detail": ""}, {"id": "辱辰厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "辱寸", "word": "寸", "hanViet": "THỐN", "detail": "1. chiều dài\nVD: 寸法 (kích thước), 原寸 (kích thước thực tế)\n2. một chút; một ít; một lát\nVD: 寸暇 (chút thời gian rảnh rỗi), 寸志 (chút lòng thành), 寸時 (giây lát)\n3. đơn vị đo chiều cao của ngựa\nVD: 一寸 (một đơn vị đo chiều cao ngựa)\n4. đơn vị đo chiều dài trong hệ 