UPDATE writing_characters SET comp_details_json = '[{"w": "而", "h": "NHI", "d": "Mày. Như nhi ông [而翁] cha mày.##Mà, vậy, dùng làm trợ ngữ. Như nhi kim an tại [而今安在] mà nay còn đâu, dĩ nhi [已而] đã mà.##Bèn, lời nói chuyển xuống. Như nhi mưu động can qua ư bang nội [而謀動干戈於邦內] bèn mưu khởi sự đánh nhau ở trong nước.##Lông má."}, {"w": "寸", "h": "THỐN", "d": "1. chiều dài\nVD: 寸法 (kích thước), 原寸 (kích thước thực tế)\n2. một chút; một ít; một lát\nVD: 寸暇 (chút thời gian rảnh rỗi), 寸志 (chút lòng thành), 寸時 (giây lát)\n3. đơn vị đo chiều cao của ngựa\nVD: 一寸 (một đơn vị đo chiều cao ngựa)\n4. đơn vị đo chiều dài trong hệ Thước Quán (khoảng 3,03 cm)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "耐而", "word": "而", "hanViet": "NHI", "detail": "Mày. Như nhi ông [而翁] cha mày.##Mà, vậy, dùng làm trợ ngữ. Như nhi kim an tại [而今安在] mà nay còn đâu, dĩ nhi [已而] đã mà.##Bèn, lời nói chuyển xuống. Như nhi mưu động can qua ư bang nội [而謀動干戈於邦內] bèn mưu khởi sự đánh nhau ở trong nước.##Lông má."}, {"id": "耐寸", "word": "寸", "hanViet": "THỐN", "detail": "1. chiều dài\nVD: 寸法 (kích thước), 原寸 (kích thước thực tế)\n2. một chút; một ít; một lát\nVD: 寸暇 (chút thời gian rảnh rỗi), 寸志 (chút lòng thành), 寸時 (giây lát)\n3. đơn vị đo chiều cao của ngựa\nVD: 一寸 (một đơn vị đo chiều cao ngựa)\n4. đơn vị đo chiều dài trong hệ Thước Quán (khoảng 3,03 cm)"}], "links": [{"source": "耐", "target": "耐而"}, {"source": "耐", "target": "耐寸"}]}'::jsonb WHERE character = '耐' AND char_type = 'KANJI';
