UPDATE writing_characters SET comp_details_json = '[{"w": "王", "h": "VƯƠNG", "d": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"w": "刂", "h": "ĐAO", "d": "Một hình thức của bộ đao [刀]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "班王", "word": "王", "hanViet": "VƯƠNG, VƯỢNG", "detail": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"id": "班王一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "班王土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "班刂", "word": "刂", "hanViet": "ĐAO", "detail": "Một hình thức của bộ đao [刀]."}], "links": [{"source": "班", "target": "班王"}, {"source": "班王", "target": "班王一"}, {"source": "班王", "target": "班王土"}, {"source": "班", "target": "班刂"}]}'::jsonb WHERE character = '班' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "余", "h": "DƯ", "d": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"w": "斗", "h": "ĐẤU", "d": "1. tên chòm sao (ở phương nam và phương bắc của bầu trời)\nVD: 南斗 (sao Nam Đẩu), 北斗 (sao Bắc Đẩu)\n2. cái đấu; cái gáo; vật có hình cái đấu hoặc cái gáo\nVD: 科斗 (nòng nọc)\n3. đấu (đơn vị đo dung tích)\nVD: 斗酒 (một đấu rượu)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "斜余", "word": "余", "hanViet": "DƯ", "detail": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"id": "斜余𠆢", "word": "𠆢", "hanViet": "", "detail": ""}, {"id": "斜余于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "斜余于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "斜余于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}, {"id": "斜余ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "斜斗", "word": "斗", "hanViet": "ĐẤU, ĐẨU", "detail": "1. tên chòm sao (ở phương nam và phương bắc của bầu trời)\nVD: 南斗 (sao Nam Đẩu), 北斗 (sao Bắc Đẩu)\n2. cái đấu; cái gáo; vật có hình cái đấu hoặc cái gáo\nVD: 科斗 (nòng nọc)\n3. đấu (đơn vị đo dung tích)\nVD: 斗酒 (một đấu rượu)"}, {"id": "斜斗十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "斜斗十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "斜斗十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "斜斗丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}], "links": [{"source": "斜", "target": "斜余"}, {"source": "斜余", "target": "斜余𠆢"}, {"source": "斜余", "target": "斜余于"}, {"source": "斜余于", "target": "斜余于二"}, {"source": "斜余于", "target": "斜余于亅"}, {"source": "斜余", "target": "斜余ハ"}, {"source": "斜", "target": "斜斗"}, {"source": "斜斗", "target": "斜斗十"}, {"source": "斜斗十", "target": "斜斗十一"}, {"source": "斜斗十", "target": "斜斗十丨"}, {"source": "斜斗", "target": "斜斗丶"}]}'::jsonb WHERE character = '斜' AND char_type = 'KANJI';
