UPDATE writing_characters SET comp_details_json = '[{"w": "此", "h": "THỬ", "d": "Ấy, bên ấy, đối lại với chữ bỉ [彼].##Thế, lời nói chỉ định hẳn hoi. Như kỳ tự nhâm dĩ thiên hạ trọng như thử [其自任以天下之重如此] thửa gánh vác lấy công việc nặng nề trong thiên hạ như thế.##Ấy, bèn. Như hữu đức thử hữu nhân [有德此有人] (Đại học [大學]) có đức ấy (bèn) có người."}, {"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "紫此", "word": "此", "hanViet": "THỬ", "detail": "Ấy, bên ấy, đối lại với chữ bỉ [彼].##Thế, lời nói chỉ định hẳn hoi. Như kỳ tự nhâm dĩ thiên hạ trọng như thử [其自任以天下之重如此] thửa gánh vác lấy công việc nặng nề trong thiên hạ như thế.##Ấy, bèn. Như hữu đức thử hữu nhân [有德此有人] (Đại học [大學]) có đức ấy (bèn) có người."}, {"id": "紫此止", "word": "止", "hanViet": "CHỈ", "detail": "1. ngăn chặn; đình chỉ; cầm\nVD: 止血 (cầm máu), 禁止 (cấm)\n2. dừng; bãi bỏ\nVD: 中止 (hoãn lại), 廃止 (bãi bỏ)\n3. dừng lại; ở lại\nVD: 止宿 (trọ lại)\n4. dáng vẻ; cử chỉ\nVD: 挙止 (cử chỉ)"}, {"id": "紫此匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}, {"id": "紫糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}], "links": [{"source": "紫", "target": "紫此"}, {"source": "紫此", "target": "紫此止"}, {"source": "紫此", "target": "紫此匕"}, {"source": "紫", "target": "紫糸"}]}'::jsonb WHERE character = '紫' AND char_type = 'KANJI';
