UPDATE writing_characters SET comp_details_json = '[{"w": "忄", "h": "TÂM", "d": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}, {"w": "吾", "h": "NGÔ", "d": "Ta, tới mình mà nói gọi là ngô. Nhân người mà nói gọi là ngã [我]. Như ngã thiện dưỡng ngô hạo nhiên chi khí [我善養吾浩然之氣] ta khéo nuôi cái khí hạo nhiên của ta.##Chống giữ. Phép quan nhà Hán có chức chấp kim ngô [執金吾] ý là cầm cái đồ binh để chống giữ việc phi thường."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "悟忄", "word": "忄", "hanViet": "TÂM", "detail": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}, {"id": "悟吾", "word": "吾", "hanViet": "NGÔ", "detail": "Ta, tới mình mà nói gọi là ngô. Nhân người mà nói gọi là ngã [我]. Như ngã thiện dưỡng ngô hạo nhiên chi khí [我善養吾浩然之氣] ta khéo nuôi cái khí hạo nhiên của ta.##Chống giữ. Phép quan nhà Hán có chức chấp kim ngô [執金吾] ý là cầm cái đồ binh để chống giữ việc phi thường."}, {"id": "悟吾五", "word": "五", "hanViet": "NGŨ", "detail": "năm; số năm\nVD: 五感 (năm giác quan), 五穀 (năm loại ngũ cốc)"}, {"id": "悟吾口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}], "links": [{"source": "悟", "target": "悟忄"}, {"source": "悟", "target": "悟吾"}, {"source": "悟吾", "target": "悟吾五"}, {"source": "悟吾", "target": "悟吾口"}]}'::jsonb WHERE character = '悟' AND char_type = 'KANJI';
