UPDATE writing_characters SET comp_details_json = '[{"w": "閏", "h": "NHUẬN", "d": "Thừa. Lịch Tàu theo vòng quả đất xoay chung quanh mặt trời mà tính năm, theo vòng mặt trăng xoay chung quanh quả đất mà tính tháng, theo vòng quả đất tự xoay mà tính ngày, cứ hết mỗi một vòng quả đất xoay chung quanh mặt trời thì mặt trăng đã xoay chung quanh quả đất được mười hai vòng và một phần ba vòng nữa, cho nên mỗi năm lại thừa ra hơn mười ngày, tính số thừa ấy lại thì hai năm rưỡi lại thừa ra một tháng, tháng thừa ấy gọi là nhuận nguyệt [閏月] tháng thừa. Lịch tây theo mặt trời tính năm, cứ hết một vòng quả đất xoay chung quanh mặt trời thì quả đất nó tự xoay mình nó được 365 vòng và lẻ một phần tư, cho nên tích bốn năm thì lại thừa một ngày gọi là nhuận nhật [閏日] ngày thừa. Năm nào có ngày nhuận thì cho vào tháng hai là 29 ngày."}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "潤閏", "word": "閏", "hanViet": "NHUẬN", "detail": "Thừa. Lịch Tàu theo vòng quả đất xoay chung quanh mặt trời mà tính năm, theo vòng mặt trăng xoay chung quanh quả đất mà tính tháng, theo vòng quả đất tự xoay mà tính ngày, cứ hết mỗi một vòng quả đất xoay chung quanh mặt trời thì mặt trăng đã xoay chung quanh quả đất được mười hai vòng và một phần ba vòng nữa, cho nên mỗi năm lại thừa ra hơn mười ngày, tính số thừa ấy lại thì hai năm rưỡi lại thừa ra một tháng, tháng thừa ấy gọi là nhuận nguyệt [閏月] tháng thừa. Lịch tây theo mặt trời tính năm, cứ hết một vòng quả đất xoay chung quanh mặt trời thì quả đất nó tự xoay mình nó được 365 vòng và lẻ một phần tư, cho nên tích bốn năm thì lại thừa một ngày gọi là nhuận nhật [閏日] ngày thừa. Năm nào có ngày nhuận thì cho vào tháng hai là 29 ngày."}, {"id": "潤閏王", "word": "王", "hanViet": "VƯƠNG, VƯỢNG", "detail": "1. vua; quân chủ một nước\nVD: 王宮 (hoàng cung), 王朝 (vương triều), 国王 (vua)\n2. người mạnh nhất; người đứng đầu\nVD: 王座 (ngai vàng), 王者 (kẻ thống trị)"}, {"id": "潤閏王一", "word