UPDATE writing_characters SET comp_details_json = '[{"w": "⻏", "h": "", "d": ""}, {"w": "牙", "h": "NHA", "d": "1. răng nanh; ngà\nVD: 牙爪 (nanh vuốt), 牙牌 (thẻ bài bằng ngà)\n2. cờ hiệu; doanh trại nơi cắm cờ này (cờ của vua hoặc tướng quân)\nVD: 牙旗 (cờ lệnh), 牙城 (thành trì), 牙門 (cổng doanh trại)\n3. răng\nVD: 歯牙 (răng)\n4. người môi giới; người trung gian\nVD: 牙郎 (người môi giới)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "邪⻏", "word": "⻏", "hanViet": "", "detail": ""}, {"id": "邪牙", "word": "牙", "hanViet": "NHA", "detail": "1. răng nanh; ngà\nVD: 牙爪 (nanh vuốt), 牙牌 (thẻ bài bằng ngà)\n2. cờ hiệu; doanh trại nơi cắm cờ này (cờ của vua hoặc tướng quân)\nVD: 牙旗 (cờ lệnh), 牙城 (thành trì), 牙門 (cổng doanh trại)\n3. răng\nVD: 歯牙 (răng)\n4. người môi giới; người trung gian\nVD: 牙郎 (người môi giới)"}, {"id": "邪牙ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "邪牙于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "邪牙于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "邪牙于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}], "links": [{"source": "邪", "target": "邪⻏"}, {"source": "邪", "target": "邪牙"}, {"source": "邪牙", "target": "邪牙ノ"}, {"source": "邪牙", "target": "邪牙于"}, {"source": "邪牙于", "target": "邪牙于二"}, {"source": "邪牙于", "target": "邪牙于亅"}]}'::jsonb WHERE character = '邪' AND char_type = 'KANJI';
