UPDATE writing_characters SET comp_details_json = '[{"w": "賁", "h": "BÍ", "d": "Rực rỡ, sáng sủa. Như trong thơ từ thường dùng chữ bí lâm [賁臨] nghĩa là ngài hạ cố tới nhà tôi thì nhà tôi được rạng rỡ thêm. Tô Mạn Thù [蘇曼殊] : Thỉnh đại sư bí lâm thư trai tiện phạn [請大師賁臨書齋便飯] (Đoạn hồng linh nhạn kí [斷鴻零雁記]) Kính mời Đại sư rời gót sang thư trai dùng cơm.##Một âm là phần. To lớn. Như dụng hoành tư phần [用宏茲賁] dùng càng rộng lớn.##Lại một âm là bôn. Dũng sĩ. Như hổ bôn [虎賁] đạo quân hùng tráng của vua."}, {"w": "土", "h": "THỔ", "d": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "墳賁", "word": "賁", "hanViet": "BÍ, PHẦN, BÔN", "detail": "Rực rỡ, sáng sủa. Như trong thơ từ thường dùng chữ bí lâm [賁臨] nghĩa là ngài hạ cố tới nhà tôi thì nhà tôi được rạng rỡ thêm. Tô Mạn Thù [蘇曼殊] : Thỉnh đại sư bí lâm thư trai tiện phạn [請大師賁臨書齋便飯] (Đoạn hồng linh nhạn kí [斷鴻零雁記]) Kính mời Đại sư rời gót sang thư trai dùng cơm.##Một âm là phần. To lớn. Như dụng hoành tư phần [用宏茲賁] dùng càng rộng lớn.##Lại một âm là bôn. Dũng sĩ. Như hổ bôn [虎賁] đạo quân hùng tráng của vua."}, {"id": "墳賁十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "墳賁十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "墳賁十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "墳賁艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "墳賁貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "墳賁貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "墳賁貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}, {"id": "墳土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}], "links": [{"source": "墳", "target": "墳賁"}, {"source": "墳賁", "target": "墳賁十"}, {"source": "墳賁十", "target": "墳賁十一"}, {"source": "墳賁十", "target": "墳賁十丨"}, {"source": "墳賁", "target": "墳賁艹"}, {"source": "墳賁", "target": "墳賁貝"}, {"source": "墳賁貝", "target": "墳賁貝ハ"}, {"source": "墳賁貝", "target": "墳賁貝目"}, {"source": "墳", "target": "墳土"}]}'::jsonb WHERE character = '墳' AND char_type = 'KANJI';
