UPDATE writing_characters SET comp_details_json = '[{"w": "雍", "h": "UNG", "d": "Hòa hợp, hòa mục. Nguyên là chữ [雝]. Như ung dung [雍容] thong thả hòa nhã.##Một âm là úng. Úng châu [雍州] một châu trong chín châu nước Tàu ngày xưa, tức là vùng Thiểm Tây [陝西], Cam Túc [甘肅], Thanh Hải [青海] bây giờ.##Ta quen đọc là ung cả."}, {"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "擁雍", "word": "雍", "hanViet": "UNG, ÚNG", "detail": "Hòa hợp, hòa mục. Nguyên là chữ [雝]. Như ung dung [雍容] thong thả hòa nhã.##Một âm là úng. Úng châu [雍州] một châu trong chín châu nước Tàu ngày xưa, tức là vùng Thiểm Tây [陝西], Cam Túc [甘肅], Thanh Hải [青海] bây giờ.##Ta quen đọc là ung cả."}, {"id": "擁雍隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "擁雍乡", "word": "乡", "hanViet": "", "detail": ""}, {"id": "擁雍亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "擁扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}], "links": [{"source": "擁", "target": "擁雍"}, {"source": "擁雍", "target": "擁雍隹"}, {"source": "擁雍", "target": "擁雍乡"}, {"source": "擁雍", "target": "擁雍亠"}, {"source": "擁", "target": "擁扌"}]}'::jsonb WHERE character = '擁' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "孑", "h": "KIẾT", "d": "Đơn chiếc. Như mĩ hữu kiết di [靡有孑遺] chẳng còn một ai. Trơ trọi. Như kiết nhiên độc lập [孑然獨立] trơ trọi đứng một mình.##Kiết củng [孑孒] con bọ gậy, sau hóa ra con muỗi.##Cái kích không có mũi nhọn."}, {"w": "瓜", "h": "QUA", "d": "Dưa, các thứ dưa có quả đều gọi là qua.##Qua kì [瓜期] đổi thay chức việc, hẹn người này đến thay người kia gọi là qua kì.##Con gái đến mười sáu tuổi gọi là phá qua [破瓜], vì chữ qua [瓜] giống hình hai chữ bát [八], tức mười sáu.##Qua lý [瓜李] nói sự hiềm nghi, xỏ giầy ở ruộng dưa người ta ngờ là hái dưa, đội lại mũ ở dưới cây mận, người ta ngờ là hái mận, dẫu ngay người ta cũng ngờ rằng gian : qua điền bất nạp lý, lý hạ bất chỉnh quan [瓜田不納履，李下不整冠].##Qua cát [瓜葛] kẻ thân thích. Hai họ không có liên thuộc gì với nhau mà vì các ngành dây dưa với nhau mới nên thân thích gọi là qua cát."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "孤孑", "word": "孑", "hanViet": "KIẾT", "detail": "Đơn chiếc. Như mĩ hữu kiết di [靡有孑遺] chẳng còn một ai. Trơ trọi. Như kiết nhiên độc lập [孑然獨立] trơ trọi đứng một mình.##Kiết củng [孑孒] con bọ gậy, sau hóa ra con muỗi.##Cái kích không có mũi nhọn."}, {"id": "孤瓜", "word": "瓜", "hanViet": "QUA", "detail": "Dưa, các thứ dưa có quả đều gọi là qua.##Qua kì [瓜期] đổi thay chức việc, hẹn người này đến thay người kia gọi là qua kì.##Con gái đến mười sáu tuổi gọi là phá qua [破瓜], vì chữ qua [瓜] giống hình hai chữ bát [八], tức mười sáu.##Qua lý [瓜李] nói sự hiềm nghi, xỏ giầy ở ruộng dưa người ta ngờ là hái dưa, đội lại mũ ở dưới cây mận, người ta ngờ là hái mận, dẫu ngay người ta cũng ngờ rằng gian : qua điền bất nạp lý, lý hạ bất chỉnh quan [瓜田不納履，李下不整冠].##Qua cát [瓜葛] kẻ thân thích. Hai họ không có liên thuộc gì với nhau mà vì các ngành dây dưa với nhau mới nên thân thích gọi là qua cát."}, {"id": "孤瓜厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "孤瓜爪", "word": "爪", "hanViet": "TRẢO", "detail": "móng; vật có hình dạng cái móng\nVD: 爪痕 (vết móng), 琴爪 (móng gảy đàn tranh koto)"}], "links": [{"source": "孤", "target": "孤孑"}, {"source": "孤", "target": "孤瓜"}, {"source": "孤瓜", "target": "孤瓜厶"}, {"source": "孤瓜", "target": "孤瓜爪"}]}'::jsonb WHERE character = '孤' AND char_type = 'KANJI';
