UPDATE writing_characters SET comp_details_json = '[{"w": "扁", "h": "BIỂN", "d": "Giẹt, cái gì rộng mà mỏng gọi là biển. Viết chữ ngang trên cửa trên cổng gọi là biển, ta gọi là hoành.##Một âm là thiên. Nhỏ. Như thiên chu [扁舟] thuyền nhỏ. Nguyễn Du [阮攸] : Thiên địa thiên chu phù tự diệp [天地扁舟浮以葉] (Chu hành tức sự [舟行即事]) Chiếc thuyền con như chiếc lá nổi giữa đất trời."}, {"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "偏扁", "word": "扁", "hanViet": "BIỂN, THIÊN", "detail": "Giẹt, cái gì rộng mà mỏng gọi là biển. Viết chữ ngang trên cửa trên cổng gọi là biển, ta gọi là hoành.##Một âm là thiên. Nhỏ. Như thiên chu [扁舟] thuyền nhỏ. Nguyễn Du [阮攸] : Thiên địa thiên chu phù tự diệp [天地扁舟浮以葉] (Chu hành tức sự [舟行即事]) Chiếc thuyền con như chiếc lá nổi giữa đất trời."}, {"id": "偏扁冊", "word": "冊", "hanViet": "SÁCH", "detail": "1. sách; tập sách\nVD: 冊子 (tập sách nhỏ), 別冊 (tập đặc biệt)\n2. đơn vị đếm sách\nVD: 冊数 (số quyển), 一冊 (một quyển)\n3. lập; dựng lên\n4. thẻ; giấy ghi chép\n5. sắc phong thiên tử (Trung Quốc)\nVD: 冊命 (chiếu chỉ sắc phong)"}, {"id": "偏扁冊廾", "word": "廾", "hanViet": "CỦNG", "detail": "Chắp tay."}, {"id": "偏扁冊廾十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "偏扁冊廾十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "偏扁冊廾十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "偏扁冊冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "偏扁戶", "word": "戶", "hanViet": "", "detail": ""}, {"id": "偏亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}], "links": [{"source": "偏", "target": "偏扁"}, {"source": "偏扁", "target": "偏扁冊"}, {"source": "偏扁冊", "target": "偏扁冊廾"}, {"source": "偏扁冊廾", "target": "偏扁冊廾十"}, {"source": "偏扁冊廾十", "target": "偏扁冊廾十一"}, {"source": "偏扁冊廾十", "target": "偏扁冊廾十丨"}, {"source": "偏扁冊", "target": "偏扁冊冂"}, {"source": "偏扁", "target": "偏扁戶"}, {"source": "偏", "target": "偏亻"}]}'::jsonb WHERE character = '偏' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "禺", "h": "NGU", "d": "Tên núi, tên đất.##Khu, mỗi khu mười dặm là một ngu."}, {"w": "⻌", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "遇禺", "word": "禺", "hanViet": "NGU", "detail": "Tên núi, tên đất.##Khu, mỗi khu mười dặm là một ngu."}, {"id": "遇禺禸", "word": "禸", "hanViet": "NHỰU", "detail": "Vết ngón chân giống thú dẫm xuống đất."}, {"id": "遇禺禸冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "遇禺禸厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "遇禺田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "遇⻌", "word": "⻌", "hanViet": "", "detail": ""}], "links": [{"source": "遇", "target": "遇禺"}, {"source": "遇禺", "target": "遇禺禸"}, {"source": "遇禺禸", "target": "遇禺禸冂"}, {"source": "遇禺禸", "target": "遇禺禸厶"}, {"source": "遇禺", "target": "遇禺田"}, {"source": "遇", "target": "遇⻌"}]}'::jsonb WHERE character = '遇' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "量", "h": "LƯỢNG", "d": "1. đo lường\n(a) đo trọng lượng, thể tích...\nVD: 計量 (đo lường), 測量 (đo đạc địa lý)\n(b) suy đoán; cân nhắc\nVD: 推量 (suy đoán), 裁量 (tự quyết định), 酌量 (châm chước)\n2. sức lực; sự rộng lượng; năng lực\nVD: 度量 (độ lượng), 器量 (tài năng)\n3. lượng; thể tích\nVD: 容量 (dung lượng), 分量 (liều lượng)\n4. dụng cụ đo; cái đấu\nVD: 量器 (dụng cụ đo), 量衡 (cân đo) "}, {"w": "米", "h": "MỄ", "d": "1. gạo; hạt lúa\nVD: 米穀 (thóc gạo), 玄米 (gạo lứt), 精米 (gạo trắng)\n2. viết tắt của nước Mỹ\nVD: 米国 (nước Mỹ), 渡米 (đi Mỹ)\n3. mét (đơn vị đo)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "糧量", "word": "量", "hanViet": "LƯỢNG, LƯƠNG", "detail": "1. đo lường\n(a) đo trọng lượng, thể tích...\nVD: 計量 (đo lường), 測量 (đo đạc địa lý)\n(b) suy đoán; cân nhắc\nVD: 推量 (suy đoán), 裁量 (tự quyết định), 酌量 (châm chước)\n2. sức lực; sự rộng lượng; năng lực\nVD: 度量 (độ lượng), 器量 (tài năng)\n3. lượng; thể tích\nVD: 容量 (dung lượng), 分量 (liều lượng)\n4. dụng cụ đo; cái đấu\nVD: 量器 (dụng cụ đo), 量衡 (cân đo) "}, {"id": "糧量旦", "word": "旦", "hanViet": "ĐÁN", "detail": "buổi sáng; bình minh \nVD: 元旦 (sáng mùng một Tết)"}, {"id": "糧量旦日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "糧量旦一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên t