UPDATE writing_characters SET comp_details_json = '[{"w": "𢦏", "h": "", "d": "Hán Việt: "}, {"w": "业", "h": "NGHIỆP", "d": ""}, {"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "繊𢦏", "word": "𢦏", "hanViet": "", "detail": "Hán Việt: "}, {"id": "繊𢦏十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "繊𢦏十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "繊𢦏十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "繊𢦏戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "繊业", "word": "业", "hanViet": "", "detail": ""}, {"id": "繊糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}], "links": [{"source": "繊", "target": "繊𢦏"}, {"source": "繊𢦏", "target": "繊𢦏十"}, {"source": "繊𢦏十", "target": "繊𢦏十一"}, {"source": "繊𢦏十", "target": "繊𢦏十丨"}, {"source": "繊𢦏", "target": "繊𢦏戈"}, {"source": "繊", "target": "繊业"}, {"source": "繊", "target": "繊糸"}]}'::jsonb WHERE character = '繊' AND char_type = 'KANJI';
