UPDATE writing_characters SET comp_details_json = '[{"w": "参", "h": "THAM", "d": "1. đi; đến chỗ người bề trên; thăm hỏi\nVD: 参上 (đến, có mặt), 見参 (gặp mặt)\n2. đi lễ đền chùa\nVD: 参詣 (đi lễ chùa), 墓参 (thăm mộ)\n3. chữ thay thế cho 三 (số ba)\n4. thua đối thủ; đầu hàng\nVD: 降参 (đầu hàng)\n5. giao lưu; tham gia; tập trung\nVD: 参会 (tham dự hội nghị), 参列 (tham dự lễ)\n6. không đồng đều\nVD: 参差 (không đều)\n7. so sánh; tra cứu\nVD: 参考 (tham khảo), 参照 (tham chiếu)"}, {"w": "忄", "h": "TÂM", "d": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "惨参", "word": "参", "hanViet": "THAM, XAM, SÂM", "detail": "1. đi; đến chỗ người bề trên; thăm hỏi\nVD: 参上 (đến, có mặt), 見参 (gặp mặt)\n2. đi lễ đền chùa\nVD: 参詣 (đi lễ chùa), 墓参 (thăm mộ)\n3. chữ thay thế cho 三 (số ba)\n4. thua đối thủ; đầu hàng\nVD: 降参 (đầu hàng)\n5. giao lưu; tham gia; tập trung\nVD: 参会 (tham dự hội nghị), 参列 (tham dự lễ)\n6. không đồng đều\nVD: 参差 (không đều)\n7. so sánh; tra cứu\nVD: 参考 (tham khảo), 参照 (tham chiếu)"}, {"id": "惨参大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "惨参大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "惨参大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "惨参厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "惨参彡", "word": "彡", "hanViet": "SAM, TIỆM", "detail": "Lông dài.##Một âm là tiệm. Tiệm thả [彡姐] tên họ, giống rợ Khương."}, {"id": "惨忄", "word": "忄", "hanViet": "TÂM", "detail": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}], "links": [{"source": "惨", "target": "惨参"}, {"source": "惨参", "target": "惨参大"}, {"source": "惨参大", "target": "惨参大一"}, {"source": "惨参大", "target": "惨参大人"}, {"source": "惨参", "target": "惨参厶"}, {"source": "惨参", "target": "惨参彡"}, {"source": "惨", "target": "惨忄"}]}'::jsonb WHERE character = '惨' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "虍", "h": "HÔ", "d": "Vằn con hổ, vằn con vện."}, {"w": "一", "h": "NHẤT", "d": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"w": "匚", "h": "PHƯƠNG", "d": "Cái đồ để đựng đồ."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "虐虍", "word": "虍", "hanViet": "HÔ", "detail": "Vằn con hổ, vằn con vện."}, {"id": "虐虍卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "虐虍厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "虐虍七", "word": "七", "hanViet": "THẤT", "detail": "1. số bảy\nVD: 七賢 (bảy vị hiền triết), 七夕 (lễ Thất tịch), 七曜 (bảy ngày trong tuần)\n2. nhiều; số lượng lớn\nVD: 七珍万宝 (muôn vàn châu báu)"}, {"id": "虐一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "虐匚", "word": "匚", "hanViet": "PHƯƠNG", "detail": "Cái đồ để đựng đồ."}], "links": [{"source": "虐", "target": "虐虍"}, {"source": "虐虍", "target": "虐虍卜"}, {"source": "虐虍", "target": "虐虍厂"}, {"source": "虐虍", "target": "虐虍七"}, {"source": "虐", "target": "虐一"}, {"source": "虐", "target": "虐匚"}]}'::jsonb WHERE character = '虐' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "扌", "h": "THỦ", "d": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"w": "居", "h": "CƯ", "d": "1. cư trú; nơi ở\nVD: 居宅 (nhà ở), 居留 (nơi cư trú), 住居 (chỗ ở)\n2. ở; có mặt; ngồi\nVD: 起居 (sinh hoạt hằng ngày)\n3. tại chỗ; nguyên trạng\nVD: 居然 (y nguyên)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "据扌", "word": "扌", "hanViet": "THỦ", "detail": "Bộ Tài gảy (biến thể bộ Thủ 手: bàn tay, hành động)"}, {"id": "据居", "word": "居", "hanViet": "CƯ, KÍ", "detail": "1. cư trú; nơi ở\nVD: 居宅 (nhà ở), 居留 (nơi cư trú), 住居 (chỗ ở)\n2. ở; có mặt; ngồi\nVD: 起居 (sinh hoạt hằng ngày)\n3. tại chỗ; nguyên trạng\nVD: 居然 (y nguyên)"}, {"id": "据居古", "word": "古", "hanViet": "CỔ", "detail": "1. cũ; cổ xưa  \nVD: 古参 (kỳ cựu), 古風 (phong cách cổ xưa)\n2. quá khứ đã qua; ngày xưa  \nVD: 古代 (thời cổ đại), 懐古 (hoài niệm)\n3. đồ cũ; dùng lâu thành cũ"}, {"id": "据居古十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "据居古十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "据居古十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "据居古口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "据居尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}], "links": [{"source": "据", "target": "据扌"}, {"source": "据", "target": "据居"}, {"source": "据居", "target": "据居古"}, {"source": "据居古", "target": "据居古十"}, {"source": "据居古十", "target": "据居古十一"}, {"source": "据居古十", "target": "据居古十丨"}, {"source": "据居古", "target": "据居古口"}, {"source": "据居", "target": "据居尸"}]}'::jsonb WHERE character = '据' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "余", "h": "DƯ", "d": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"w": "彳", "h": "XÍCH", "d": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "徐余", "word": "余", "hanViet": "DƯ", "detail": "1. khác; ngoài ra\nVD: 余興 (tiết mục góp vui), 余念 (ý nghĩ khác)\n2. thừa; phần dư; phần còn lại\nVD: 余生 (quãng đời còn lại), 余力 (sức lực còn dư), 残余 (phần còn lại)\n3. tôi; ta (đại từ nhân xưng) \nVD: 余輩 (chúng ta)"}, {"id": "徐余𠆢", "word": "𠆢", "hanViet": "", "detail": ""}, {"id": "徐余于", "word": "于", "hanViet": "VU, HU, Ư, Ô", "detail": "Đi. Như vu quy [于歸] con gái đi lấy chồng.##Đi lấy. Như trú nhĩ vu mao [晝爾于茅] sớm đi lấy cỏ tranh.##Chưng, dùng làm lời trợ ngữ. Như chí vu kỳ hạ [至于岐下] đến chưng dưới núi Kỳ.##So. Như vu Thang hữu quang [于湯有光] so với vua Thang có ý sáng sủa hơn.##Nhởn nhơ, lờ mờ. Như kỳ giác dã vu vu [其覺也于于] thửa biết vậy lờ mờ.##Một âm là hu. Tiếng tán thán. Như hu ta lân hề [于嗟麟兮] chao ơi con lân kia !##Giản thể của chữ [於]."}, {"id": "徐余于二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "徐余于亅", "word": "亅", "hanViet": "QUYẾT", "detail": "Tức là cái nét xổ có móc."}, {"id": "徐余ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "徐彳", "word": "彳", "hanViet": "XÍCH", "detail": "Bước ngắn. Bước chân trái gọi là xích [彳], bước chân phải gọi là xúc [亍], hợp [彳] với [亍] lại thành ra chữ hành [行]. $ Có khi đọc là sách."}], "links": [{"source": "徐", "target": "徐余"}, {"source": "徐余", "target": "徐余𠆢"}, {"source": "徐余", "target": "徐余于"}, {"source": "徐余于", "target": "徐余于二"}, {"source": "徐余于", "target": "徐余于亅"}, {"source": "徐余", "target": "徐余ハ"}, {"source": "徐", "target": "徐彳"}]}'::jsonb WHERE character = '徐' AND char_type = 'KANJI';
