UPDATE writing_characters SET comp_details_json = '[{"w": "馬", "h": "MÃ", "d": "con ngựa\nVD: 馬脚 (chân ngựa), 騎馬 (cưỡi ngựa)"}, {"w": "夋", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "駿馬", "word": "馬", "hanViet": "MÃ", "detail": "con ngựa\nVD: 馬脚 (chân ngựa), 騎馬 (cưỡi ngựa)"}, {"id": "駿馬隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "駿馬灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}, {"id": "駿夋", "word": "夋", "hanViet": "", "detail": ""}, {"id": "駿夋允", "word": "允", "hanViet": "DUẪN, DOÃN", "detail": "Thành thực.##Đáng. Như bình duẫn [平允] xử đoán phải chăng."}, {"id": "駿夋允厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "駿夋允儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}, {"id": "駿夋夂", "word": "夂", "hanViet": "TRI, TRUY", "detail": "Theo sau mà đến. Ngày xưa dùng như chữ chung [終]. $ Chữ này [夂] viết không có nét ló ra phía trên góc bên trái, khác với chữ tuy [夊] có nét ló ra phía trên góc bên trái."}], "links": [{"source": "駿", "target": "駿馬"}, {"source": "駿馬", "target": "駿馬隹"}, {"source": "駿馬", "target": "駿馬灬"}, {"source": "駿", "target": "駿夋"}, {"source": "駿夋", "target": "駿夋允"}, {"source": "駿夋允", "target": "駿夋允厶"}, {"source": "駿夋允", "target": "駿夋允儿"}, {"source": "駿夋", "target": "駿夋夂"}]}'::jsonb WHERE character = '駿' AND char_type = 'KANJI';
