UPDATE writing_characters SET comp_details_json = '[{"w": "禺", "h": "NGU", "d": "Tên núi, tên đất.##Khu, mỗi khu mười dặm là một ngu."}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "愚禺", "word": "禺", "hanViet": "NGU", "detail": "Tên núi, tên đất.##Khu, mỗi khu mười dặm là một ngu."}, {"id": "愚禺禸", "word": "禸", "hanViet": "NHỰU", "detail": "Vết ngón chân giống thú dẫm xuống đất."}, {"id": "愚禺禸冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "愚禺禸厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "愚禺田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "愚心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}], "links": [{"source": "愚", "target": "愚禺"}, {"source": "愚禺", "target": "愚禺禸"}, {"source": "愚禺禸", "target": "愚禺禸冂"}, {"source": "愚禺禸", "target": "愚禺禸厶"}, {"source": "愚禺", "target": "愚禺田"}, {"source": "愚", "target": "愚心"}]}'::jsonb WHERE character = '愚' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "广", "h": "NGHIỄM", "d": "Mái nhà. Cũng đọc là yểm.##Giản thể của chữ [廣]."}, {"w": "廿", "h": "NHẬP", "d": "Hai mươi. Như nhập bát tinh tú [廿八星宿] hai mươi tám sao, tức \"Nhị thập bát tú\" [二十八宿]. $ Ta quen đọc là chữ chấp."}, {"w": "灬", "h": "HỎA", "d": "Một hình thức của bộ hỏa [火]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "庶广", "word": "广", "hanViet": "NGHIỄM, YỂM, QUẢNG, QUÁNG", "detail": "Mái nhà. Cũng đọc là yểm.##Giản thể của chữ [廣]."}, {"id": "庶廿", "word": "廿", "hanViet": "NHẬP, CHẤP", "detail": "Hai mươi. Như nhập bát tinh tú [廿八星宿] hai mươi tám sao, tức \"Nhị thập bát tú\" [二十八宿]. $ Ta quen đọc là chữ chấp."}, {"id": "庶廿十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "庶廿十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "庶廿十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "庶灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}], "links": [{"source": "庶", "target": "庶广"}, {"source": "庶", "target": "庶廿"}, {"source": "庶廿", "target": "庶廿十"}, {"source": "庶廿十", "target": "庶廿十一"}, {"source": "庶廿十", "target": "庶廿十丨"}, {"source": "庶", "target": "庶灬"}]}'::jsonb WHERE character = '庶' AND char_type = 'KANJI';
