UPDATE writing_characters SET comp_details_json = '[{"w": "攸", "h": "DU", "d": "Vụt, thoáng, tả cái dáng nhanh chóng. Như du nhiên nhi thệ [攸然而逝] vụt vậy mà đi.##Chốn, nơi. Như tướng du [相攸] kén nơi đáng lấy làm chồng.##Thửa, dùng làm tiếng trợ từ. Như danh tiết du quan [名節攸關] danh tiết thửa quan hệ.##Du du [攸攸] dằng dặc.##Tên người. Như Nguyễn Du [阮攸] (Việt Nam, 1765-1820)."}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "悠攸", "word": "攸", "hanViet": "DU", "detail": "Vụt, thoáng, tả cái dáng nhanh chóng. Như du nhiên nhi thệ [攸然而逝] vụt vậy mà đi.##Chốn, nơi. Như tướng du [相攸] kén nơi đáng lấy làm chồng.##Thửa, dùng làm tiếng trợ từ. Như danh tiết du quan [名節攸關] danh tiết thửa quan hệ.##Du du [攸攸] dằng dặc.##Tên người. Như Nguyễn Du [阮攸] (Việt Nam, 1765-1820)."}, {"id": "悠攸亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "悠攸丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "悠攸攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}, {"id": "悠心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}], "links": [{"source": "悠", "target": "悠攸"}, {"source": "悠攸", "target": "悠攸亻"}, {"source": "悠攸", "target": "悠攸丨"}, {"source": "悠攸", "target": "悠攸攵"}, {"source": "悠", "target": "悠心"}]}'::jsonb WHERE character = '悠' AND char_type = 'KANJI';
