UPDATE writing_characters SET comp_details_json = '[{"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"w": "旁", "h": "BÀNG", "d": "Bên cạnh. Như nhi lập tại bàng [兒立在旁] đứa bé đứng ở bên.##Một âm là bạng. Nương tựa.##Lại một âm là banh. Banh banh [旁旁] rong ruổi, sa sả.##Một âm nữa là phang. Phang bạc [旁礡] mông mênh, bát ngát."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "傍亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "傍旁", "word": "旁", "hanViet": "BÀNG, BẠNG, BANH, PHANG", "detail": "Bên cạnh. Như nhi lập tại bàng [兒立在旁] đứa bé đứng ở bên.##Một âm là bạng. Nương tựa.##Lại một âm là banh. Banh banh [旁旁] rong ruổi, sa sả.##Một âm nữa là phang. Phang bạc [旁礡] mông mênh, bát ngát."}, {"id": "傍旁方", "word": "方", "hanViet": "PHƯƠNG", "detail": "1. hướng\nVD: 方角 (hướng đi), 方向 (phương hướng)\n2. một bộ phận; lĩnh vực; khía cạnh\nVD: 方面 (lĩnh vực), 双方 (đôi bên)\n3. vùng đất; địa phương\nVD: 方言 (tiếng địa phương), 地方 (địa phương)\n4. cách thức; phương pháp; kỹ năng\nVD: 方式 (cách thức), 方法 (phương pháp), 方術 (thuật pháp)\n5.  hình vuông; vuông vức \nVD: 方形 (hình vuông), 方丈 (vuông một trượng)\n6. đúng đắn; ngay ngắn\nVD: 方正 (ngay thẳng)\n7. đang; đúng lúc\nVD: 方今 (hiện nay)\n8. vị; người; phương hướng; thời gian\n(a) kính ngữ chỉ người khác\n(b) người phụ trách\nVD: 裏方 (người làm hậu trường), 煮方 (người nấu)\n(c) chỗ ở; nơi nương tựa\n(d) thời điểm; lúc\nVD: 夕方 (chiều tối)"}, {"id": "傍旁立", "word": "立", "hanViet": "LẬP", "detail": "1. đứng; đứng thẳng\nVD: 立脚 (lập trường), 立像 (tượng đứng), 起立 (đứng dậy)\n2. khởi đầu một mùa\nVD: 立春 (bắt đầu mùa xuân), 立秋 (bắt đầu mùa thu)\n3. lập nên; xác định; làm cho hình thành\nVD: 立案 (lập kế hoạch), 確立 (xác lập), 成立 (thành lập)\n4. lít (đơn vị đo dung tích); viết tắt của từ 立突"}, {"id": "傍旁冖", "word": "冖", "hanViet": "MỊCH", "detail": "Trùm, lấy khăn trùm lên trên đồ."}], "links": [{"source": "傍", "target": "傍亻"}, {"source": "傍", "target": "傍旁"}, {"source"