UPDATE writing_characters SET comp_details_json = '[{"w": "男", "h": "NAM", "d": "1. con trai\nVD: 嫡男 (đích nam), 長男 (trưởng nam)\n2. đàn ông; nam giới \nVD: 男子 (nam giới), 男性 (đàn ông)\n3. tước vị thứ năm trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam)\nVD: 男爵 (nam tước)"}, {"w": "虍", "h": "HÔ", "d": "Vằn con hổ, vằn con vện."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "虜男", "word": "男", "hanViet": "NAM", "detail": "1. con trai\nVD: 嫡男 (đích nam), 長男 (trưởng nam)\n2. đàn ông; nam giới \nVD: 男子 (nam giới), 男性 (đàn ông)\n3. tước vị thứ năm trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam)\nVD: 男爵 (nam tước)"}, {"id": "虜男力", "word": "力", "hanViet": "LỰC", "detail": "1. sức lực; sức mạnh\nVD: 力士 (võ sĩ sumo), 体力 (thể lực)\n2. hoạt động; chức năng; hiệu quả\nVD: 効力 (hiệu lực), 視力 (thị lực)\n3. gồng mình; dồn sức\n4. uy thế; thế lực\nVD: 威力 (sức mạnh), 勢力 (thế lực)\n5. cố gắng; nỗ lực; chăm chỉ\nVD: 力作 (tác phẩm tâm huyết), 努力 (nỗ lực)"}, {"id": "虜男田", "word": "田", "hanViet": "ĐIỀN", "detail": "1. nông thôn; quê\nVD: 田舎 (nông thôn), 田紳 (người có địa vị ở quê), 田夫 (nông dân)\n2. săn bắn \nVD: 田猟 (săn bắn)\n3. ruộng; đất canh tác\nVD: 田園 (đồng quê), 田畑 (ruộng đồng), 水田 (ruộng lúa nước)\n4. vùng sản xuất một loại vật phẩm cụ thể\nVD: 塩田 (ruộng muối), 炭田 (mỏ than), 油田 (mỏ dầu)"}, {"id": "虜虍", "word": "虍", "hanViet": "HÔ", "detail": "Vằn con hổ, vằn con vện."}, {"id": "虜虍卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "虜虍厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "虜虍七", "word": "七", "hanViet": "THẤT", "detail": "1. số bảy