UPDATE writing_characters SET comp_details_json = '[{"w": "感", "h": "CẢM", "d": "1. cảm nhận##(a) tâm trí lay động; chạm đến trái tim; tiếp nhận bằng trái tim##VD: 感化 (cảm hóa), 感慨 (cảm khái), 予感 (linh cảm)##(b) tri giác; cảm giác##VD: 感覚 (cảm giác), 感触 (cảm giác khi tiếp xúc), 快感 (khoái cảm)##2. bị nhiễm; mắc phải; viết tắt của 感冒 (cảm cúm)##VD: 感染 (nhiễm), 流感 (cúm)"}, {"w": "忄", "h": "TÂM", "d": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "憾感", "word": "感", "hanViet": "CẢM", "detail": "1. cảm nhận##(a) tâm trí lay động; chạm đến trái tim; tiếp nhận bằng trái tim##VD: 感化 (cảm hóa), 感慨 (cảm khái), 予感 (linh cảm)##(b) tri giác; cảm giác##VD: 感覚 (cảm giác), 感触 (cảm giác khi tiếp xúc), 快感 (khoái cảm)##2. bị nhiễm; mắc phải; viết tắt của 感冒 (cảm cúm)##VD: 感染 (nhiễm), 流感 (cúm)"}, {"id": "憾感咸", "word": "咸", "hanViet": "HÀM, GIẢM", "detail": "Khắp cả.##Đều, hết thẩy.##Một âm là giảm, cùng nghĩa với chữ giảm [減].##Giản thể của chữ [鹹]."}, {"id": "憾感咸戊", "word": "戊", "hanViet": "MẬU", "detail": "Can Mậu [戊], can thứ năm trong mười can."}, {"id": "憾感咸戊戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "憾感咸一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}