UPDATE writing_characters SET comp_details_json = '[{"w": "逢", "h": "PHÙNG", "d": "Gặp. Hai bên gặp nhau gọi là phùng.##Đón rước. Như Mạnh Tử [孟子] nói phùng quân chi ác kì tội đại [逢君之惡其最大] đón rước ý vua làm cho thêm hư, tội rất lớn.##To lớn. Như phùng dịch chi y [逢掖之衣] cái áo rộng kích.##Một âm là bồng. Bồng bồng [逢逢] tiếng trống thùng thùng."}, {"w": "糸", "h": "MỊCH", "d": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "縫逢", "word": "逢", "hanViet": "PHÙNG, BỒNG", "detail": "Gặp. Hai bên gặp nhau gọi là phùng.##Đón rước. Như Mạnh Tử [孟子] nói phùng quân chi ác kì tội đại [逢君之惡其最大] đón rước ý vua làm cho thêm hư, tội rất lớn.##To lớn. Như phùng dịch chi y [逢掖之衣] cái áo rộng kích.##Một âm là bồng. Bồng bồng [逢逢] tiếng trống thùng thùng."}, {"id": "縫逢夆", "word": "夆", "hanViet": "PHÙNG", "detail": "Trái nghịch.##Dắt kéo đi."}, {"id": "縫逢夆夂", "word": "夂", "hanViet": "TRI, TRUY", "detail": "Theo sau mà đến. Ngày xưa dùng như chữ chung [終]. $ Chữ này [夂] viết không có nét ló ra phía trên góc bên trái, khác với chữ tuy [夊] có nét ló ra phía trên góc bên trái."}, {"id": "縫逢夆丰", "word": "丰", "hanViet": "PHONG", "detail": "Giản thể của chữ [豐]."}, {"id": "縫逢辶", "word": "辶", "hanViet": "SƯỚC", "detail": "Bộ Quai xước (bộ Sước 辵: bước đi, di chuyển)"}, {"id": "縫糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}], "links": [{"source": "縫", "target": "縫逢"}, {"source": "縫逢", "target": "縫逢夆"}, {"source": "縫逢夆", "target": "縫逢夆夂"}, {"source": "縫逢夆", "target": "縫逢夆丰"}, {"source": "縫逢", "target": "縫逢辶"}, {"source": "縫", "ta