UPDATE writing_characters SET comp_details_json = '[{"w": "貝", "h": "BỐI", "d": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"w": "戎", "h": "NHUNG", "d": "Đồ binh, cung, nỏ, giáo, mác, kích gọi là năm đồ binh, ngũ nhung [五戎], vì thế nên các đồ quân bị đều gọi là nhung cả.##Binh lính. Quan tổng binh gọi là tổng nhung [總戎].##To lớn. Như nhung thúc [戎菽] giống đậu to.##Rợ, các giống rợ ở phương tây đều gọi là nhung.##Mày.##Cùng.##Xe binh."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "賊貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "賊貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "賊貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}, {"id": "賊戎", "word": "戎", "hanViet": "NHUNG", "detail": "Đồ binh, cung, nỏ, giáo, mác, kích gọi là năm đồ binh, ngũ nhung [五戎], vì thế nên các đồ quân bị đều gọi là nhung cả.##Binh lính. Quan tổng binh gọi là tổng nhung [總戎].##To lớn. Như nhung thúc [戎菽] giống đậu to.##Rợ, các giống rợ ở phương tây đều gọi là nhung.##Mày.##Cùng.##Xe binh."}, {"id": "賊戎𠂇", "word": "𠂇", "hanViet": "", "detail": ""}, {"id": "賊戎戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}], "links": [{"source": "賊", "target": "賊貝"}, {"source": "賊貝", "target": "賊貝ハ"}, {"source": "賊貝", "target": "賊貝目"}, {"source": "賊", "target": "賊戎"}, {"source": "賊戎", "target": "賊戎𠂇"}, {"source": "賊戎", "target": "賊戎戈"}]}'::jsonb WHERE character = '賊' AND char_type = 'KANJI';
