UPDATE writing_characters SET comp_details_json = '[{"w": "戈", "h": "QUA", "d": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"w": "虚", "h": "HƯ", "d": "1. trống rỗng; không có nội dung; hư không \nVD: 虚無 (trống rỗng), 虚空 (khoảng không)\n2. bề ngoài; không thực chất; giả dối \nVD: 虚栄 (hư vinh), 虚礼 (lễ nghi sáo rỗng)\n3. yếu ớt; suy nhược\nVD: 虚弱 (yếu ớt), 虚脱 (kiệt sức)\n4. không có tà tâm; thành thật; khiêm tốn\nVD: 謙虚 (khiêm tốn)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "戯戈", "word": "戈", "hanViet": "QUA", "detail": "Cái mác, một thứ đồ binh ngày xưa.##Đánh nhau, nhật tầm can qua [日尋干戈] ngày gây sự đánh nhau. Người trong đảng quay lại phản đảng gọi là đảo qua tương hướng [倒戈相向], cùng trong một đảng mà đánh lẫn nhau gọi là đồng thất thao qua [同室操戈].##Qua thập cáp [戈什哈] tiếng Mãn Thanh, nghĩa là kẻ hầu gần, kẻ hộ vệ."}, {"id": "戯虚", "word": "虚", "hanViet": "HƯ, KHƯ", "detail": "1. trống rỗng; không có nội dung; hư không \nVD: 虚無 (trống rỗng), 虚空 (khoảng không)\n2. bề ngoài; không thực chất; giả dối \nVD: 虚栄 (hư vinh), 虚礼 (lễ nghi sáo rỗng)\n3. yếu ớt; suy nhược\nVD: 虚弱 (yếu ớt), 虚脱 (kiệt sức)\n4. không có tà tâm; thành thật; khiêm tốn\nVD: 謙虚 (khiêm tốn)"}, {"id": "戯虚虍", "word": "虍", "hanViet": "HÔ", "detail": "Vằn con hổ, vằn con vện."}, {"id": "戯虚虍卜", "word": "卜", "hanViet": "BẶC, BỐC", "detail": "Bói rùa. Đốt mai rùa để xem xấu tốt gọi là bốc. Như mai bốc công thần, duy cát chi tòng [枚卜公臣惟吉之從] bói xem các bầy tôi ai là tốt hơn. Đời sau dùng quan tể tướng gọi là mai bốc [枚] là theo nghĩa ấy.##Bói thử. Như xem chim sâu kêu mà đoán xem mưa nắng gọi là bốc. Bây giờ gọi sự đã dự kì ([預期]) là định bốc [定卜], gọi sự chưa biết ([未知]) là vị bốc [未卜].##Giản thể của chữ [蔔]."}, {"id": "戯虚虍厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "戯虚虍七", "word": "七", "hanViet": "THẤT", "detail": "1. số bảy\nVD: 七賢 (bảy vị hiền triết), 七夕 (lễ Thất tịch), 七曜 (bảy ngày trong tuần)\n2. nhiều; số lượng lớn\nVD: 七珍万宝 (muôn vàn châu báu)"}, {"id": "戯虚业", "word": "业", "hanViet": "", "detail": ""}], "links": [{"source": "戯", "target": "戯戈"}, {"source": "戯", "target": "戯虚"}, {"source": "戯虚", "target": "戯虚虍"}, {"source": "戯虚虍", "target": "戯虚虍卜"}, {"source": "戯虚虍", "target": "戯虚虍厂"}, {"source": "戯虚虍", "target": "戯虚虍七"}, {"source": "戯虚", "target": "戯虚业"}]}'::jsonb WHERE character = '戯' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "己", "h": "KỈ", "d": "1. bản thân; chính mình\nVD: 自己 (bản thân), 克己 (tự kiềm chế)\n2. kỷ (can thứ sáu trong mười thiên can)\nVD: 己丑 (năm Kỷ Sửu)"}, {"w": "心", "h": "TÂM", "d": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "忌己", "word": "己", "hanViet": "KỈ", "detail": "1. bản thân; chính mình\nVD: 自己 (bản thân), 克己 (tự kiềm chế)\n2. kỷ (can thứ sáu trong mười thiên can)\nVD: 己丑 (năm Kỷ Sửu)"}, {"id": "忌心", "word": "心", "hanViet": "TÂM", "detail": "1. trái tim\nVD: 心音 (nhịp tim), 心筋 (cơ tim)\n2. tâm; tình cảm; tinh thần \nVD: 心情 (tâm tư tình cảm), 感心 (cảm phục)\n3. ở giữa; phần quan trọng; điểm mấu chốt\nVD: 心棒 (trục chính), 核心 (cốt lõi)"}], "links": [{"source": "忌", "target": "忌己"}, {"source": "忌", "target": "忌心"}]}'::jsonb WHERE character = '忌' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "蜀", "h": "THỤC", "d": "Lúc con ngài, con bướm con như con sâu nhỏ gọi là thục.##Đất Thục [蜀], nước Thục [蜀] (221-264); thuộc tỉnh Tứ Xuyên [四川] bây giờ.##Cô độc.##Đồ thờ."}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "濁蜀", "word": "蜀", "hanViet": "THỤC", "detail": "Lúc con ngài, con bướm con như con sâu nhỏ gọi là thục.##Đất Thục [蜀], nước Thục [蜀] (221-264); thuộc tỉnh Tứ Xuyên [四川] bây giờ.##Cô độc.##Đồ thờ."}, {"id": "濁蜀虫", "word": "虫", "hanViet": "TRÙNG", "detail": "1. sâu bọ; côn trùng\nVD: 益虫 (côn trùng có ích), 幼虫 (ấu trùng)\n2. các loài động vật nói chung"}, {"id": "濁蜀虫一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "濁蜀虫丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "濁蜀虫中", "word": "中", "hanViet": "TRUNG, TRÚNG", "detail": "1. chính giữa\nVD: 中央 (trung ương), 中心 (trung tâm), 中核 (cốt lõi)\n2. bên trong phạm vi; phía trong\nVD: 意中 (trong lòng), 車中 (trong xe), 忌中 (trong thời gian chịu tang)\n3. khoảng giữa; đoạn giữa trong 3 đoạn\nVD: 中等 (tầm trung), 中流 (tầng lớp trung lưu), 中盤 (giai đoạn giữa)\n4. ở giữa; khoảng cách giữa hai bên\nVD: 中間 (trung gian), 中継 (phát sóng), 中腹 (sườn núi)\n5. suốt; toàn bộ\nVD: 年中 (quanh năm), 世界中 (trên toàn thế giới)\n6. viết tắt của trung học hoặc Trung Quốc\nVD: 中卒 (tốt nghiệp trung học), 訪中 (thăm Trung Quốc)\n7. không thiên vị\nVD: 中立 (trung lập), 中道 (trung đạo), 折中 (dung )\n8. trúng; nhắm trúng\nVD: 中毒 (trúng độc), 命中 (trúng đích)\n9. mọi người; trong nhóm bạn bè\nVD: 講中 (nhóm tín đồ), 連中 (đám người)"}, {"id": "濁蜀虫中口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "濁蜀虫中丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "濁蜀勹", "word": "勹", "hanViet": "BAO", "detail": "Bọc."}, {"id": "濁蜀罒", "word": "罒", "hanViet": "VÕNG", "detail": "Một hình thức của bộ võng [网]."}, {"id": "濁氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "濁", "target": "濁蜀"}, {"source": "濁蜀", "target": "濁蜀虫"}, {"source": "濁蜀虫", "target": "濁蜀虫一"}, {"source": "濁蜀虫", "target": "濁蜀虫丶"}, {"source": "濁蜀虫", "target": "濁蜀虫中"}, {"source": "濁蜀虫中", "target": "濁蜀虫中口"}, {"source": "濁蜀虫中", "target": "濁蜀虫中丨"}, {"source": "濁蜀", "target": "濁蜀勹"}, {"source": "濁蜀", "target": "濁蜀罒"}, {"source": "濁", "target": "濁氵"}]}'::jsonb WHERE character = '濁' AND char_type = 'KANJI';
