UPDATE writing_characters SET comp_details_json = '[{"w": "賁", "h": "BÍ", "d": "Rực rỡ, sáng sủa. Như trong thơ từ thường dùng chữ bí lâm [賁臨] nghĩa là ngài hạ cố tới nhà tôi thì nhà tôi được rạng rỡ thêm. Tô Mạn Thù [蘇曼殊] : Thỉnh đại sư bí lâm thư trai tiện phạn [請大師賁臨書齋便飯] (Đoạn hồng linh nhạn kí [斷鴻零雁記]) Kính mời Đại sư rời gót sang thư trai dùng cơm.##Một âm là phần. To lớn. Như dụng hoành tư phần [用宏茲賁] dùng càng rộng lớn.##Lại một âm là bôn. Dũng sĩ. Như hổ bôn [虎賁] đạo quân hùng tráng của vua."}, {"w": "忄", "h": "TÂM", "d": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "憤賁", "word": "賁", "hanViet": "BÍ, PHẦN, BÔN", "detail": "Rực rỡ, sáng sủa. Như trong thơ từ thường dùng chữ bí lâm [賁臨] nghĩa là ngài hạ cố tới nhà tôi thì nhà tôi được rạng rỡ thêm. Tô Mạn Thù [蘇曼殊] : Thỉnh đại sư bí lâm thư trai tiện phạn [請大師賁臨書齋便飯] (Đoạn hồng linh nhạn kí [斷鴻零雁記]) Kính mời Đại sư rời gót sang thư trai dùng cơm.##Một âm là phần. To lớn. Như dụng hoành tư phần [用宏茲賁] dùng càng rộng lớn.##Lại một âm là bôn. Dũng sĩ. Như hổ bôn [虎賁] đạo quân hùng tráng của vua."}, {"id": "憤賁十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "憤賁十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "憤賁十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "憤賁艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "憤賁貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "憤賁貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "憤賁貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}, {"id": "憤忄", "word": "忄", "hanViet": "TÂM", "detail": "Bộ Tâm đứng (biến thể bộ Tâm 心: tim, tấm lòng, cảm xúc)"}], "links": [{"source": "憤", "target": "憤賁"}, {"source": "憤賁", "target": "憤賁十"}, {"source": "憤賁十", "target": "憤賁十一"}, {"source": "憤賁十", "target": "憤賁十丨"}, {"source": "憤賁", "target": "憤賁艹"}, {"source": "憤賁", "target": "憤賁貝"}, {"source": "憤賁貝", "target": "憤賁貝ハ"}, {"source": "憤賁貝", "target": "憤賁貝目"}, {"source": "憤", "target": "憤忄"}]}'::jsonb WHERE character = '憤' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "勺", "h": "CHƯỚC", "d": "Múc lấy. Thường dùng chữ chước [酌].##Cái chước, một phần trăm của một thưng 升 gọi là chước 勺.  Mười chước là một cáp合.##Cái môi dùng để múc canh."}, {"w": "酉", "h": "DẬU", "d": "Chi Dậu, chi thứ mười trong mười hai chi.##Giờ Dậu, từ 5 đến 7 giờ chiều.##Gà."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "酌勺", "word": "勺", "hanViet": "CHƯỚC, THƯỢC", "detail": "Múc lấy. Thường dùng chữ chước [酌].##Cái chước, một phần trăm của một thưng 升 gọi là chước 勺.  Mười chước là một cáp合.##Cái môi dùng để múc canh."}, {"id": "酌勺勹", "word": "勹", "hanViet": "BAO", "detail": "Bọc."}, {"id": "酌勺丶", "word": "丶", "hanViet": "CHỦ", "detail": "Phàm cái gì cần có phân biệt, sự gì cần biết nên chăng, lòng đã có định, thì đánh dấu chữ chủ để nhớ lấy."}, {"id": "酌酉", "word": "酉", "hanViet": "DẬU", "detail": "Chi Dậu, chi thứ mười trong mười hai chi.##Giờ Dậu, từ 5 đến 7 giờ chiều.##Gà."}, {"id": "酌酉西", "word": "西", "hanViet": "TÂY, TÊ", "detail": "1. phía tây \nVD: 西部 (miền tây), 西方 (phương tây)\n2. chỉ phương Tây\nVD: 西暦 (dương lịch), 泰西 (phương Tây)"}, {"id": "酌酉一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}], "links": [{"source": "酌", "target": "酌勺"}, {"source": "酌勺", "target": "酌勺勹"}, {"source": "酌勺", "target": "酌勺丶"}, {"source": "酌", "target": "酌酉"}, {"source": "酌酉", "target": "酌酉西"}, {"source": "酌酉", "target": "酌酉一"}]}'::jsonb WHERE character = '酌' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"w": "尭", "h": "NGHIÊU", "d": "Cao; vua Nghiêu"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "暁日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "暁尭", "word": "尭", "hanViet": "NGHIÊU", "detail": "Cao; vua Nghiêu"}, {"id": "暁尭十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "暁尭十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "暁尭十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "暁尭艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "暁尭兀", "word": "兀", "hanViet": "NGỘT", "detail": "Cao mà bằng đầu. Bây giờ quen gọi là cao chót. Như đột ngột [突兀] chót vót.##Ngây ngất. Như hằng ngột ngột dĩ cùng niên [恆兀兀以窮年] thường lo đau đáu suốt năm.##Lại là lời trợ ngữ, trong các bài từ nhà Nguyên họ hay dùng.##Ngột giả [兀者] kẻ bị chặt gẫy một chân."}, {"id": "暁尭兀一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "暁尭兀儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}], "links": [{"source": "暁", "target": "暁日"}, {"source": "暁", "target": "暁尭"}, {"source": "暁尭", "target": "暁尭十"}, {"source": "暁尭十", "target": "暁尭十一"}, {"source": "暁尭十", "target": "暁尭十丨"}, {"source": "暁尭", "target": "暁尭艹"}, {"source": "暁尭", "target": "暁尭兀"}, {"source": "暁尭兀", "target": "暁尭兀一"}, {"source": "暁尭兀", "target": "暁尭兀儿"}]}'::jsonb WHERE character = '暁' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "亻", "h": "NHÂN", "d": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"w": "木", "h": "MỘC", "d": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"w": "舛", "h": "SUYỄN", "d": "Ngang trái. Vương Bột [王勃] : Ta hồ ! Thời vận bất tề, mệnh đồ đa suyễn [嗟乎！時運不齊, 命途多舛] (Đằng Vương các tự [滕王閣序]) Than ôi ! Thời vận chẳng bình thường, đường đời nhiều ngang trái.##Lẫn lộn."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "傑亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "傑木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm gỗ), 材木 (vật liệu gỗ)\n2. cây cối\nVD: 木石 (cây và đá), 樹木 (cây cối)\n3. thứ Năm\n4. mộc mạc; chất phác \nVD: 木訥 (chất phác)\n5. mộc (một trong ngũ hành)"}, {"id": "傑木大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "傑木大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3.