UPDATE writing_characters SET comp_details_json = '[{"w": "此", "h": "THỬ", "d": "Ấy, bên ấy, đối lại với chữ bỉ [彼].##Thế, lời nói chỉ định hẳn hoi. Như kỳ tự nhâm dĩ thiên hạ trọng như thử [其自任以天下之重如此] thửa gánh vác lấy công việc nặng nề trong thiên hạ như thế.##Ấy, bèn. Như hữu đức thử hữu nhân [有德此有人] (Đại học [大學]) có đức ấy (bèn) có người."}, {"w": "隹", "h": "CHUY", "d": "Một cái tên chung để gọi giống chim đuôi ngắn."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "雌此", "word": "此", "hanViet": "THỬ", "detail": "Ấy, bên ấy, đối lại với chữ bỉ [彼].##Thế, lời nói chỉ định hẳn hoi. Như kỳ tự nhâm dĩ thiên hạ trọng như thử [其自任以天下之重如此] thửa gánh vác lấy công việc nặng nề trong thiên hạ như thế.##Ấy, bèn. Như hữu đức thử hữu nhân [有德此有人] (Đại học [大學]) có đức ấy (bèn) có người."}, {"id": "雌此止", "word": "止", "hanViet": "CHỈ", "detail": "1. ngăn chặn; đình chỉ; cầm\nVD: 止血 (cầm máu), 禁止 (cấm)\n2. dừng; bãi bỏ\nVD: 中止 (hoãn lại), 廃止 (bãi bỏ)\n3. dừng lại; ở lại\nVD: 止宿 (trọ lại)\n4. dáng vẻ; cử chỉ\nVD: 挙止 (cử chỉ)"}, {"id": "雌此匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}, {"id": "雌隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}], "links": [{"source": "雌", "target": "雌此"}, {"source": "雌此", "target": "雌此止"}, {"source": "雌此", "target": "雌此匕"}, {"source": "雌", "target": "雌隹"}]}'::jsonb WHERE character = '雌' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "甚", "h": "THẬM", "d": "rất; cực kỳ; vượt mức\nVD: 甚大 (cực kỳ lớn), 深甚 (sâu sắc)"}, {"w": "土", "h": "THỔ", "d": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "堪甚", "word": "甚", "hanViet": "THẬM", "detail": "rất; cực kỳ; vượt mức\nVD: 甚大 (cực kỳ lớn), 深甚 (sâu sắc)"}, {"id": "堪甚甘", "word": "甘", "hanViet": "CAM", "detail": "1. ngọt; ngon\nVD: 甘美 (ngọt ngào), 甘露 (cam lộ)\n2. cam chịu; hài lòng; thỏa mãn\nVD: 甘受 (cam chịu), 甘心 (hài lòng)"}, {"id": "堪甚甘廿", "word": "廿", "hanViet": "NHẬP, CHẤP", "detail": "Hai mươi. Như nhập bát tinh tú [廿八星宿] hai mươi tám sao, tức \"Nhị thập bát tú\" [二十八宿]. $ Ta quen đọc là chữ chấp."}, {"id": "堪甚甘廿十", "word": "十", "hanViet": "THẬP", "detail": "1. số mười\nVD: 十戒 (mười điều răn), 十干 (thập can)\n2. số lượng nhiều; rất nhiều\nVD: 十目 (nhiều người nhìn)\n3. trạng thái đầy đủ; tất cả\nVD: 十分 (đầy đủ), 十全 (vẹn toàn)"}, {"id": "堪甚甘廿十一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "堪甚甘廿十丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "堪甚匹", "word": "匹", "hanViet": "THẤT", "detail": "1. <i>hiki</i> \n(a) từ dùng để đếm động vật\n(b) đơn vị đo chiều dài vải (bằng 2 tấm); đơn vị tiền tệ ngày xưa (bằng 10 văn)\n2. ngang hàng; thành đôi; bè bạn\nVD: 匹敵 (ngang sức), 匹偶 (cặp đôi)\n3. thấp hèn; địa vị thấp kém\nVD: 匹夫 (kẻ thường dân)"}, {"id": "堪甚匹儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}, {"id": "堪甚匹匚", "word": "匚", "hanViet": "PHƯƠNG", "detail": "Cái đồ để đựng đồ."}, {"id": "堪土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}], "links": [{"source": "堪", "target": "堪甚"}, {"source": "堪甚", "target": "堪甚甘"}, {"source": "堪甚甘", "target": "堪甚甘廿"}, {"source": "堪甚甘廿", "target": "堪甚甘廿十"}, {"source": "堪甚甘廿十", "target": "堪甚甘廿十一"}, {"source": "堪甚甘廿十", "target": "堪甚甘廿十丨"}, {"source": "堪甚", "target": "堪甚匹"}, {"source": "堪甚匹", "target": "堪甚匹儿"}, {"source": "堪甚匹", "target": "堪甚匹匚"}, {"source": "堪", "target": "堪土"}]}'::jsonb WHERE character = '堪' AND char_type = 'KANJI';
