UPDATE writing_characters SET comp_details_json = '[{"w": "土", "h": "THỔ", "d": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"w": "亢", "h": "KHÁNG", "d": "Cao. Như bất kháng bất ti [不亢不卑] không kiêu ngạo không siểm nịnh.##Quá. Như kháng dương [亢陽] chân dương thái quá, kháng hạn [亢旱] nắng quá.##Che chở. Như kháng tông chi tử [亢宗之子] đứa con có thể làm phên che chở cho họ được.##Một âm là cang. Cổ. Như ách kỳ cang [搤其亢] bóp thửa cổ.##Sao Cang, một vì sao trong Nhị thập bát tú, cũng đọc là chữ cương."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "坑土", "word": "土", "hanViet": "THỔ, ĐỘ, ĐỖ", "detail": "1. quốc gia; lãnh thổ; nơi con người cư trú\nVD: 王土 (đất vua), 国土 (lãnh thổ quốc gia), 領土 (lãnh thổ)\n2. địa phương; thuộc về vùng đất đó\nVD: 土俗 (phong tục địa phương), 土着 (bản địa), 土豪 (hào phú địa phương)\n3. đất; bùn; mặt đất; lục địa\nVD: 土壌 (thổ nhưỡng), 粘土 (đất sét), 土地 (đất đai)\n4. thứ Bảy\n5. thổ (một trong ngũ hành)\n6. viết tắt của tỉnh cổ Tosa\nVD: 土州 (tỉnh Tosa)"}, {"id": "坑亢", "word": "亢", "hanViet": "KHÁNG, CANG, CƯƠNG", "detail": "Cao. Như bất kháng bất ti [不亢不卑] không kiêu ngạo không siểm nịnh.##Quá. Như kháng dương [亢陽] chân dương thái quá, kháng hạn [亢旱] nắng quá.##Che chở. Như kháng tông chi tử [亢宗之子] đứa con có thể làm phên che chở cho họ được.##Một âm là cang. Cổ. Như ách kỳ cang [搤其亢] bóp thửa cổ.##Sao Cang, một vì sao trong Nhị thập bát tú, cũng đọc là chữ cương."}, {"id": "坑亢几", "word": "几", "hanViet": "KỈ", "detail": "Cái ghế dựa.##Cái kỉ tre.##Giản thể của chữ [幾]."}, {"id": "坑亢亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}], "links": [{"source": "坑", "target": "坑土"}, {"source": "坑", "targ