UPDATE writing_characters SET comp_details_json = '[{"w": "亥", "h": "HỢI", "d": "Chi Hợi, một chi cuối cùng trong mười hai chi. Từ chín giờ đến mười một đêm gọi là giờ Hợi."}, {"w": "力", "h": "LỰC", "d": "1. sức lực; sức mạnh\nVD: 力士 (võ sĩ sumo), 体力 (thể lực)\n2. hoạt động; chức năng; hiệu quả\nVD: 効力 (hiệu lực), 視力 (thị lực)\n3. gồng mình; dồn sức\n4. uy thế; thế lực\nVD: 威力 (sức mạnh), 勢力 (thế lực)\n5. cố gắng; nỗ lực; chăm chỉ\nVD: 力作 (tác phẩm tâm huyết), 努力 (nỗ lực)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "劾亥", "word": "亥", "hanViet": "HỢI", "detail": "Chi Hợi, một chi cuối cùng trong mười hai chi. Từ chín giờ đến mười một đêm gọi là giờ Hợi."}, {"id": "劾亥幺", "word": "幺", "hanViet": "YÊU", "detail": "Nhỏ.##Tục gọi số một là yêu, vì số một là số đầu (nhỏ); đánh tổ tôm, tài bàn, chắn, v.v. gọi nhất là yêu là vì đó.##Dị dạng của chữ [么].##Giản thể của chữ [么]."}, {"id": "劾亥幺糸", "word": "糸", "hanViet": "MỊCH", "detail": "1. đơn vị đo lường; một phần mười nghìn\n2. sợi chỉ; vật mảnh như sợi chỉ\nVD: 金糸 (chỉ vàng), 菌糸 (sợi nấm)\n3. nhạc cụ có dây; đàn dây \nVD: 糸竹 (nhạc cụ dây và sáo), 糸管 (nhạc cụ dây và nhạc cụ hơi)\n4. cực kỳ ít\nVD: 糸毫 (một chút xíu)"}, {"id": "劾亥亠", "word": "亠", "hanViet": "ĐẦU", "detail": "Không có ý nghĩa gì."}, {"id": "劾力", "word": "力", "hanViet": "LỰC", "detail": "1. sức lực; sức mạnh\nVD: 力士 (võ sĩ sumo), 体力 (thể lực)\n2. hoạt động; chức năng; hiệu quả\nVD: 効力 (hiệu lực), 視力 (thị lực)\n3. gồng mình; dồn sức\n4. uy thế; thế lực\nVD: 威力 (sức mạnh), 勢力 (thế lực)\n5. cố gắng; nỗ lực; chăm chỉ\nVD: 力作 (tác phẩm tâm huyết), 努力 (nỗ lực)"}], "links": [{"source": "劾", "target": "劾亥"}, {"source": "劾亥", "target": "劾亥幺"}, {"source": "劾亥幺", "target": "劾亥幺糸"}, {"source": "劾亥", "target": "劾亥亠"}, {"source": "劾", "target": "劾力"}]}'::jsonb WHERE character = '劾' AND char_type = 'KANJI';
