UPDATE writing_characters SET comp_details_json = '[{"w": "女", "h": "NỮ", "d": "1. phụ nữ; phái nữ \nVD: 女王 (nữ hoàng), 女性 (phụ nữ), 女流 (nữ giới)\n2. con gái; thiếu nữ\nVD: 少女 (thiếu nữ), 処女 (con gái chưa chồng), 息女 (con gái người khác)\n3. nhà ngươi; mày \n4. gả đi; cho đi lấy chồng"}, {"w": "胥", "h": "TƯ", "d": "Đều. Như tư khả [胥可] đều khá.##Đợi. Như thiểu tư [少胥] đợi một chút, tư mệnh [胥命] đợi mệnh lệnh, v.v.##Cùng coi, dò xét. Như vu tư tư nguyên [于胥斯原] (Thi Kinh [詩經]) cùng coi cánh đồng để định chỗ cho dân ở.##Thứ nhân làm quan gọi là tư. Đời sau gọi thơ lại là tư lại [胥吏] là bởi đó (tức ta gọi là nhà tơ).##Giúp.##Sơ, xa."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "婿女", "word": "女", "hanViet": "NỮ, NỨ, NHỮ", "detail": "1. phụ nữ; phái nữ \nVD: 女王 (nữ hoàng), 女性 (phụ nữ), 女流 (nữ giới)\n2. con gái; thiếu nữ\nVD: 少女 (thiếu nữ), 処女 (con gái chưa chồng), 息女 (con gái người khác)\n3. nhà ngươi; mày \n4. gả đi; cho đi lấy chồng"}, {"id": "婿胥", "word": "胥", "hanViet": "TƯ", "detail": "Đều. Như tư khả [胥可] đều khá.##Đợi. Như thiểu tư [少胥] đợi một chút, tư mệnh [胥命] đợi mệnh lệnh, v.v.##Cùng coi, dò xét. Như vu tư tư nguyên [于胥斯原] (Thi Kinh [詩經]) cùng coi cánh đồng để định chỗ cho dân ở.##Thứ nhân làm quan gọi là tư. Đời sau gọi thơ lại là tư lại [胥吏] là bởi đó (tức ta gọi là nhà tơ).##Giúp.##Sơ, xa."}, {"id": "婿胥月", "word": "月", "hanViet": "NGUYỆT", "detail": "1. thứ Hai\n2. mặt trăng \nVD: 月光 (ánh trăng), 満月 (trăng tròn)\n3. tháng\nVD: 歳月 (thời gian dài), 年月 (năm tháng) "}, {"id": "婿胥疋", "word": "疋", "hanViet": "SƠ, NHÃ, THẤT", "detail": "Đủ, chân.##Một âm là nhã. Chính, ngày xưa dùng như chữ nhã [雅].##Lại một âm là thất. Nếp, xếp, vải lụa gấp lại, mỗi nếp gọi là nhất thất [一疋]."}], "links": [{"source": "婿", "target": "婿女"}, {"source": "婿", "target": "婿胥"}, {"source": "婿胥", "target": "婿胥月"}, {"source": "婿胥", "target": "婿胥疋"}]}'::jsonb WHERE character = '婿' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "莫", "h": "MẠC", "d": "Tuyệt không, chẳng ai không. Như mạc bất chấn cụ [莫不震懼] chẳng ai là chẳng sợ run.##Chớ, lời cấm chỉ. Như quân mạc vũ [君莫舞] anh chớ có múa. Lý Bạch : Nhân sinh đắc ý tu tận hoan, Mạc sử kim tôn không đối nguyệt [人生得意須盡歡，莫使金樽空對月] Người ta ở đời khi đắc ý, hãy tận vui hưởng, Chớ để chén vàng trống không trước vầng trăng.##Quảng mạc [廣莫] bát ngát.##Cùng nghĩa với chữ mạc [羃].##Yên định.##Vót.##To lớn.##Cùng nghĩa với chữ mạc [瘼].##Một âm là mộ. Cũng như chữ mộ [暮].##Lại một âm là mạch. Kì diệp mạch mạch [其葉莫莫] lá nó rậm rạp.##Một âm nữa là bá. Lặng. Quân phụ bá bá [君婦莫莫] vợ anh tính yên lặng.##Họ Mạc."}, {"w": "⺗", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "慕莫", "word": "莫", "hanViet": "MẠC, MỘ, MẠCH, BÁ", "detail": "Tuyệt không, chẳng ai không. Như mạc bất chấn cụ [莫不震懼] chẳng ai là chẳng sợ run.##Chớ, lời cấm chỉ. Như quân mạc vũ [君莫舞] anh chớ có múa. Lý Bạch : Nhân sinh đắc ý tu tận hoan, Mạc sử kim tôn không đối nguyệt [人生得意須盡歡，莫使金樽空對月] Người ta ở đời khi đắc ý, hãy tận vui hưởng, Chớ để chén vàng trống không trước vầng trăng.##Quảng mạc [廣莫] bát ngát.##Cùng nghĩa với chữ mạc [羃].##Yên định.##Vót.##To lớn.##Cùng nghĩa với chữ mạc [瘼].##Một âm là mộ. Cũng như chữ mộ [暮].##Lại một âm là mạch. Kì diệp mạch mạch [其葉莫莫] lá nó rậm rạp.##Một âm nữa là bá. Lặng. Quân phụ bá bá [君婦莫莫] vợ anh tính yên lặng.##Họ Mạc."}, {"id": "慕莫大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "慕莫大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "慕莫大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "慕莫日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "慕莫艹", "word": "艹", "hanViet": "THẢO", "detail": "Bộ Thảo đầu (cỏ, thảo mộc, thực vật)"}, {"id": "慕⺗", "word": "⺗", "hanViet": "", "detail": ""}], "links": [{"source": "慕", "target": "慕莫"}, {"source": "慕莫", "target": "慕莫大"}, {"source": "慕莫大", "target": "慕莫大一"}, {"source": "慕莫大", "target": "慕莫大人"}, {"source": "慕莫", "target": "慕莫日"}, {"source": "慕莫", "target": "慕莫艹"}, {"source": "慕", "target": "慕⺗"}]}'::jsonb WHERE character = '慕' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "罒", "h": "VÕNG", "d": "Một hình thức của bộ võng [网]."}, {"w": "能", "h": "NĂNG", "d": "1. kịch Noh (kịch truyền thống Nhật Bản)\nVD: 能面 (mặt nạ kịch Noh)\n2. công năng; kỹ năng; hiệu quả\nVD: 能率 (năng suất), 機能 (tính năng), 効能 (công dụng)\n3. viết tắt của tỉnh Noto\nVD: 能州 (tỉnh Noto)\n4. có thể; giỏi; làm tốt\nVD: 能弁 (hùng biện), 能吏 (quan chức giỏi), 可能 (khả năng)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "罷罒", "word": "罒", "hanViet": "VÕNG", "detail": "Một hình thức của bộ võng [网]."}, {"id": "罷能", "word": "能", "hanViet": "NĂNG, NAI, NẠI", "detail": "1. kịch Noh (kịch truyền thống Nhật Bản)\nVD: 能面 (mặt nạ kịch Noh)\n2. công năng; kỹ năng; hiệu quả\nVD: 能率 (năng suất), 機能 (tính năng), 効能 (công dụng)\n3. viết tắt của tỉnh Noto\nVD: 能州 (tỉnh Noto)\n4. có thể; giỏi; làm tốt\nVD: 能弁 (hùng biện), 能吏 (quan chức giỏi), 可能 (khả năng)"}, {"id": "罷能匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}, {"id": "罷能䏍", "word": "䏍", "hanViet": "", "detail": ""}], "links": [{"source": "罷", "target": "罷罒"}, {"source": "罷", "target": "罷能"}, {"source": "罷能", "target": "罷能匕"}, {"source": "罷能", "target": "罷能䏍"}]}'::jsonb WHERE character = '罷' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "喬", "h": "KIỀU", "d": "Cao. Như kiều mộc [喬木] cây cao. Kinh Thi nói : Xuất tự u cốc, thiên vu kiều mộc [出自幽谷遷于喬木] Từ hang tối ra, thiên lên cây cao. Ý nói chim nó còn biết chọn chỗ cao, huống chi người. Nay dùng hai chữ kiều thiên [喬遷]để tỏ ý lên chốn cao thượng sáng láng.##Giả. Như kiều trang [喬妝] ăn mặc giả lốt.##Cái móc trên cái giáo.##Cùng nghĩa với chữ kiêu [驕]."}, {"w": "矢", "h": "THỈ", "d": "1. mũi tên\nVD: 弓矢 (cung tên), 嚆矢 (mũi tên phát lệnh, sự khởi đầu)\n2. thề; giữ vững lời hứa\nVD: 矢言 (lời thề)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "矯喬", "word": "喬", "hanViet": "KIỀU", "detail": "Cao. Như kiều mộc [喬木] cây cao. Kinh Thi nói : Xuất tự u cốc, thiên vu kiều mộc [出自幽谷遷于喬木] Từ hang tối ra, thiên lên cây cao. Ý nói chim nó còn biết chọn chỗ cao, huống chi người. Nay dùng hai chữ kiều thiên [喬遷]để tỏ ý lên chốn cao thượng sáng láng.##Giả. Như kiều trang [喬妝] ăn mặc giả lốt.##Cái móc trên cái giáo.##Cùng nghĩa với chữ kiêu [驕]."}, {"id": "矯喬冋", "word": "冋", "hanViet": "QUYNH", "detail": "desert, border prairie, the 1st form is radical 13"}, {"id": "矯喬冋冂", "word": "冂", "hanViet": "QUYNH", "detail": "Đất ở xa ngoài cõi nước, kinh truyện đều dùng chữ quynh [坰]."}, {"id": "矯喬冋口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "矯喬呑", "word": "呑", "hanViet": "THÔN", "detail": "Nuốt.##drink"}, {"id": "矯喬呑夭", "word": "夭", "hanViet": "YÊU, YỂU", "detail": "Yêu yêu [夭夭] nét mặt vui vẻ ôn tồn.##Rờn rờn, nhan sắc mầu mỡ đáng yêu.##Yêu kiểu [夭矯] uốn khúc. Nguyễn Du [阮攸] : Ngô văn thiên trì chi phần hữu long yêu kiểu [吾聞天池之濆有龍夭矯] (Mạnh Tử từ cổ liễu [孟子祠古柳]) Ta nghe bên bờ ao trời có con rồng uốn khúc.##Tai vạ.##Một âm là yểu. Chết non."}, {"id": "矯喬呑夭ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "矯喬呑夭大", "word": "大", "hanViet": "ĐẠI, THÁI", "detail": "1. số lượng hoặc khối lượng nhiều\nVD: 大群 (bầy đàn lớn), 大衆 (quần chúng)\n2. hình dáng hoặc quy mô lớn \nVD: 大河 (sông lớn), 長大 (dài và lớn)\n3. viết tắt của đại học\nVD: 短大 (trường cao đẳng)\n4. từ biểu thị vị trí cao nhất trong thứ tự \nVD: 大将 (đại tướng), 大僧正 (chức vị cao nhất của tăng sĩ)\n5. quan trọng; trọng yếu\nVD: 大義 (đại nghĩa), 大役 (trọng trách)\n6. xuất sắc; tuyệt vời\nVD: 偉大 (vĩ đại), 大器 (người có tài năng lớn)\n7. trở nên lớn; kiêu ngạo; tự cao\nVD: 誇大 (phóng đại), 尊大 (kiêu ngạo)\n8. kích thước của vật\nVD: 等身大 (kích thước bằng người thật)\n9. đại khái; khoảng chừng\nVD: 大意 (ý chính), 大要 (tóm lược)\n10. rất; vô cùng; hết sức\nVD: 大安 (ngày đại an), 大慶 (niềm vui lớn)\n11. từ dùng làm tôn xưng, kính xưng hoặc mỹ xưng\nVD: 大兄 (đại huynh), 大命 (thánh chỉ)"}, {"id": "矯喬呑夭大一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "矯喬呑夭大人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "矯喬呑口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở mi