UPDATE writing_characters SET comp_details_json = '[{"w": "士", "h": "SĨ", "d": "1. đàn ông; nam giới trưởng thành; người đàn ông hào hiệp\nVD: 志士 (người có chí hướng), 紳士 (quý ông)\n2. người có bằng cấp hoặc tư cách nhất định\nVD: 学士 (cử nhân), 助士 (trợ lý)\n3. samurai; quân nhân\nVD: 兵士 (binh sĩ), 武士 (võ sĩ, samurai)"}, {"w": "冖", "h": "MỊCH", "d": "Trùm, lấy khăn trùm lên trên đồ."}, {"w": "匕", "h": "CHỦY", "d": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "壱士", "word": "士", "hanViet": "SĨ", "detail": "1. đàn ông; nam giới trưởng thành; người đàn ông hào hiệp\nVD: 志士 (người có chí hướng), 紳士 (quý ông)\n2. người có bằng cấp hoặc tư cách nhất định\nVD: 学士 (cử nhân), 助士 (trợ lý)\n3. samurai; quân nhân\nVD: 兵士 (binh sĩ), 武士 (võ sĩ, samurai)"}, {"id": "壱冖", "word": "冖", "hanViet": "MỊCH", "detail": "Trùm, lấy khăn trùm lên trên đồ."}, {"id": "壱匕", "word": "匕", "hanViet": "CHỦY", "detail": "Cái thìa. Như nói cuộc đời yên lặng thì gọi là chủy xưởng bất kinh [匕鬯不驚] nghĩa là vẫn được vô sự mà ăn uống yên lành.##Chủy thủ [匕首] một thứ gươm, đầu như cái thìa, ngắn mà tiện dùng, cho nên gọi là chủy thủ."}], "links": [{"source": "壱", "target": "壱士"}, {"source": "壱", "target": "壱冖"}, {"source": "壱", "target": "壱匕"}]}'::jsonb WHERE character = '壱' AND char_type = 'KANJI';
