UPDATE writing_characters SET comp_details_json = '[{"w": "叚", "h": "GIẢ", "d": "Cũng như chữ [假]."}, {"w": "⻗", "h": "", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "霞叚", "word": "叚", "hanViet": "GIẢ", "detail": "Cũng như chữ [假]."}, {"id": "霞叚コ", "word": "コ", "hanViet": "", "detail": ""}, {"id": "霞叚尸", "word": "尸", "hanViet": "THI", "detail": "Thần Thi, ngày xưa cúng tế, dùng một đứa bé lên ngồi trên ngai để cho thần nương vào đấy gọi là thi, đời sau mới dùng tranh ảnh thay vào.##Thây, người chết chưa chôn gọi là thi. Kẻ sống mà không có tinh thần, tục mỉa là kẻ hành thi tẩu nhục [行尸走肉] thịt chạy thây đi.##Chủ. Như kinh Thi nói thùy kì thi chi, hữu Tề quý nữ [誰其尸之有齊季女] ai thửa chủ việc cơm canh, có con gái út nước Tề.##Bầy. Như Tả truyện chép Sở Vũ vương Kinh thi [楚武王荆尸] vua Vũ nước Sở dàn quân ở đất Kinh.##Ngồi không, không có ích gì cho cái ngôi chức của mình gọi là thi. Như thi vị [尸位] ngôi hão, thi quan [尸官] quan thừa, v.v.##Giản thể của chữ [屍]."}, {"id": "霞叚又", "word": "又", "hanViet": "HỰU", "detail": "lại; hơn nữa; lại một lần nữa"}, {"id": "霞⻗", "word": "⻗", "hanViet": "", "detail": ""}], "links": [{"source": "霞", "target": "霞叚"}, {"source": "霞叚", "target": "霞叚コ"}, {"source": "霞叚", "target": "霞叚尸"}, {"source": "霞叚", "target": "霞叚又"}, {"source": "霞", "target": "霞⻗"}]}'::jsonb WHERE character = '霞' AND char_type = 'KANJI';
