UPDATE writing_characters SET comp_details_json = '[{"w": "火", "h": "HỎA", "d": "1. lửa; ngọn lửa\nVD: 火気 (nguồn nhiệt), 火炎 (ngọn lửa), 発火 (bắt lửa)\n2. hỏa (một trong ngũ hành)\n3. thứ Ba\n4. ánh sáng; ngọn đèn\nVD: 漁火 (lửa chài), 灯火 (ánh đèn)\n5. cháy; đốt\nVD: 火災 (hỏa hoạn), 火事 (đám cháy)\n6. cảm xúc mãnh liệt, cháy bỏng\nVD: 情火 (ngọn lửa tình)\n7. vội vã; cấp bách\nVD: 火急 (khẩn cấp)"}, {"w": "粲", "h": "XÁN", "d": "Thứ gạo giã kỹ, gạo trắng tinh. Hình phép nhà Hán có thứ gọi là quỷ tân [鬼薪] và bạch xán [白粲]. Quỷ tân là phải đi kiếm củi để cấp cho nhà tôn miếu. Bạch xán là bắt ngồi chọn lấy hạt gạo trắng gạo lành, cũng như hình phạt khổ sai bây giờ.##Tươi, rực rỡ, đẹp.##Cười nhởn, phì cười. Như vị chi xán nhiên [爲之粲然] làm cho phì cười cả."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "燦火", "word": "火", "hanViet": "HỎA", "detail": "1. lửa; ngọn lửa\nVD: 火気 (nguồn nhiệt), 火炎 (ngọn lửa), 発火 (bắt lửa)\n2. hỏa (một trong ngũ hành)\n3. thứ Ba\n4. ánh sáng; ngọn đèn\nVD: 漁火 (lửa chài), 灯火 (ánh đèn)\n5. cháy; đốt\nVD: 火災 (hỏa hoạn), 火事 (đám cháy)\n6. cảm xúc mãnh liệt, cháy bỏng\nVD: 情火 (ngọn lửa tình)\n7. vội vã; cấp bách\nVD: 火急 (khẩn cấp)"}, {"id": "燦火丷", "word": "丷", "hanViet": "", "detail": ""}, {"id": "燦火人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "燦粲", "word": "粲", "hanViet": "XÁN", "detail": "Thứ gạo giã kỹ, gạo trắng tinh. Hình phép nhà Hán có thứ gọi là quỷ tân [鬼薪] và bạch xán [白粲]. Quỷ tân là phải đi kiếm củi để cấp cho nhà tôn miếu. Bạch xán là bắt ngồi chọn lấy hạt gạo trắng gạo lành, cũng như hình phạt khổ sai bây giờ.##Tươi, rực rỡ, đẹp.##Cười nhởn, phì cười. Như vị chi xán nhiên [爲之粲然] làm cho phì cười cả."}, {"id": "燦粲歺", "word": "歺", "hanViet": "", "detail": ""}