UPDATE writing_characters SET comp_details_json = '[{"w": "舛", "h": "SUYỄN", "d": "Ngang trái. Vương Bột [王勃] : Ta hồ ! Thời vận bất tề, mệnh đồ đa suyễn [嗟乎！時運不齊, 命途多舛] (Đằng Vương các tự [滕王閣序]) Than ôi ! Thời vận chẳng bình thường, đường đời nhiều ngang trái.##Lẫn lộn."}, {"w": "⺤", "h": "TRẢO", "d": "Bộ Trảo (biến thể bộ Trảo 爪: móng vuốt)"}, {"w": "冖", "h": "MỊCH", "d": "Trùm, lấy khăn trùm lên trên đồ."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "舜舛", "word": "舛", "hanViet": "SUYỄN", "detail": "Ngang trái. Vương Bột [王勃] : Ta hồ ! Thời vận bất tề, mệnh đồ đa suyễn [嗟乎！時運不齊, 命途多舛] (Đằng Vương các tự [滕王閣序]) Than ôi ! Thời vận chẳng bình thường, đường đời nhiều ngang trái.##Lẫn lộn."}, {"id": "舜舛夕", "word": "夕", "hanViet": "TỊCH", "detail": "buổi chiều; buổi tối; lúc mặt trời lặn \nVD: 夕映 (ánh chiều tà), 夕陽 (ánh hoàng hôn), 旦夕 (sớm tối)"}, {"id": "舜舛夕タ", "word": "タ", "hanViet": "TỊCH", "detail": "Bộ Tịch hoặc nét Katakana Ta"}, {"id": "舜舛ヰ", "word": "ヰ", "hanViet": "", "detail": ""}, {"id": "舜⺤", "word": "⺤", "hanViet": "TRẢO", "detail": "Bộ Trảo (biến thể bộ Trảo 爪: móng vuốt)"}, {"id": "舜冖", "word": "冖", "hanViet": "MỊCH", "detail": "Trùm, lấy khăn trùm lên trên đồ."}], "links": [{"source": "舜", "target": "舜舛"}, {"source": "舜舛", "target": "舜舛夕"}, {"source": "舜舛夕", "target": "舜舛夕タ"}, {"source": "舜舛", "target": "舜舛ヰ"}, {"source": "舜", "target": "舜⺤"}, {"source": "舜", "target": "舜冖"}]}'::jsonb WHERE character = '舜' AND char_type = 'KANJI';
