UPDATE writing_characters SET comp_details_json = '[{"w": "芻", "h": "SÔ", "d": "Cắt cỏ, người cắt cỏ.##Loài vật ăn cỏ gọi là sô.##Rơm, cỏ khô. Như sô cẩu [芻狗] con chó rút bằng rơm bằng cỏ, ý nói là vật bỏ đi. Lão Tử [老子] : Thiên địa bất nhân, dĩ vạn vật vi sô cẩu [天地不仁, 以萬物爲芻狗] (Đạo Đức Kinh [道德經]) Trời đất bất nhân, coi vạn vật như chó rơm. Từ Nhụ viếng mẹ Quách Lâm chỉ đưa có một nhúm cỏ khô, vì thế tục gọi lễ phúng là sinh sô [生芻]."}, {"w": "隹", "h": "CHUY", "d": "Một cái tên chung để gọi giống chim đuôi ngắn."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "雛芻", "word": "芻", "hanViet": "SÔ", "detail": "Cắt cỏ, người cắt cỏ.##Loài vật ăn cỏ gọi là sô.##Rơm, cỏ khô. Như sô cẩu [芻狗] con chó rút bằng rơm bằng cỏ, ý nói là vật bỏ đi. Lão Tử [老子] : Thiên địa bất nhân, dĩ vạn vật vi sô cẩu [天地不仁, 以萬物爲芻狗] (Đạo Đức Kinh [道德經]) Trời đất bất nhân, coi vạn vật như chó rơm. Từ Nhụ viếng mẹ Quách Lâm chỉ đưa có một nhúm cỏ khô, vì thế tục gọi lễ phúng là sinh sô [生芻]."}, {"id": "雛芻勹", "word": "勹", "hanViet": "BAO", "detail": "Bọc."}, {"id": "雛芻屮", "word": "屮", "hanViet": "TRIỆT", "detail": "Cây cỏ mới mọc, tức là chữ thảo [艸] cổ."}, {"id": "雛隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}], "links": [{"source": "雛", "target": "雛芻"}, {"source": "雛芻", "target": "雛芻勹"}, {"source": "雛芻", "target": "雛芻屮"}, {"source": "雛", "target": "雛隹"}]}'::jsonb WHERE character = '雛' AND char_type = 'KANJI';
