UPDATE writing_characters SET comp_details_json = '[{"w": "鳥", "h": "ĐIỂU", "d": "chim; tên gọi chung của các loài chim\nVD: 鳥獣 (chim và thú), 候鳥 (chim di cư), 野鳥 (chim hoang dã)"}, {"w": "雁", "h": "NHẠN", "d": "Chim nhạn. Chim nhạn, mùa thu lại, mùa xuân đi, cho nên gọi là hậu điểu [候鳥] chim mùa. Chim nhạn bay có thứ tự, nên anh em gọi là nhạn tự [雁序]. Có khi viết là nhạn [鴈]. Ta gọi là con chim mòng. Nguyễn Trãi [阮廌] : Cố quốc tâm quy lạc nhạn biên [故國心歸落雁邊] (Thần Phù hải khẩu [神苻海口]) Lòng mong về quê cũ theo cánh nhạn sa."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "鷹鳥", "word": "鳥", "hanViet": "ĐIỂU", "detail": "chim; tên gọi chung của các loài chim\nVD: 鳥獣 (chim và thú), 候鳥 (chim di cư), 野鳥 (chim hoang dã)"}, {"id": "鷹鳥白", "word": "白", "hanViet": "BẠCH", "detail": "1. màu trắng \nVD: 白衣 (áo trắng), 紅白 (đỏ và trắng)\n2. làm cho trắng; tẩy trắng\nVD: 精白 (tinh luyện, làm trắng), 漂白 (tẩy trắng)\n3. sáng; rõ ràng; minh bạch\nVD: 白日 (ban ngày), 明白 (rõ ràng)\n4. trong sạch; không vẩn đục \nVD: 潔白 (trong sạch)\n5. trống trơn\nVD: 白紙 (giấy trắng), 空白 (khoảng trống)\n6. lời thoại\nVD: 科白 (lời thoại)\n7. nói ra; trình bày\nVD: 白状 (thú nhận), 建白 (kiến nghị)"}, {"id": "鷹鳥白ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "鷹鳥白日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "鷹鳥丂", "word": "丂", "hanViet": "KHẢO", "detail": "Như chữ xảo [巧]."}, {"id": "鷹鳥灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}, {"id": "鷹雁", "word": "雁", "hanViet": "NHẠN", "detail": "Chim nhạn. Chim nhạn, mùa thu lại, mùa xuân 