UPDATE writing_characters SET comp_details_json = '[{"w": "穴", "h": "HUYỆT", "d": "1. lỗ; chỗ trũng\nVD: 穴居 (sống trong hang), 墓穴 (phần mộ)\n2. thâm hụt; thua lỗ (kế toán)\n3. kết quả bất ngờ\nVD: 大穴 (thắng lớn bất ngờ)\n4. huyệt đạo trên cơ thể\nVD: 灸穴 (huyệt châm cứu)\n5.  chỗ hời mà ít người biết\nVD: 穴場 (chỗ hay ít người biết)"}, {"w": "𦍌", "h": "", "d": ""}, {"w": "灬", "h": "HỎA", "d": "Một hình thức của bộ hỏa [火]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "窯穴", "word": "穴", "hanViet": "HUYỆT", "detail": "1. lỗ; chỗ trũng\nVD: 穴居 (sống trong hang), 墓穴 (phần mộ)\n2. thâm hụt; thua lỗ (kế toán)\n3. kết quả bất ngờ\nVD: 大穴 (thắng lớn bất ngờ)\n4. huyệt đạo trên cơ thể\nVD: 灸穴 (huyệt châm cứu)\n5.  chỗ hời mà ít người biết\nVD: 穴場 (chỗ hay ít người biết)"}, {"id": "窯穴ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "窯穴宀", "word": "宀", "hanViet": "MIÊN", "detail": "Lợp trùm nhà ngoài với nhà trong."}, {"id": "窯𦍌", "word": "𦍌", "hanViet": "", "detail": ""}, {"id": "窯灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}], "links": [{"source": "窯", "target": "窯穴"}, {"source": "窯穴", "target": "窯穴ハ"}, {"source": "窯穴", "target": "窯穴宀"}, {"source": "窯", "target": "窯𦍌"}, {"source": "窯", "target": "窯灬"}]}'::jsonb WHERE character = '窯' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "翟", "h": "ĐỊCH", "d": "Lông trĩ, đuôi con trĩ ở núi dài và đẹp, trong khi nhạc múa dùng cầm cho đẹp.##Cùng nghĩa với chữ địch [狄] giống rợ Địch.##Một âm là trạch. Họ Trạch."}, {"w": "光", "h": "QUANG", "d": "1. thời gian; dòng chảy thời gian\nVD: 光陰 (thời gian), 消光 (thời gian trôi qua)\n2. cảnh tượng; phong cảnh\nVD: 光景 (quang cảnh), 風光 (phong cảnh)\n3. tỏa sáng; chiếu sáng; ánh sáng; sự rực rỡ\nVD: 光線 (tia sáng), 光明 (ánh sáng), 月光 (ánh trăng)\n4. sự rực rỡ; vinh dự; danh tiếng\nVD: 光臨 (vinh dự đến), 栄光 (vinh quang)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "耀翟", "word": "翟", "hanViet": "ĐỊCH, TRẠCH", "detail": "Lông trĩ, đuôi con trĩ ở núi dài và đẹp, trong khi nhạc múa dùng cầm cho đẹp.##Cùng nghĩa với chữ địch [狄] giống rợ Địch.##Một âm là trạch. Họ Trạch."}, {"id": "耀翟隹", "word": "隹", "hanViet": "CHUY", "detail": "Một cái tên chung để gọi giống chim đuôi ngắn."}, {"id": "耀翟习", "word": "习", "hanViet": "", "detail": ""}, {"id": "耀光", "word": "光", "hanViet": "QUANG", "detail": "1. thời gian; dòng chảy thời gian\nVD: 光陰 (thời gian), 消光 (thời gian trôi qua)\n2. cảnh tượng; phong cảnh\nVD: 光景 (quang cảnh), 風光 (phong cảnh)\n3. tỏa sáng; chiếu sáng; ánh sáng; sự rực rỡ\nVD: 光線 (tia sáng), 光明 (ánh sáng), 月光 (ánh trăng)\n4. sự rực rỡ; vinh dự; danh tiếng\nVD: 光臨 (vinh dự đến), 栄光 (vinh quang)"}, {"id": "耀光小", "word": "小", "hanViet": "TIỂU", "detail": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"id": "耀光兀", "word": "兀", "hanViet": "NGỘT", "detail": "Cao mà bằng đầu. Bây giờ quen gọi là cao chót. Như đột ngột [突兀] chót vót.##Ngây ngất. Như hằng ngột ngột dĩ cùng niên [恆兀兀以窮年] thường lo đau đáu suốt năm.##Lại là lời trợ ngữ, trong các bài từ nhà Nguyên họ hay dùng.##Ngột giả [兀者] kẻ bị chặt gẫy một chân."}, {"id": "耀光兀一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "耀光兀儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}], "links": [{"source": "耀", "target": "耀翟"}, {"source": "耀翟", "target": "耀翟隹"}, {"source": "耀翟", "target": "耀翟习"}, {"source": "耀", "target": "耀光"}, {"source": "耀光", "target": "耀光小"}, {"source": "耀光", "target": "耀光兀"}, {"source": "耀光兀", "target": "耀光兀一"}, {"source": "耀光兀", "target": "耀光兀儿"}]}'::jsonb WHERE character = '耀' AND char_type = 'KANJI';
