UPDATE writing_characters SET comp_details_json = '[{"w": "辰", "h": "THẦN", "d": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"w": "日", "h": "NHẬT", "d": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "晨辰", "word": "辰", "hanViet": "THẦN, THÌN", "detail": "Chi Thần (ta đọc là Thìn); chi thứ năm trong 12 chi. Từ bảy giờ sáng cho đến chín giờ sáng gọi là giờ Thìn.##Một tiếng gọi gộp cả 12 chi. Ngày xưa lấy 12 chi ghi ngày, hết một hồi từ ngày tí cho đến ngày hợi gọi là thiếp thần [浹辰], vì thế nên ngày và giờ đều gọi là thần.##Tiếng gọi chung cả mặt trời, mặt trăng và sao.##Cùng nghĩa với chữ thần [晨]."}, {"id": "晨辰二", "word": "二", "hanViet": "NHỊ", "detail": "1. số hai\nVD: 二重 (gấp đôi), 二倍 (gấp hai lần)\n2. tiếp theo; thứ hai\nVD: 二次 (thứ hai), 二世 (thế hệ thứ hai)\n3. lại; lần thứ hai\nVD: 二度 (lần thứ hai), 二伸 (tái bút)\n4. khác; khác biệt\nVD: 二心 (hai lòng), 二言 (nói hai lời)"}, {"id": "晨辰𧘇", "word": "𧘇", "hanViet": "", "detail": ""}, {"id": "晨辰厂", "word": "厂", "hanViet": "HÁN, XƯỞNG", "detail": "Chỗ sườn núi người ta có thể ở được.##Giản thể của chữ [廠]."}, {"id": "晨日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trờ