UPDATE writing_characters SET comp_details_json = '[{"w": "晃", "h": "HOẢNG", "d": "Sáng"}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "滉晃", "word": "晃", "hanViet": "HOẢNG", "detail": "Sáng"}, {"id": "滉晃光", "word": "光", "hanViet": "QUANG", "detail": "1. thời gian; dòng chảy thời gian\nVD: 光陰 (thời gian), 消光 (thời gian trôi qua)\n2. cảnh tượng; phong cảnh\nVD: 光景 (quang cảnh), 風光 (phong cảnh)\n3. tỏa sáng; chiếu sáng; ánh sáng; sự rực rỡ\nVD: 光線 (tia sáng), 光明 (ánh sáng), 月光 (ánh trăng)\n4. sự rực rỡ; vinh dự; danh tiếng\nVD: 光臨 (vinh dự đến), 栄光 (vinh quang)"}, {"id": "滉晃光小", "word": "小", "hanViet": "TIỂU", "detail": "1. trẻ; thơ ấu\nVD: 小児 (trẻ nhỏ), 小子 (trẻ em)\n2. ít; một chút ít\nVD: 小量 (lượng nhỏ), 小康 (tạm ổn)\n3. cách nói khiêm tốn về bản thân hoặc những gì liên quan đến mình\nVD: 小生 (tôi), 小社 (công ty chúng tôi)\n4. nhỏ; bé (hình dáng, quy mô) \nVD: 小型 (cỡ nhỏ), 小国 (quốc gia nhỏ), 弱小 (yếu ớt và nhỏ bé)\n5. viết tắt của 小学生 (học sinh tiểu học)\nVD: 小六 (lớp sáu tiểu học)\n6. không đáng kể; vụn vặt; tầm thường\nVD: 小事 (việc vặt), 小市民 (tiểu tư sản)\n7.  tiền tố dùng để điều chỉnh âm điệu\nVD: 小首 (nghiêng đầu), 小川 (con suối nhỏ), 小夜 (đêm tối)"}, {"id": "滉晃光兀", "word": "兀", "hanViet": "NGỘT", "detail": "Cao mà bằng đầu. Bây giờ quen gọi là cao chót. Như đột ngột [突兀] chót vót.##Ngây ngất. Như hằng ngột ngột dĩ cùng niên [恆兀兀以窮年] thường lo đau đáu suốt năm.##Lại là lời trợ ngữ, trong các bài từ nhà Nguyên họ hay dùng.##Ngột giả [兀者] kẻ bị chặt gẫy một chân."}, {"id": "滉晃光兀一", "word": "一", "hanViet": "NHẤT", "detail": "1. một; số một; một lần\nVD: 一列 (một hàng), 一度 (một lần), 一個 (một cái)\n2. một cái nào đó\nVD: 一説 (một giả thuyết), 一夜 (một đêm), 一例 (một ví dụ)\n3. một chút; một lát\nVD: 一刻 (một khắc), 一瞬 (một khoảnh khắc), 一笑 (một nụ cười)\n4. bắt đầu; xuất sắc nhất\nVD: 一番 (nhất), 一流 (hàng đầu), 第一 (thứ nhất)\n5. chuyên tâm; chỉ; duy nhất\nVD: 一意 (một lòng), 一散 (tan tác), 専一 (chuyên tâm)\n6. hợp nhất; tất cả; toàn bộ; đồng đều\nVD: 一括 (gộp chung), 一様 (đồng đều), 均一 (đồng nhất)"}, {"id": "滉晃光兀儿", "word": "儿", "hanViet": "NHÂN, NHI, NGHÊ", "detail": "Người. Chữ nhân [人] giống người đứng, chữ nhân [儿] giống người đi.##Giản thể của chữ [兒]."}, {"id": "滉晃日", "word": "日", "hanViet": "NHẬT, NHỰT", "detail": "1. viết tắt của Nhật Bản\nVD: 日米 (Nhật - Mỹ), 駐日 (tại Nhật)\n2. Chủ nhật\n3. một ngày; một ngày một đêm; số ngày\nVD: 日給 (lương ngày), 平日 (ngày thường)\n4. mặt trời \nVD: 日光 (ánh sáng mặt trời), 落日 (mặt trời lặn)\n5. ban ngày \nVD: 日中 (ban ngày), 日夜 (ngày đêm)\n6. mỗi ngày; hằng ngày\nVD: 日常 (thường ngày), 日用 (dùng hằng ngày)\n7. viết tắt của tỉnh cổ Hyuga\nVD: 日州 (Nisshu - tỉnh Hyuga)"}, {"id": "滉氵", "word": "氵", "hanViet": "THỦY", "detail": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}], "links": [{"source": "滉", "target": "滉晃"}, {"source": "滉晃", "target": "滉晃光"}, {"source": "滉晃光", "target": "滉晃光小"}, {"source": "滉晃光", "target": "滉晃光兀"}, {"source": "滉晃光兀", "target": "滉晃光兀一"}, {"source": "滉晃光兀", "target": "滉晃光兀儿"}, {"source": "滉晃", "target": "滉晃日"}, {"source": "滉", "target": "滉氵"}]}'::jsonb WHERE character = '滉' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "欠", "h": "KHIẾM", "d": "1. (ケツ) nghỉ; hủy bỏ \nVD: 欠航 (hủy chuyến), 欠席 (vắng mặt)\n2. (ケツ) sứt; mẻ; thiếu hụt \nVD: 欠落 (thiếu hụt), 補欠 (dự bị)\n3. (ケン) ngáp\nVD: 欠伸 (ngáp)"}, {"w": "束", "h": "THÚC", "d": "1. buộc; trói\nVD: 束縛 (ràng buộc)\n2. giữ lại; trói buộc\nVD: 拘束 (giam giữ)\n3. bó; buộc thành bó\nVD: 束髪 (kiểu tóc búi phong cách phương Tây thời Meiji)\n4. đơn vị đếm các vật được bó lại\n5. đơn vị đo chiều dài mũi tên"}, {"w": "氵", "h": "THỦY", "d": "Bộ Ba chấm thủy (biến thể bộ Thủy 水: nước, sông hồ)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "漱欠", "word": "欠", "hanViet": "KHIẾM", "detail": "1. (ケツ) nghỉ; hủy bỏ \nVD: 欠航 (hủy chuyến), 欠席 (vắng mặt)\n2. (ケツ) sứt; mẻ; thiếu hụt \nVD: 欠落 (thiếu hụt), 補欠 (dự bị)\n3. (ケン) ngáp\nVD: 欠伸 (ngáp)"}, {"id": "漱欠人", "word": "人", "hanViet": "NHÂN", "detail": "1. con người; nhân loại\nVD: 人権 (nhân quyền), 人情 (tình người), 隣人 (người hàng xóm)\n2. nhân cách; tính cách\nVD: 人格 (nhân cách), 人品 (phẩm chất)\n3.  đơn vị đếm người\nVD: 一〇人 (10 người)\n4. người thuộc một nghề, lĩnh vực\nVD: 歌人 (nhà thơ), 経済人 (người làm kinh tế), 英国人 (người Anh)"}, {"id": "漱欠⺈", "word": "⺈", "hanViet": "", "detail": ""}, {"id": "漱束", "word": "束", "hanViet": "THÚC, THÚ", "detail": "1. buộc; trói\nVD: 束縛 (ràng buộc)\n2. giữ lại; trói buộc\nVD: 拘束 (giam giữ)\n3. bó; buộc thành bó\nVD: 束髪 (kiểu tóc búi phong cách phương Tây thời Meiji)\n4. đơn vị đếm các vật được bó lại\n5. đơn vị đo chiều dài mũi tên"}, {"id": "漱束口", "word": "口", "hanViet": "KHẨU", "detail": "1. miệng\nVD: 口角 (khóe miệng), 開口 (mở miệng), 鶏口 (mỏ gà)\n2. nói; lời nói\nVD: 口上 (lời nói), 口調 (giọng điệu), 悪口 (nói xấu)\n3. chủng loại; đơn vị\nVD: 口座 (tài khoản)\n4. cửa; nơi ra vào\nVD: 河口 (cửa sông), 銃口 (họng súng)\n5. sự bắt đầu; đầu mối\nVD: 糸口 (đầu sợi chỉ)\n6. số người; số hộ gia đình\nVD: 人口 (dân số), 戸口 (số hộ)\n7. đơn vị đếm kiếm, đao"}, {"id": "漱束木", "word": "木", "hanViet": "MỘC", "detail": "1. nguyên liệu gỗ\nVD: 木刀 (kiếm