UPDATE writing_characters SET comp_details_json = '[{"w": "攸", "h": "DU", "d": "Vụt, thoáng, tả cái dáng nhanh chóng. Như du nhiên nhi thệ [攸然而逝] vụt vậy mà đi.##Chốn, nơi. Như tướng du [相攸] kén nơi đáng lấy làm chồng.##Thửa, dùng làm tiếng trợ từ. Như danh tiết du quan [名節攸關] danh tiết thửa quan hệ.##Du du [攸攸] dằng dặc.##Tên người. Như Nguyễn Du [阮攸] (Việt Nam, 1765-1820)."}, {"w": "⺼", "h": "NHỤC", "d": "Bộ Nhục (thịt, biến thể giống chữ Nguyệt 月 chỉ các bộ phận cơ thể)"}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "脩攸", "word": "攸", "hanViet": "DU", "detail": "Vụt, thoáng, tả cái dáng nhanh chóng. Như du nhiên nhi thệ [攸然而逝] vụt vậy mà đi.##Chốn, nơi. Như tướng du [相攸] kén nơi đáng lấy làm chồng.##Thửa, dùng làm tiếng trợ từ. Như danh tiết du quan [名節攸關] danh tiết thửa quan hệ.##Du du [攸攸] dằng dặc.##Tên người. Như Nguyễn Du [阮攸] (Việt Nam, 1765-1820)."}, {"id": "脩攸亻", "word": "亻", "hanViet": "NHÂN", "detail": "Bộ Nhân đứng (biến thể bộ Nhân 人: con người)"}, {"id": "脩攸丨", "word": "丨", "hanViet": "CỔN", "detail": "Bộ cổn."}, {"id": "脩攸攵", "word": "攵", "hanViet": "PHÁC PHỐC PHỘC TRUY", "detail": "strike, hit, folding chair radical variant (no. 66)"}, {"id": "脩⺼", "word": "⺼", "hanViet": "NHỤC", "detail": "Bộ Nhục (thịt, biến thể giống chữ Nguyệt 月 chỉ các bộ phận cơ thể)"}], "links": [{"source": "脩", "target": "脩攸"}, {"source": "脩攸", "target": "脩攸亻"}, {"source": "脩攸", "target": "脩攸丨"}, {"source": "脩攸", "target": "脩攸攵"}, {"source": "脩", "target": "脩⺼"}]}'::jsonb WHERE character = '脩' AND char_type = 'KANJI';
