UPDATE writing_characters SET comp_details_json = '[{"w": "公", "h": "CÔNG", "d": "1. không thiên vị; đúng đắn\nVD: 公平 (công bằng), 公正 (công chính)\n2. công cộng \n(a) liên quan đến quốc gia hoặc chính phủ\nVD: 公職 (công chức), 公営 (do nhà nước quản lý), 公債 (trái phiếu nhà nước)\n(b) mang tính xã hội\nVD: 公益 (lợi ích công cộng), 公害 (ô nhiễm công cộng)\n3. chung; áp dụng cho tất cả\nVD: 公式 (công thức), 公理 (công lý)\n4. tước Công (tước vị đầu trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam))\n5. từ biểu thị sự kính trọng đối với quý nhân hoặc người khác\nVD: 貴公 (quý ông)\n6. từ biểu thị sự thân mật hoặc khinh miệt\nVD: 八公 (<i>Hachiko</i> - cách gọi thân mật hoặc coi thường)\n7. ngài; thiên tử; quân chủ; chủ nhân\nVD: 公子 (công tử)"}, {"w": "頁", "h": "HIỆT", "d": "Đầu.##Một tờ giấy gọi là nhất hiệt [一頁]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "頌公", "word": "公", "hanViet": "CÔNG", "detail": "1. không thiên vị; đúng đắn\nVD: 公平 (công bằng), 公正 (công chính)\n2. công cộng \n(a) liên quan đến quốc gia hoặc chính phủ\nVD: 公職 (công chức), 公営 (do nhà nước quản lý), 公債 (trái phiếu nhà nước)\n(b) mang tính xã hội\nVD: 公益 (lợi ích công cộng), 公害 (ô nhiễm công cộng)\n3. chung; áp dụng cho tất cả\nVD: 公式 (công thức), 公理 (công lý)\n4. tước Công (tước vị đầu trong ngũ đẳng tước (Công, Hầu, Bá, Tử, Nam))\n5. từ biểu thị sự kính trọng đối với quý nhân hoặc người khác\nVD: 貴公 (quý ông)\n6. từ biểu thị sự thân mật hoặc khinh miệt\nVD: 八公 (<i>Hachiko</i> - cách gọi thân mật hoặc coi thường)\n7. ngài; thiên tử; quân chủ; chủ nhân\nVD: 公子 (công tử)"}, {"id": "頌公ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "頌公厶", "word": "厶", "hanViet": "KHƯ", "detail": "Khư lư [去盧] đồ ăn cơm. $ Ghi chú : Dưới chữ khứ [去] theo chữ khư. Cổ văn là chữ tư, dưới chữ soán [篡], chữ nội [內] đều theo đó. Cổ văn viết là quăng [厷] tức là chữ [肱]. Lại là chữ dĩ [以] bớt nét di, tức là bên tả chữ dĩ [以], chữ [台], chữ hĩ [矣] đều theo đó."}, {"id": "頌頁", "word": "頁", "hanViet": "HIỆT", "detail": "Đầu.##Một tờ giấy gọi là nhất hiệt [一頁]."}, {"id": "頌頁丆", "word": "丆", "hanViet": "", "detail": ""}, {"id": "頌頁貝", "word": "貝", "hanViet": "BỐI", "detail": "con sò; vỏ sò\nVD: 貝貨 (tiền vỏ sò), 貝錦 (gấm hoa văn vỏ ốc), 貝勒 (bối lặc, tước hiệu quý tộc thời Thanh)"}, {"id": "頌頁貝ハ", "word": "ハ", "hanViet": "", "detail": ""}, {"id": "頌頁貝目", "word": "目", "hanViet": "MỤC", "detail": "1. mắt; con mắt\nVD: 目前 (trước mắt), 耳目 (tai mắt)\n2. nhìn; chứng kiến\nVD: 目撃 (tận mắt chứng kiến), 注目 (chú ý)\n3. người đứng đầu; chủ chốt\nVD: 頭目 (thủ lĩnh)\n4. tiêu đề; tên gọi\nVD: 目次 (mục lục), 品目 (danh mục hàng hóa)\n5. mục nhỏ; phần chia nhỏ\nVD: 科目 (môn học), 項目 (hạng mục)\n6. điểm mấu chốt; trọng điểm\nVD: 眼目 (điểm trọng yếu), 要目 (mục quan trọng)\n7. bộ (một cấp bậc trong phân loại sinh học)\nVD: 霊長目 (bộ Linh trưởng)\n8. thể diện; danh dự\nVD: 面目 (thể diện)\n9. bây giờ; hiện tại\nVD: 目下 (mục hạ)\n10. vết khía; ranh giới; đường vân\nVD: 木目 (vân gỗ)"}], "links": [{"source": "頌", "target": "頌公"}, {"source": "頌公", "target": "頌公ハ"}, {"source": "頌公", "target": "頌公厶"}, {"source": "頌", "target": "頌頁"}, {"source": "頌頁", "target": "頌頁丆"}, {"source": "頌頁", "target": "頌頁貝"}, {"source": "頌頁貝", "target": "頌頁貝ハ"}, {"source": "頌頁貝", "target": "頌頁貝目"}]}'::jsonb WHERE character = '頌' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "ノ", "h": "PHIỆT", "d": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"w": "勹", "h": "BAO", "d": "Bọc."}, {"w": "禾", "h": "HÒA", "d": "Lúa, lúa chưa cắt rơm rạ đi gọi là hòa."}, {"w": "氽", "h": "THỘN", "d": ""}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "黎ノ", "word": "ノ", "hanViet": "PHIỆT", "detail": "Nét Phiệt (nét phẩy từ phải sang trái)"}, {"id": "黎勹", "word": "勹", "hanViet": "BAO", "detail": "Bọc."}, {"id": "黎禾", "word": "禾", "hanViet": "HÒA", "detail": "Lúa, lúa chưa cắt rơm rạ đi gọi là hòa."}, {"id": "黎氽", "word": "氽", "hanViet": "", "detail": ""}], "links": [{"source": "黎", "target": "黎ノ"}, {"source": "黎", "target": "黎勹"}, {"source": "黎", "target": "黎禾"}, {"source": "黎", "target": "黎氽"}]}'::jsonb WHERE character = '黎' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "稟", "h": "BẨM", "d": "Vâng mệnh, bẩm mệnh.##Bẩm, kẻ dưới thưa việc gì với người trên xưng là bẩm. Tục viết là [禀].##Bẩm phú, tính trời phú cho.##Một âm là lẫm. Cấp lúa kho.##Dị dạng của chữ [禀]."}, {"w": "冫", "h": "BĂNG", "d": "Cùng nghĩa như chữ băng [冰] nước đá."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "凜稟", "word": "稟", "hanViet": "BẨM, LẪM", "detail": "Vâng mệnh, bẩm mệnh.##Bẩm, kẻ dưới thưa việc gì với người trên xưng là bẩm. Tục viết là [禀].##Bẩm phú, tính trời phú cho.##Một âm là lẫm. Cấp lúa kho.##Dị dạng của chữ [禀]."}, {"id": "凜冫", "word": "冫", "hanViet": "BĂNG", "detail": "Cùng nghĩa như chữ băng [冰] nước đá."}], "links": [{"source": "凜", "target": "凜稟"}, {"source": "凜", "target": "凜冫"}]}'::jsonb WHERE character = '凜' AND char_type = 'KANJI';
UPDATE writing_characters SET comp_details_json = '[{"w": "巳", "h": "TỊ", "d": "Chi Tị, chi thứ sáu trong mười hai chi.##Từ chín giờ sáng đến mười một giờ trưa là giờ Tị.##Ngày Tị đầu tháng ba gọi là ngày thượng Tị [上巳]. Tục nước Trịnh cứ ngày ấy làm lễ cầu mát."}, {"w": "臣", "h": "THẦN", "d": "1. dân chúng; nhân dân\nVD: 臣民 (thần dân)\n2. bề tôi; người hầu hạ chủ quân\nVD: 臣下 (bề tôi), 家臣 (người hầu trong nhà)\n3. <i>omi</i> (một trong các tước hiệu quý tộc cổ đại)"}, {"w": "灬", "h": "HỎA", "d": "Một hình thức của bộ hỏa [火]."}]'::jsonb, comp_graph_json = '{"nodes": [{"id": "熙巳", "word": "巳", "hanViet": "TỊ", "detail": "Chi Tị, chi thứ sáu trong mười hai chi.##Từ chín giờ sáng đến mười một giờ trưa là giờ Tị.##Ngày Tị đầu tháng ba gọi là ngày thượng Tị [上巳]. Tục nước Trịnh cứ ngày ấy làm lễ cầu mát."}, {"id": "熙巳己", "word": "己", "hanViet": "KỈ", "detail": "1. bản thân; chính mình\nVD: 自己 (bản thân), 克己 (tự kiềm chế)\n2. kỷ (can thứ sáu trong mười thiên can)\nVD: 己丑 (năm Kỷ Sửu)"}, {"id": "熙臣", "word": "臣", "hanViet": "THẦN", "detail": "1. dân chúng; nhân dân\nVD: 臣民 (thần dân)\n2. bề tôi; người hầu hạ chủ quân\nVD: 臣下 (bề tôi), 家臣 (người hầu trong nhà)\n3. <i>omi</i> (một trong các tước hiệu quý tộc cổ đại)"}, {"id": "熙灬", "word": "灬", "hanViet": "HỎA", "detail": "Một hình thức của bộ hỏa [火]."}], "links": [{"source": "熙", "target": "熙巳"}, {"source": "熙巳", "target": "熙巳己"}, {"source": "熙", "target": "熙臣"}, {"source": "熙", "target": "熙灬"}]}'::jsonb WHERE character = '熙' AND char_type = 'KANJI';
COMMIT;
